/* V6 — Celular: telas escondidas só são desenhadas quando abertas.
   hhDefer(página, função) devolve true quando a página não está visível;
   a função fica pendente e roda assim que a página for aberta. */
(function(){
  const pending=new Map();
  let flushing=false;
  const visible=id=>{
    const page=document.getElementById(id);
    if(!page)return true;
    // Só a classe: ler o estilo calculado aqui forçaria um recálculo da página.
    return page.classList.contains("active");
  };
  window.hhDefer=function(pageId,fn){
    if(flushing||visible(pageId))return false;
    if(!pending.has(pageId))pending.set(pageId,new Set());
    pending.get(pageId).add(fn);
    return true;
  };
  window.hhFlushDeferred=function(pageId){
    const list=pending.get(pageId);
    if(!list||!list.size)return;
    pending.delete(pageId);
    flushing=true;
    try{list.forEach(fn=>{try{fn();}catch(error){console.error("Desenho adiado:",error);}});}
    finally{flushing=false;}
  };
  document.addEventListener("hh:pagechange",event=>window.hhFlushDeferred(event.detail?.to));
})();
const STORAGE_KEY = "pokemon_rpg_sheet_v13";
const STORAGE_BACKUP_KEY="pokemon_rpg_sheet_v13_recovery";
const STORAGE_TIMESTAMP_KEY="pokemon_rpg_sheet_v13_timestamp";
let localSaveLoading=true,localSaveApplying=false,localSaveTimer=null,localSavePanel=null;
const localSaveStore=window.HH_LOCAL_SAVE?.create({
  env:window,
  namespace:document.getElementById('hhLocalSaveScript')?.dataset.namespace||'pokemon_hh_v5_local',
  legacy:{primary:STORAGE_KEY,backup:STORAGE_BACKUP_KEY,timestamp:STORAGE_TIMESTAMP_KEY,database:'pokemon_rpg_sheet_recovery'},
  onExternal:value=>{applyRestoredLocalState(value);showToast('✓ Fichas atualizadas com o save de outra aba.');}
});
function validSavedState(value){return !!(value&&typeof value==='object'&&Array.isArray(value.pokemon)&&value.pokemon.length&&value.pokemon.every(p=>p&&typeof p==='object'&&!Array.isArray(p)));}
function normalizeLocalSavedState(value){
  const result=clone(value),seen=new Set();
  if(!Array.isArray(result.speciesBank))result.speciesBank=[];
  for(const p of result.pokemon){
    if(p.id==null||seen.has(p.id))p.id=uid();seen.add(p.id);
    const base={hp:1,atk:1,def:1,spa:1,spd:1,spe:1};
    p.stats={...base,...(p.baseStats&&typeof p.baseStats==='object'?p.baseStats:{}),...(p.stats&&typeof p.stats==='object'?p.stats:{})};
    p.baseStats={...p.stats,...(p.baseStats&&typeof p.baseStats==='object'?p.baseStats:{})};
    if(p.name==null)p.name='Sem nome';if(p.level==null)p.level=1;
    if(p.maxHp==null)p.maxHp=p.stats.hp;if(p.currentHp==null)p.currentHp=p.maxHp;
    repairPokemonMoves(p);
  }
  if(!result.pokemon.some(p=>p.id===result.currentId))result.currentId=result.pokemon[0].id;
  return result;
}
function loadState(){
  if(localSaveStore)return normalizeLocalSavedState(localSaveStore.loadSync(defaultData));
  for(const key of [STORAGE_KEY,STORAGE_BACKUP_KEY]){
    try{const value=JSON.parse(localStorage.getItem(key)||'null');if(validSavedState(value))return normalizeLocalSavedState(value);}catch{}
  }
  return clone(defaultData);
}
function cancelPendingLocalSave(){clearTimeout(localSaveTimer);localSaveTimer=null;}
function saveState(settings={}){
  cancelPendingLocalSave();
  if(localSaveLoading||localSaveApplying)return false;
  if(localSaveStore)return localSaveStore.schedule(state,settings);
  try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));localStorage.setItem(STORAGE_TIMESTAMP_KEY,String(Date.now()));return true;}
  catch(error){showToast('Não foi possível salvar. Baixe um JSON para guardar suas fichas.');return false;}
}
async function flushLocalSave(settings={}){
  cancelPendingLocalSave();
  if(localSaveLoading||localSaveApplying)return false;
  if(localSaveStore)return localSaveStore.saveNow(state,settings);
  return saveState(settings);
}
function queueLocalSave(){
  if(localSaveLoading||localSaveApplying)return;
  localSaveStore?.markDirty();cancelPendingLocalSave();
  localSaveTimer=setTimeout(()=>saveState(),180);
}
function applyRestoredLocalState(value){
  cancelPendingLocalSave();localSaveApplying=true;
  try{
    state=normalizeLocalSavedState(value);current=getCurrent();
    normalizePokedexAppearance();normalizeSheetAppearance();normalizeAppearanceModalTab();
    ensureTrainerData();initializeUnifiedBagInventory();
    migrateSavedPokemonReworks();localizeAllPokemonAbilities();
    applyFontTheme(state.fontTheme||'standard');applyTheme(state.theme||'hazel');
    applyPokedexColor(false);applySheetPokedexMode(false);setAppearanceModalTab(state.appearanceModalTab,{save:false});
    renderAll();
  }finally{localSaveApplying=false;}
}
async function restoreRecoveryStateIfNeeded(){
  localSavePanel=window.HH_LOCAL_SAVE_UI?.mount({
    store:localSaveStore,getState:()=>state,applyState:applyRestoredLocalState,cancelPending:cancelPendingLocalSave,
    flush:flushLocalSave,export:exportAll,notify:showToast,
    retry:async()=>{
      localSaveLoading=true;cancelPendingLocalSave();localSavePanel?.setLoading(true);
      try{const result=await localSaveStore.retry(defaultData);applyRestoredLocalState(result.state);}
      finally{localSaveLoading=false;localSavePanel?.setLoading(false);}
      if(!localSaveStore.status().halted&&!localSaveStore.status().conflict)await flushLocalSave();
    }
  });
  try{
    if(localSaveStore){
      const result=await localSaveStore.boot(defaultData);applyRestoredLocalState(result.state);
      if(result.recovered)showToast('✓ Suas fichas e imagens foram recuperadas de uma cópia local.');
    }
  }catch(error){console.error('Recuperação do save:',error);showToast('O save precisa de atenção. Abra a central de save antes de continuar.');}
  finally{localSaveLoading=false;localSavePanel?.setLoading(false);}
  window.addEventListener('pagehide',()=>{
    if(!localSaveStore||localSaveLoading||!localSaveStore.status().dirty)return;
    cancelPendingLocalSave();localSaveStore.emergency(state);saveState();localSaveStore.flush();
  });
  document.addEventListener('visibilitychange',()=>{
    if(document.visibilityState==='hidden'&&!localSaveLoading&&localSaveStore?.status().dirty){cancelPendingLocalSave();localSaveStore.emergency(state);saveState();localSaveStore.flush();}
  });
  window.addEventListener('beforeunload',event=>{
    if(localSaveLoading||!localSaveStore?.status().dirty)return;
    cancelPendingLocalSave();const journal=localSaveStore.emergency(state);saveState();localSaveStore.flush();
    if(!journal){event.preventDefault();event.returnValue='';}
  });
  if(localSaveStore&&!localSaveStore.status().halted&&!localSaveStore.status().conflict)await flushLocalSave();
}


const STAT_KEYS = [
  ["hp","VIDA"],
  ["atk","ATAQUE"],
  ["def","DEFESA"],
  ["spa","ATAQUE ESP."],
  ["spd","DEFESA ESP."],
  ["spe","VELOCIDADE"]
];

const POKEMON_NATURES=[{name:"Healthy",plus:"hp",minus:"def"},{name:"Fragile",plus:"spe",minus:"hp"},{name:"Hardy",plus:"",minus:""},{name:"Lonely",plus:"atk",minus:"def"},{name:"Brave",plus:"atk",minus:"spe"},{name:"Adamant",plus:"atk",minus:"spa"},{name:"Naughty",plus:"atk",minus:"spd"},{name:"Bold",plus:"def",minus:"atk"},{name:"Docile",plus:"",minus:""},{name:"Relaxed",plus:"def",minus:"spe"},{name:"Impish",plus:"def",minus:"spa"},{name:"Lax",plus:"def",minus:"spd"},{name:"Timid",plus:"spe",minus:"atk"},{name:"Hasty",plus:"spe",minus:"def"},{name:"Serious",plus:"",minus:""},{name:"Jolly",plus:"spe",minus:"spa"},{name:"Naive",plus:"spe",minus:"spd"},{name:"Modest",plus:"spa",minus:"atk"},{name:"Mild",plus:"spa",minus:"def"},{name:"Quiet",plus:"spa",minus:"spe"},{name:"Bashful",plus:"",minus:""},{name:"Rash",plus:"spa",minus:"spd"},{name:"Calm",plus:"spd",minus:"atk"},{name:"Gentle",plus:"spd",minus:"def"},{name:"Sassy",plus:"spd",minus:"spe"},{name:"Careful",plus:"spd",minus:"spa"},{name:"Quirky",plus:"",minus:""}];

function findPokemonNature(name){
  return POKEMON_NATURES.find(n=>n.name.toLowerCase()===String(name||"").toLowerCase())||null;
}

function inferPokemonNature(plus,minus){
  if(!plus && !minus)return null;
  return POKEMON_NATURES.find(n=>n.plus===String(plus||"") && n.minus===String(minus||""))||null;
}

function natureStatLabel(stat){
  return STAT_KEYS.find(([key])=>key===stat)?.[1]||stat||"Nenhum";
}

function natureOptionLabel(nature){
  if(!nature.plus && !nature.minus)return `${nature.name} • Neutra`;
  return `${nature.name} • +${natureStatLabel(nature.plus)} / -${natureStatLabel(nature.minus)}`;
}

function applyPokemonNature(name){
  const nature=findPokemonNature(name);
  current.natureName=nature?.name||"";
  current.naturePlus=nature?.plus||"";
  current.natureMinus=nature?.minus||"";
}


