function repairPokemonMoves(p){
  if(!p || typeof p!=="object")return false;

  let changed=false;

  if(!Array.isArray(p.moves)){
    p.moves=[];
    return true;
  }

  const seen=new Set();
  const repaired=[];

  p.moves.forEach(raw=>{
    if(!raw || typeof raw!=="object"){
      changed=true;
      return;
    }

    const move=raw;

    let id=move.id==null ? "" : String(move.id).trim();
    if(!id || seen.has(id)){
      id=uid();
      changed=true;
    }

    if(String(move.id??"")!==id){
      move.id=id;
      changed=true;
    }
    seen.add(id);

    if(!String(move.name||"").trim()){
      move.name=move.apiName ? prettyName(move.apiName) : "Move";
      changed=true;
    }

    const defaults={
      type:"Normal",
      category:"Status",
      power:0,
      powerLabel:"",
      accuracy:90,
      accuracyLabel:"",
      alwaysHits:false,
      effectChance:0,
      description:"",
      source:"",
      active:false,
      autoLearnset:false,
      learnMethod:"",
      learnsetSpecies:"",
      learnsetVersionGroup:""
    };

    Object.entries(defaults).forEach(([key,value])=>{
      if(move[key]==null){
        move[key]=value;
        changed=true;
      }
    });

    if(!Array.isArray(move.tags)){move.tags=[];changed=true;}
    if(!Array.isArray(move.learnableBy)){move.learnableBy=[];changed=true;}

    move.power=Number(move.power||0);
    move.accuracy=Number(move.accuracy||0);
    move.effectChance=Number(move.effectChance||0);
    move.alwaysHits=!!move.alwaysHits;
    move.active=!!move.active;
    move.autoLearnset=!!move.autoLearnset;
    move.learnLevel=move.learnLevel==null ? null : Number(move.learnLevel);
    /* MOVE_LEVEL_LOCK_V2: golpes por nível vindos do Banco do Sistema / Pokédex GM
       também ficam bloqueados até o nível certo. */
    if(!move.autoLearnset && move.systemIntegratedSpecies && move.learnLevel>0){move.autoLearnset=true;changed=true;}

    repaired.push(move);
  });

  if(repaired.length!==p.moves.length){
    p.moves=repaired;
    changed=true;
  }

  return changed;
}



