/* V5.0 — largura ajustável da Box */
const DRAWER_WIDTH_MIN=280;
const DRAWER_WIDTH_MAX=560;
const DRAWER_WIDTH_STEP=40;

function normalizedDrawerWidth(value){
  return Math.max(
    DRAWER_WIDTH_MIN,
    Math.min(DRAWER_WIDTH_MAX,Math.round(Number(value||350)))
  );
}

function applyDrawerWidth(value,{save=true}={}){
  const width=normalizedDrawerWidth(value);
  state.drawerWidth=width;

  const app=document.getElementById("app");
  if(app)app.style.setProperty("--drawer-width",`${width}px`);

  const drawer=document.querySelector(".drawer");
  if(drawer)drawer.style.setProperty("--drawer-width",`${width}px`);

  if(save)debouncedSave();
  return width;
}

function changeDrawerWidth(delta){
  applyDrawerWidth(normalizedDrawerWidth(state.drawerWidth)+Number(delta||0));
}

function initializeDrawerResize(){
  if(state.drawerWidth==null)state.drawerWidth=350;
  applyDrawerWidth(state.drawerWidth,{save:false});

  document.getElementById("drawerShrinkBtn")?.addEventListener("click",()=>{
    changeDrawerWidth(-DRAWER_WIDTH_STEP);
  });

  document.getElementById("drawerExpandBtn")?.addEventListener("click",()=>{
    changeDrawerWidth(DRAWER_WIDTH_STEP);
  });

  const handle=document.getElementById("drawerResizeHandle");
  if(!handle)return;

  let resizing=false;

  const stop=()=>{
    if(!resizing)return;
    resizing=false;
    document.body.classList.remove("drawer-resizing");
    debouncedSave();
  };

  handle.addEventListener("pointerdown",event=>{
    if(isMobileLayout())return;
    resizing=true;
    handle.setPointerCapture?.(event.pointerId);
    document.body.classList.add("drawer-resizing");
    event.preventDefault();
  });

  handle.addEventListener("pointermove",event=>{
    if(!resizing||isMobileLayout())return;
    applyDrawerWidth(event.clientX,{save:false});
  });

  handle.addEventListener("pointerup",stop);
  handle.addEventListener("pointercancel",stop);

  handle.addEventListener("dblclick",()=>{
    applyDrawerWidth(350);
  });
}



/* V5.0 — foto do Treinador */
function trainerPhotoRatio(){
  const t=ensureTrainerData();
  const ratio=Number(t.photoRatio||0);
  return Number.isFinite(ratio)&&ratio>0?ratio:0.78;
}

function updateTrainerPhotoFrame(){
  const t=ensureTrainerData();
  const image=document.getElementById("trainerPhoto");
  const placeholder=document.getElementById("trainerAvatar");
  const frame=document.getElementById("trainerPhotoFrame");
  const remove=document.getElementById("trainerPhotoRemoveBtn");

  if(frame){
    frame.style.setProperty("--trainer-photo-ratio",String(trainerPhotoRatio()));
  }

  if(t.photo){
    if(image){
      if(image.src!==t.photo)image.src=t.photo;
      image.hidden=false;
    }
    if(placeholder)placeholder.hidden=true;
    frame?.classList.add("has-photo");
    if(remove)remove.disabled=false;
  }else{
    if(image){
      image.removeAttribute("src");
      image.hidden=true;
    }
    if(placeholder){
      placeholder.hidden=false;
      placeholder.textContent=trainerInitials();
    }
    frame?.classList.remove("has-photo");
    if(remove)remove.disabled=true;
  }
}

function compressTrainerPhoto(file){
  return new Promise((resolve,reject)=>{
    if(!file||!String(file.type||"").startsWith("image/")){
      reject(new Error("Arquivo de imagem inválido."));
      return;
    }

    const reader=new FileReader();

    reader.onerror=()=>reject(new Error("Não foi possível ler a imagem."));
    reader.onload=()=>{
      const source=String(reader.result||"");
      const image=new Image();

      image.onerror=()=>reject(new Error("A imagem não pôde ser aberta."));
      image.onload=()=>{
        const naturalWidth=Math.max(1,image.naturalWidth||image.width||1);
        const naturalHeight=Math.max(1,image.naturalHeight||image.height||1);
        const maxDimension=1000;
        const scale=Math.min(1,maxDimension/Math.max(naturalWidth,naturalHeight));
        const width=Math.max(1,Math.round(naturalWidth*scale));
        const height=Math.max(1,Math.round(naturalHeight*scale));

        const canvas=document.createElement("canvas");
        canvas.width=width;
        canvas.height=height;

        const ctx=canvas.getContext("2d",{alpha:true});
        if(!ctx){
          reject(new Error("Canvas indisponível."));
          return;
        }

        ctx.imageSmoothingEnabled=true;
        ctx.imageSmoothingQuality="high";
        ctx.drawImage(image,0,0,width,height);

        let dataUrl="";
        try{
          dataUrl=canvas.toDataURL("image/webp",0.88);
        }catch{
          dataUrl=source;
        }

        resolve({
          dataUrl,
          ratio:naturalWidth/naturalHeight
        });
      };

      image.src=source;
    };

    reader.readAsDataURL(file);
  });
}

async function setTrainerPhotoFromFile(file){
  try{
    const processed=await compressTrainerPhoto(file);
    const t=ensureTrainerData();
    t.photo=processed.dataUrl;
    t.photoRatio=processed.ratio;
    updateTrainerPhotoFrame();
    saveState();
    showToast("Foto do Treinador atualizada.");
  }catch(error){
    showToast(error?.message||"Não foi possível carregar a foto.");
  }
}

function removeTrainerPhoto(){
  const t=ensureTrainerData();
  t.photo="";
  t.photoRatio=0.78;
  updateTrainerPhotoFrame();
  saveState();
}

function ensureTrainerData(){
  if(!state.trainer||typeof state.trainer!=="object")state.trainer={};
  const t=state.trainer;

  if(t.name==null)t.name="Treinador";
  if(t.player==null)t.player="";
  if(t.age==null)t.age="";
  if(t.region==null)t.region="";
  if(t.money==null)t.money=0;
  if(t.notes==null)t.notes="";
  if(t.photo==null)t.photo="";
  if(t.photoRatio==null)t.photoRatio=0.78;

  if(!t.attributes||typeof t.attributes!=="object"){
    t.attributes={life:50,body:40,mind:30,presence:20,spirit:10};
  }

  const fallback={life:50,body:40,mind:30,presence:20,spirit:10};
  TRAINER_ATTRIBUTES.forEach(attr=>{
    if(t.attributes[attr.key]==null)t.attributes[attr.key]=fallback[attr.key];
    t.attributes[attr.key]=Math.max(0,Math.min(999,Math.trunc(Number(t.attributes[attr.key]||0))));
  });

  /* Mantém a identidade dos objetos do formulário.
     Não recriar skill/ability/badge aqui: os controles da tela guardam
     referências para estes mesmos objetos enquanto o usuário edita. */
  if(!Array.isArray(t.skills))t.skills=[];
  t.skills=t.skills.filter(skill=>skill&&typeof skill==="object");
  t.skills.forEach(skill=>{
    skill.id=String(skill.id||uid());
    skill.name=String(skill.name??"Nova Perícia");
    skill.attribute=TRAINER_ATTRIBUTES.some(attr=>attr.key===skill.attribute)?skill.attribute:"body";
    skill.grade=TRAINER_SKILL_GRADES[skill.grade]?skill.grade:"D";
    skill.note=String(skill.note??"");
  });

  if(!Array.isArray(t.exclusiveAbilities))t.exclusiveAbilities=[];
  t.exclusiveAbilities=t.exclusiveAbilities.filter(ability=>ability&&typeof ability==="object");
  t.exclusiveAbilities.forEach(ability=>{
    ability.id=String(ability.id||uid());
    ability.name=String(ability.name??"Nova Habilidade");
    ability.attribute=TRAINER_ATTRIBUTES.some(attr=>attr.key===ability.attribute)?ability.attribute:"spirit";
    ability.description=String(ability.description??"");
  });

  if(!Array.isArray(t.badges)||!t.badges.length)t.badges=createTrainerDefaultBadges();
  t.badges=t.badges.filter(badge=>badge&&typeof badge==="object");
  t.badges.forEach((badge,index)=>{
    badge.id=String(badge.id||uid());
    badge.name=String(badge.name??`Insígnia ${index+1}`);
    badge.earned=!!badge.earned;
    badge.type=TRAINER_BADGE_TYPES.includes(badge.type)?badge.type:"";
    badge.note=String(badge.note??"");
  });

  return t;
}

function trainerAttrDefinition(key){
  return TRAINER_ATTRIBUTES.find(attr=>attr.key===key)||TRAINER_ATTRIBUTES[0];
}

function trainerAttributeValue(key){
  const t=ensureTrainerData();
  return Math.max(0,Math.trunc(Number(t.attributes[key]||0)));
}

function trainerAttributePoints(key){
  return Math.floor(trainerAttributeValue(key)/10);
}

function trainerInitials(){
  const name=String(ensureTrainerData().name||"Treinador").trim();
  const parts=name.split(/\s+/).filter(Boolean);
  if(!parts.length)return "TR";
  return (parts.length===1?parts[0].slice(0,2):parts[0][0]+parts.at(-1)[0]).toUpperCase();
}

function rollTrainerD100(){
  return Math.floor(Math.random()*100)+1;
}

function trainerRollClass(roll,target){
  const critical=Math.max(0,Math.floor(Number(target||0)/4));
  if(roll<=critical)return "critical";
  if(roll<=target)return "success";
  return "failure";
}

function trainerRollLabel(roll,target){
  const cls=trainerRollClass(roll,target);
  if(cls==="critical")return "CRÍTICO";
  if(cls==="success")return "SUCESSO";
  return "FALHA";
}

function testTrainerAttribute(key){
  const def=trainerAttrDefinition(key);
  const target=trainerAttributeValue(key);
  const critical=Math.floor(target/4);
  const roll=rollTrainerD100();
  const label=trainerRollLabel(roll,target);

  showToast(`${def.label}: ${roll} • ${label} • Alvo ${target} • Crítico ≤ ${critical}`);
}


const TRAINER_SKILL_GRADE_ORDER=["E","D","C","B","A","S"];

function trainerSkillById(id){
  const t=ensureTrainerData();
  return t.skills.find(skill=>String(skill.id)===String(id))||null;
}

function trainerSkillGradeIndex(grade){
  const index=TRAINER_SKILL_GRADE_ORDER.indexOf(grade);
  return index>=0?index:1;
}

function shiftTrainerSkillGrade(id,direction){
  const skill=trainerSkillById(id);
  if(!skill)return;

  const currentIndex=trainerSkillGradeIndex(skill.grade);
  const nextIndex=Math.max(
    0,
    Math.min(
      TRAINER_SKILL_GRADE_ORDER.length-1,
      currentIndex+Number(direction||0)
    )
  );

  skill.grade=TRAINER_SKILL_GRADE_ORDER[nextIndex];
  const card=document.querySelector(`.trainer-skill-card[data-skill-id="${CSS.escape(String(id))}"]`);
  if(card)refreshTrainerSkillCard(card,skill);
  debouncedSave();
}

function refreshTrainerSkillCard(card,skill){
  if(!card||!skill)return;

  const attr=trainerAttrDefinition(skill.attribute);
  const grade=TRAINER_SKILL_GRADES[skill.grade]||TRAINER_SKILL_GRADES.D;

  const badge=card.querySelector(".trainer-skill-grade-badge");
  if(badge){
    badge.className=`trainer-skill-grade-badge grade-${skill.grade}`;
    badge.textContent=skill.grade;
  }

  const gradeSelect=card.querySelector(".trainer-skill-grade");
  if(gradeSelect&&gradeSelect.value!==skill.grade)gradeSelect.value=skill.grade;

  const attrSelect=card.querySelector(".trainer-skill-attr");
  if(attrSelect&&attrSelect.value!==skill.attribute)attrSelect.value=skill.attribute;

  const dice=card.querySelector(".trainer-skill-dice b");
  if(dice)dice.textContent=`${grade.dice}d100${grade.worst?" • PIOR":""}`;

  const rollInfo=card.querySelector(".trainer-skill-roll small");
  if(rollInfo)rollInfo.textContent=`d100 ≤ ${attr.label} (${trainerAttributeValue(skill.attribute)})`;

  const down=card.querySelector(".trainer-skill-grade-down");
  const up=card.querySelector(".trainer-skill-grade-up");
  const gradeIndex=trainerSkillGradeIndex(skill.grade);

  if(down)down.disabled=gradeIndex<=0;
  if(up)up.disabled=gradeIndex>=TRAINER_SKILL_GRADE_ORDER.length-1;
}


