function testTrainerSkill(id){
  const t=ensureTrainerData();
  const skill=t.skills.find(row=>String(row.id)===String(id));
  if(!skill)return;

  const rule=TRAINER_SKILL_GRADES[skill.grade]||TRAINER_SKILL_GRADES.D;
  const target=trainerAttributeValue(skill.attribute);
  const rolls=Array.from({length:rule.dice},rollTrainerD100);
  const successes=rolls.filter(roll=>roll<=target).length;
  const criticals=rolls.filter(roll=>roll<=Math.floor(target/4)).length;

  let resolution="";
  if(rule.worst){
    const worst=Math.max(...rolls);
    resolution=` • PIOR ${worst} (${trainerRollLabel(worst,target)})`;
  }else{
    resolution=` • ${successes}/${rule.dice} sucesso${successes===1?"":"s"}`;
  }

  const critText=criticals?` • ${criticals} crítico${criticals===1?"":"s"}`:"";
  showToast(`${skill.name} [${skill.grade}] • d100: ${rolls.join(" / ")}${resolution}${critText} • Alvo ${target}`);
}

