const TRAINER_BADGE_TYPES=[
  "",
  "Normal","Fire","Water","Electric","Grass","Ice",
  "Fighting","Poison","Ground","Flying","Psychic","Bug",
  "Rock","Ghost","Dragon","Dark","Steel","Fairy"
];

function trainerBadgePalette(type){
  if(!type){
    return {
      main:"#84949d",
      dark:"#2b353b",
      soft:"rgba(132,148,157,.12)"
    };
  }

  const palette=moveTypePalette(type);
  return {
    main:palette?.main||"#84949d",
    dark:palette?.dark||"#2b353b",
    soft:`color-mix(in srgb,${palette?.main||"#84949d"} 13%,transparent)`
  };
}

function trainerBadgeTypeOptions(selected){
  return TRAINER_BADGE_TYPES.map(type=>{
    const label=type||"Sem Tipo";
    return `<option value="${escAttr(type)}" ${type===selected?"selected":""}>${esc(label)}</option>`;
  }).join("");
}

function renderTrainerParty(){
  const strip=document.getElementById("trainerPartyStrip");
  const count=document.getElementById("trainerPartyCount");
  if(!strip)return;

  const team=state.pokemon
    .filter(p=>p.storageGroup==="team")
    .slice(0,6);

  if(count)count.textContent=`${team.length} / 6`;

  strip.innerHTML="";

  for(let index=0;index<6;index++){
    const p=team[index];

    if(!p){
      const empty=document.createElement("div");
      empty.className="trainer-party-slot empty";
      empty.innerHTML=`
        <span class="trainer-party-slot-number">${String(index+1).padStart(2,"0")}</span>
        <span class="trainer-party-empty-ball">◓</span>
        <small>VAZIO</small>
      `;
      strip.appendChild(empty);
      continue;
    }

    const type=normalizeTypeName(p.type1)||"Normal";
    const palette=moveTypePalette(type);
    const slot=document.createElement("button");
    slot.type="button";
    slot.className=`trainer-party-slot filled ${p.id===state.currentId?"current":""}`;
    slot.style.setProperty("--party-type",palette.main);
    slot.style.setProperty("--party-type-dark",palette.dark);
    slot.title=`${p.name||"Pokémon"} • Lv.${Number(p.level||1)}`;

    slot.innerHTML=`
      <span class="trainer-party-slot-number">${String(index+1).padStart(2,"0")}</span>
      <span class="trainer-party-image">
        ${displayPokemonImage(p)
          ?`<img src="${escAttr(displayPokemonImage(p))}" alt="${escAttr(p.name||"Pokémon")}" loading="lazy">`
          :`<span>◓</span>`}
      </span>
      <span class="trainer-party-copy">
        <b>${esc(p.name||"Sem nome")}</b>
        <small>Lv.${Number(p.level||1)}</small>
      </span>
    `;

    slot.addEventListener("click",()=>{
      state.currentId=p.id;
      current=getCurrent();
      renderAll();
      debouncedSave();
    });

    strip.appendChild(slot);
  }
}


