function trainerBagFilteredItems(){
  const query=String(trainerBagUi.query||"")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g,"")
    .trim()
    .toLowerCase();

  return BAG_CONSUMABLE_ITEMS.filter(item=>{
    const qty=bagQuantity(item.apiName);

    if(trainerBagUi.filter==="owned"&&qty<=0)return false;
    if(trainerBagUi.filter!=="owned"&&trainerBagUi.filter!=="all"&&item.bagGroup!==trainerBagUi.filter)return false;
    if(query&&!bagItemSearchText(item).includes(query))return false;

    return true;
  }).sort((a,b)=>{
    const qa=bagQuantity(a.apiName);
    const qb=bagQuantity(b.apiName);
    if(qa!==qb)return qb-qa;
    if(a.bagGroup!==b.bagGroup)return a.bagGroup.localeCompare(b.bagGroup);
    return a.name.localeCompare(b.name,"en");
  });
}


function formatBagQuantity(value){
  const qty=Math.max(0,Math.floor(Number(value||0)));

  if(qty<1000)return String(qty);
  if(qty<1000000){
    const short=(qty/1000).toFixed(qty<10000?1:0).replace(".",",");
    return `${short}k`;
  }

  const short=(qty/1000000).toFixed(qty<10000000?1:0).replace(".",",");
  return `${short}M`;
}

function renderTrainerBag(){
  const list=document.getElementById("trainerBagList");
  const note=document.getElementById("trainerBagNote");
  if(!list)return;

  initializeUnifiedBagInventory();

  const items=trainerBagFilteredItems();
  const ownedTotal=Object.values(state.combatBag||{}).reduce((sum,value)=>sum+Math.max(0,Number(value||0)),0);

  const owned=document.getElementById("trainerBagOwnedTotal");
  const count=document.getElementById("trainerBagCatalogCount");

  if(owned){ owned.textContent=formatBagQuantity(ownedTotal); owned.title=String(ownedTotal); }
  if(count)count.textContent=String(BAG_CONSUMABLE_ITEMS.length);

  if(note){
    note.textContent=trainerBagUi.filter==="owned"
      ?`${items.length} tipo${items.length===1?"":"s"} de item atualmente na mochila.`
      :`${items.length} registro${items.length===1?"":"s"} no catálogo selecionado.`;
  }

  list.innerHTML=items.length
    ?""
    :'<div class="empty-state trainer-empty-state">Nenhum item encontrado neste filtro.</div>';

  items.forEach(item=>{
    const qty=bagQuantity(item.apiName);
    const actionLabel=bagItemActionLabel(item);
    const usable=actionLabel==="INFO"||qty>0;

    const card=document.createElement("article");
    card.className=`trainer-bag-card group-${item.bagGroup}`;

    card.innerHTML=`
      <div class="trainer-bag-item-head">
        <span class="trainer-bag-icon">${bagItemIcon(item)}</span>
        <div>
          <b>${esc(item.name)}</b>
          <small>${esc(BAG_GROUP_LABELS[item.bagGroup]||item.categoryPt||"Item")}</small>
        </div>
        <span class="trainer-bag-owned" title="Quantidade: ${qty}">×${formatBagQuantity(qty)}</span>
      </div>

      <div class="trainer-bag-description">${esc(item.description||"Sem descrição.")}</div>

      <div class="trainer-bag-actions">
        <div class="trainer-bag-quantity">
          <button type="button" data-trainer-bag-minus>−</button>
          <input type="number" min="0" step="1" value="${qty}" />
          <button type="button" data-trainer-bag-plus>＋</button>
        </div>

        <button class="trainer-bag-use ${item.bagGroup==="balls"?"capture":""}" type="button" ${usable?"":"disabled"}>
          ${actionLabel}
        </button>
      </div>
    `;

    const input=card.querySelector(".trainer-bag-quantity input");

    card.querySelector("[data-trainer-bag-minus]").addEventListener("click",()=>{
      setBagQuantity(item.apiName,Number(input.value||0)-1);
    });

    card.querySelector("[data-trainer-bag-plus]").addEventListener("click",()=>{
      setBagQuantity(item.apiName,Number(input.value||0)+1);
    });

    input.addEventListener("change",()=>{
      setBagQuantity(item.apiName,input.value);
    });

    card.querySelector(".trainer-bag-use").addEventListener("click",()=>{
      if(!usable)return;
      if(item.bagGroup==="balls")openCaptureModal(item.apiName);
      else if(bagItemUseSpec(item))useBagItem(item.apiName);
      else showToast(`${item.name}: ${item.description||"efeito manual."}`);
    });

    list.appendChild(card);
  });
}

