function renderTrainerSummary(){
  const t=ensureTrainerData();
  const attrTotal=TRAINER_ATTRIBUTES.reduce((sum,attr)=>sum+trainerAttributeValue(attr.key),0);
  const pointTotal=TRAINER_ATTRIBUTES.reduce((sum,attr)=>sum+trainerAttributePoints(attr.key),0);
  const badgeTotal=t.badges.filter(badge=>badge.earned).length;

  const set=(id,value)=>{
    const element=document.getElementById(id);
    if(element)element.textContent=value;
  };

  set("trainerAttrTotal",String(attrTotal));
  set("trainerPointTotal",String(pointTotal));
  set("trainerSkillCount",String(t.skills.length));
  set("trainerBadgeCount",`${badgeTotal} / ${t.badges.length}`);
  set("trainerAttributeDistributionTotal",String(attrTotal));
  set("trainerGeneratedPoints",String(pointTotal));
}

