function findCustomMove(query){
  const key=normalizeApiSlug(query);
  return CUSTOM_MOVE_BANK.find(m=>normalizeApiSlug(m.name)===key)||null;
}

function customMoveToLookup(move){
  return {
    name:move.name,
    type:move.type,
    category:move.category,
    power:Number(move.power||0),
    powerLabel:move.powerLabel||"",
    accuracy:Number(move.accuracy||0),
    accuracyLabel:move.accuracyLabel||"",
    effectChance:Number(move.effectChance||0),
    description:move.description||"",
    alwaysHits:!!move.alwaysHits,
    tags:[...(move.tags||[])],
    learnableBy:[...(move.learnableBy||[])],
    learnRule:move.learnRule||"",
    source:"Sistema"
  };
}

function normalizeApiSlug(value){
  return String(value||"").trim().toLowerCase().replace(/[’']/g,"").replace(/\s+/g,"-");
}
const MOVE_EFFECT_EXACT_PT={
  "inflicts regular damage with no additional effect.":"Causa dano normal sem efeito adicional.",
  "inflicts regular damage.":"Causa dano normal.",
  "never misses.":"Este Move nunca erra.",
  "power doubles every turn this move is used in succession after the first, resetting after five turns.":"O Poder dobra a cada turno em que este Move é usado consecutivamente após o primeiro, sendo reiniciado depois de cinco turnos.",
  "user recovers half the hp inflicted on opponent.":"O usuário recupera HP equivalente à metade do dano causado ao alvo.",
  "user sleeps for two turns, completely healing itself.":"O usuário dorme por 2 turnos e recupera completamente seu HP.",
  "forces the target to switch out.":"Força o alvo a sair de campo e ser substituído.",
  "protects the user from attacks.":"Protege o usuário contra ataques.",
  "hits 2-5 times in one turn.":"Atinge de 2 a 5 vezes no mesmo turno."
};

function moveStatLabelPt(value){
  const key=String(value||"").toLowerCase().replace(/[_-]+/g," ");
  const labels={
    "attack":"Ataque",
    "defense":"Defesa",
    "special attack":"Ataque Especial",
    "special defense":"Defesa Especial",
    "speed":"Velocidade",
    "accuracy":"Precisão",
    "evasion":"Evasão"
  };
  return labels[key]||value;
}

function moveDescriptionLooksPortuguese(value){
  return /\b(usuário|alvo|golpe|dano|turno|rodada|poder|precisão|aumenta|reduz|causa|recupera|chance|estágio)\b/i
    .test(String(value||""));
}

function translateMoveEffectPt(value){
  let text=String(value||"")
    .replace(/\[(.*?)\]\{.*?\}/g,"$1")
    .replace(/\$effect_chance%?/gi,"")
    .replace(/\s+/g," ")
    .trim();

  if(!text)return "";

  const exact=MOVE_EFFECT_EXACT_PT[text.toLowerCase()];
  if(exact)return exact;

  if(moveDescriptionLooksPortuguese(text)){
    return text
      .replace(/\bMoves?\b/g,"Moves")
      .replace(/\bPower\b/g,"Poder")
      .replace(/\bAccuracy\b/g,"Precisão")
      .replace(/\bPhysical\b/g,"Físico")
      .replace(/\bSpecial\b/g,"Especial")
      .replace(/\bAttack\b/g,"Ataque")
      .replace(/\bDefense\b/g,"Defesa")
      .replace(/\bSpeed\b/g,"Velocidade");
  }

  let match=text.match(/^Has a (\d+)% chance to make the target flinch\.?$/i);
  if(match)return `Tem ${match[1]}% de chance de causar Flinch no alvo.`;

  match=text.match(/^Has a (\d+)% chance to lower the target'?s (.+?) by (one|two|three) stages?\.?$/i);
  if(match){
    const amount={one:1,two:2,three:3}[match[3].toLowerCase()]||1;
    return `Tem ${match[1]}% de chance de reduzir ${moveStatLabelPt(match[2])} do alvo em ${amount} estágio${amount===1?"":"s"}.`;
  }

  match=text.match(/^Has a (\d+)% chance to raise the user'?s (.+?) by (one|two|three) stages?\.?$/i);
  if(match){
    const amount={one:1,two:2,three:3}[match[3].toLowerCase()]||1;
    return `Tem ${match[1]}% de chance de aumentar ${moveStatLabelPt(match[2])} do usuário em ${amount} estágio${amount===1?"":"s"}.`;
  }

  match=text.match(/^Lowers the target'?s (.+?) by (one|two|three) stages?\.?$/i);
  if(match){
    const amount={one:1,two:2,three:3}[match[2].toLowerCase()]||1;
    return `Reduz ${moveStatLabelPt(match[1])} do alvo em ${amount} estágio${amount===1?"":"s"}.`;
  }

  match=text.match(/^Raises the user'?s (.+?) by (one|two|three) stages?\.?$/i);
  if(match){
    const amount={one:1,two:2,three:3}[match[2].toLowerCase()]||1;
    return `Aumenta ${moveStatLabelPt(match[1])} do usuário em ${amount} estágio${amount===1?"":"s"}.`;
  }

  match=text.match(/^Has a (\d+)% chance to (burn|poison|paralyze|freeze|confuse) the target\.?$/i);
  if(match){
    const status={
      burn:"causar Burn",
      poison:"causar Poison",
      paralyze:"causar Paralysis",
      freeze:"causar Freeze",
      confuse:"causar Confusion"
    }[match[2].toLowerCase()];
    return `Tem ${match[1]}% de chance de ${status} no alvo.`;
  }

  match=text.match(/^Power is doubled if (.+)\.?$/i);
  if(match)return `O Poder é dobrado se ${match[1]}.`;

  const replacements=[
    [/\bInflicts regular damage\b/gi,"Causa dano normal"],
    [/\bwith no additional effect\b/gi,"sem efeito adicional"],
    [/\bThis move\b/gi,"Este Move"],
    [/\bthe user\b/gi,"o usuário"],
    [/\bthe target\b/gi,"o alvo"],
    [/\bthe opponent\b/gi,"o oponente"],
    [/\bthe target's\b/gi,"do alvo"],
    [/\bthe user's\b/gi,"do usuário"],
    [/\bhas a\b/gi,"tem"],
    [/\bchance to\b/gi,"chance de"],
    [/\bpower\b/gi,"Poder"],
    [/\bdamage\b/gi,"dano"],
    [/\baccuracy\b/gi,"Precisão"],
    [/\battack\b/gi,"Ataque"],
    [/\bdefense\b/gi,"Defesa"],
    [/\bspeed\b/gi,"Velocidade"],
    [/\braises\b/gi,"aumenta"],
    [/\blowers\b/gi,"reduz"],
    [/\brecovers\b/gi,"recupera"],
    [/\brestores\b/gi,"restaura"],
    [/\bcauses\b/gi,"causa"],
    [/\bcan hit\b/gi,"pode atingir"],
    [/\bfor two turns\b/gi,"por 2 turnos"],
    [/\bfor three turns\b/gi,"por 3 turnos"],
    [/\bby one stage\b/gi,"em 1 estágio"],
    [/\bby two stages\b/gi,"em 2 estágios"],
    [/\bcritical hit\b/gi,"acerto crítico"],
    [/\bcritical hits\b/gi,"acertos críticos"],
    [/\bflinch\b/gi,"Flinch"],
    [/\bburn\b/gi,"Burn"],
    [/\bpoison\b/gi,"Poison"],
    [/\bparalysis\b/gi,"Paralysis"],
    [/\bconfusion\b/gi,"Confusion"],
    [/\bfreeze\b/gi,"Freeze"],
    [/\brecoil\b/gi,"recuo"],
    [/\bturn\b/gi,"turno"],
    [/\bturns\b/gi,"turnos"]
  ];

  replacements.forEach(([pattern,replacement])=>{text=text.replace(pattern,replacement);});
  text=text
    .replace(/\s+([,.!?])/g,"$1")
    .replace(/\bde o\b/gi,"do")
    .replace(/\bde a\b/gi,"da")
    .trim();

  return text.charAt(0).toUpperCase()+text.slice(1);
}

function moveDescriptionFromApi(data){
  const effect=(data.effect_entries||[]).find(x=>x?.language?.name==="en");
  const flavor=(data.flavor_text_entries||[]).find(x=>x?.language?.name==="en");
  let text=effect?.short_effect || effect?.effect || flavor?.flavor_text || "";
  text=String(text).replace(/\$effect_chance/g,String(data.effect_chance??0));
  return translateMoveEffectPt(text);
}
async function fetchMoveFromApi(query){
  const custom=findCustomMove(query);
  if(custom) return customMoveToLookup(custom);

  const slug=normalizeApiSlug(query);
  if(!slug) throw new Error("Digite o nome do move.");
  const res=await fetch(`https://pokeapi.co/api/v2/move/${encodeURIComponent(slug)}/`);
  if(!res.ok){
    if(res.status===404) throw new Error("Move não encontrado no Banco do Sistema nem na PokéAPI.");
    throw new Error(`Erro da PokéAPI (${res.status}).`);
  }
  const data=await res.json();
  return {
    name:prettyName(data.name),
    type:prettyName(data.type?.name||"Normal"),
    category:prettyName(data.damage_class?.name||"Status"),
    power:Number(data.power||0),
    powerLabel:"",
    accuracy:data.accuracy==null?90:Math.min(90,Number(data.accuracy||90)),
    accuracyLabel:data.accuracy==null?"Nunca erra":"",
    effectChance:Number(data.effect_chance||0),
    description:moveDescriptionFromApi(data),
    alwaysHits:data.accuracy==null,
    tags:[],
    learnableBy:[],
    learnRule:"",
    source:"PokéAPI"
  };
}
const moveLookupMeta={memory:null,training:null};

function moveLookupExtraText(move){
  const lines=[];
  if(move.accuracyLabel) lines.push(`Precisão especial: ${move.accuracyLabel}.`);
  if(move.tags?.length) lines.push(`Tags: ${move.tags.join(" • ")}.`);
  if(move.learnableBy?.length) lines.push(`Pokémon listados: ${move.learnableBy.join(", ")}.`);
  if(move.learnRule) lines.push(`Regra de aprendizado: ${move.learnRule}`);
  return lines.length?`\n\n${lines.join("\n")}`:"";
}

function applyMoveDataToForm(move,target){
  moveLookupMeta[target]={
    source:move.source||"",
    powerLabel:move.powerLabel||"",
    accuracyLabel:move.accuracyLabel||"",
    alwaysHits:!!move.alwaysHits,
    tags:[...(move.tags||[])],
    learnableBy:[...(move.learnableBy||[])],
    learnRule:move.learnRule||""
  };
  const text=(move.description||"")+moveLookupExtraText(move);
  if(target==="training"){
    setVal("trainingMoveName",move.name);setVal("trainingElementType",move.type);
    setVal("trainingCategory",move.category);setVal("trainingPower",move.power);
    setVal("trainingAccuracy",move.accuracy);setVal("trainingEffectChance",move.effectChance);
    setVal("trainingDescription",text);
  }else{
    setVal("moveName",move.name);setVal("moveType",normalizeTypeName(move.type)||"Normal");
    setVal("moveCategory",move.category);setVal("movePower",move.power);
    setVal("moveAccuracy",move.accuracy);setVal("moveEffectChance",move.effectChance);
    setVal("moveDescription",text);
  }
}
async function automateMoveLookup(target="memory"){
  const inputId=target==="training"?"trainingMoveApiLookup":"moveApiLookup";
  const statusId=target==="training"?"trainingMoveApiLookupStatus":"moveApiLookupStatus";
  const fallbackId=target==="training"?"trainingMoveName":"moveName";
  const input=document.getElementById(inputId);
  const status=document.getElementById(statusId);
  const query=(input.value||document.getElementById(fallbackId).value||"").trim();
  if(!query){status.textContent="Digite ou selecione um move.";return}
  status.textContent="Buscando dados do move...";
  try{
    const move=await fetchMoveFromApi(query);
    applyMoveDataToForm(move,target);
    input.value=move.name;
    status.textContent=`✓ ${move.name} preenchido automaticamente • ${move.source||"Banco"}${move.accuracyLabel?` • ${move.accuracyLabel}`:""}`;
    showToast(`${move.name} preenchido pelo ${move.source==="Sistema"?"Banco do Sistema":"PokéAPI"}.`);
  }catch(err){
    console.error(err);status.textContent=err.message||"Não foi possível buscar o move.";showToast(status.textContent);
  }
}

const MOVE_DETAIL_CACHE=new Map();

function resourceIdFromUrl(url){
  const match=String(url||"").match(/\/(\d+)\/?$/);
  return match?Number(match[1]):0;
}

function getLatestLevelUpLearnset(pokemonData){
  const candidates=[];
  (pokemonData.moves||[]).forEach(entry=>{
    const moveName=entry?.move?.name||"";
    (entry.version_group_details||[]).forEach(detail=>{
      if(detail?.move_learn_method?.name!=="level-up")return;
      candidates.push({
        apiName:moveName,
        name:prettyName(moveName),
        level:Number(detail.level_learned_at||0),
        order:Number(detail.order||0),
        versionGroup:detail?.version_group?.name||"",
        versionGroupId:resourceIdFromUrl(detail?.version_group?.url||"")
      });
    });
  });

  if(!candidates.length){
    return {versionGroup:"",versionGroupId:0,moves:[]};
  }

  const latestVersionGroupId=Math.max(...candidates.map(x=>x.versionGroupId||0));
  const latestCandidates=candidates.filter(x=>x.versionGroupId===latestVersionGroupId);
  const latestVersionGroup=latestCandidates[0]?.versionGroup||"";

  const byMove=new Map();
  latestCandidates.forEach(item=>{
    const key=normalizeApiSlug(item.apiName);
    const previous=byMove.get(key);
    if(!previous || item.level<previous.level || (item.level===previous.level && item.order<previous.order)){
      byMove.set(key,item);
    }
  });

  const moves=[...byMove.values()].sort((a,b)=>{
    const levelA=a.level===0?-1:a.level;
    const levelB=b.level===0?-1:b.level;
    if(levelA!==levelB)return levelA-levelB;
    if(a.order!==b.order)return a.order-b.order;
    return a.name.localeCompare(b.name);
  });

  return {versionGroup:latestVersionGroup,versionGroupId:latestVersionGroupId,moves};
}

async function fetchMoveCached(query){
  const key=normalizeApiSlug(query);
  const custom=findCustomMove(query);
  if(custom)return customMoveToLookup(custom);
  if(MOVE_DETAIL_CACHE.has(key))return clone(MOVE_DETAIL_CACHE.get(key));
  const result=await fetchMoveFromApi(query);
  MOVE_DETAIL_CACHE.set(key,clone(result));
  return clone(result);
}

async function mapWithConcurrency(items,limit,mapper){
  const results=new Array(items.length);
  let cursor=0;

  async function worker(){
    while(true){
      const index=cursor++;
      if(index>=items.length)return;
      results[index]=await mapper(items[index],index);
    }
  }

  const workers=Array.from({length:Math.min(limit,items.length)},()=>worker());
  await Promise.all(workers);
  return results;
}

function cleanPreviousFutureLearnset(oldSpecies,oldLevel){
  if(!oldSpecies)return;
  current.moves=(current.moves||[]).filter(move=>{
    if(!move.autoLearnset)return true;
    if(normalizeSpeciesKey(move.learnsetSpecies)!==normalizeSpeciesKey(oldSpecies))return true;
    if(move.active)return true;
    const required=Number(move.learnLevel||0);
    return required<=Number(oldLevel||1);
  });
}

async function importOfficialLevelUpMoves(pokemonData,oldSpecies="",oldLevel=1){
  const learnset=getLatestLevelUpLearnset(pokemonData);
  const speciesName=prettyName(pokemonData?.name||"");

  cleanPreviousFutureLearnset(oldSpecies,oldLevel);

  if(!learnset.moves.length){
    current.apiData=current.apiData||{};
    current.apiData.learnsetVersionGroup="";
    current.apiData.levelUpMoveCount=0;
    return {added:0,updated:0,total:0,versionGroup:""};
  }

  const detailedMoves=await mapWithConcurrency(learnset.moves,6,async info=>{
    try{
      const details=await fetchMoveCached(info.apiName);
      return {...info,details};
    }catch(err){
      console.error("Falha ao carregar move:",info.apiName,err);
      return {
        ...info,
        details:{
          name:info.name,
          type:"—",
          category:"Status",
          power:0,
          powerLabel:"—",
          accuracy:90,
          accuracyLabel:"",
          effectChance:0,
          description:"Não foi possível carregar os detalhes deste move automaticamente.",
          alwaysHits:false,
          tags:[],
          learnableBy:[],
          learnRule:"",
          source:"PokéAPI"
        }
      };
    }
  });

  let added=0,updated=0;

  detailedMoves.forEach(({apiName,name,level,versionGroup,details})=>{
    const key=normalizeApiSlug(name);
    const existing=(current.moves||[]).find(m=>normalizeApiSlug(m.name)===key);
    const learnMeta={
      autoLearnset:true,
      learnLevel:Number(level||0),
      learnMethod:"level-up",
      learnsetSpecies:speciesName,
      learnsetVersionGroup:versionGroup
    };

    if(existing){
      existing.autoLearnset=true;
      existing.learnLevel=Number(level||0);
      existing.learnMethod="level-up";
      existing.learnsetSpecies=speciesName;
      existing.learnsetVersionGroup=versionGroup;

      // Se já veio de uma importação automática, atualiza os dados completos.
      // Se foi criado/editado manualmente, apenas completa campos vazios e mantém a personalização.
      if(existing.source==="PokéAPI" || existing.autoImportedDetails){
        existing.type=details.type;
        existing.category=details.category;
        existing.power=Number(details.power||0);
        existing.powerLabel=details.powerLabel||"";
        existing.accuracy=Number(details.accuracy||0);
        existing.accuracyLabel=details.accuracyLabel||"";
        existing.alwaysHits=!!details.alwaysHits;
        existing.effectChance=Number(details.effectChance||0);
        existing.description=details.description||existing.description||"";
        existing.source=details.source||"PokéAPI";
        existing.tags=[...(details.tags||[])];
      }else{
        if(!existing.description)existing.description=details.description||"";
        if(!existing.type || existing.type==="—")existing.type=details.type||existing.type;
        if(!existing.category)existing.category=details.category||"Status";
        if(!Array.isArray(existing.tags) || !existing.tags.length)existing.tags=[...(details.tags||[])];
      }

      existing.autoImportedDetails=true;
      updated++;
      return;
    }

    current.moves.push({
      id:uid(),
      name:details.name||name,
      type:details.type||"—",
      category:details.category||"Status",
      power:Number(details.power||0),
      powerLabel:details.powerLabel||"",
      accuracy:Number(details.accuracy||0),
      accuracyLabel:details.accuracyLabel||"",
      alwaysHits:!!details.alwaysHits,
      effectChance:Number(details.effectChance||0),
      description:details.description||"",
      source:details.source||"PokéAPI",
      tags:[...(details.tags||[])],
      learnableBy:[...(details.learnableBy||[])],
      learnRule:details.learnRule||"",
      active:false,
      autoImportedDetails:true,
      ...learnMeta
    });
    added++;
  });

  current.apiData=current.apiData||{};
  current.apiData.learnsetVersionGroup=learnset.versionGroup;
  current.apiData.learnsetVersionGroupId=learnset.versionGroupId;
  current.apiData.levelUpMoveCount=learnset.moves.length;

  return {
    added,
    updated,
    total:learnset.moves.length,
    versionGroup:learnset.versionGroup
  };
}

function moveLearnLevelLabel(move){
  if(!move.autoLearnset)return "";
  const level=Number(move.learnLevel||0);
  return level<=0?"Inicial / Evolução":`Aprende Lv. ${level}`;
}

function isMoveLevelLocked(move){
  if(!move.autoLearnset)return false;
  const level=Number(move.learnLevel||0);
  return level>0 && Number(current.level||1)<level;
}

function renderOfficialMoveSuggestions(){
  const list=document.getElementById("officialMoveSuggestions");
  if(!list)return;
  const apiNames=current.apiData?.moveNames||[];
  const customNames=CUSTOM_MOVE_BANK.map(m=>m.name);
  const names=[...new Set([...apiNames,...customNames])];
  list.innerHTML=names.slice().sort((a,b)=>a.localeCompare(b))
    .map(n=>`<option value="${escAttr(n)}"></option>`).join("");
}
async function searchPokemonFromApi(queryOverride=null){
  clearTemporaryGimmicksForSpeciesChange();
  const input=document.getElementById("pokeApiSearch");
  const status=document.getElementById("pokeApiStatus");
  const btn=document.getElementById("pokeApiSearchBtn");
  if(typeof queryOverride==="string" && queryOverride) input.value=queryOverride;
  let query=(input.value||"").trim().toLowerCase();
  if(!query){
    status.textContent="Digite um nome ou número.";
    input.focus();
    return;
  }
  query=query.replace(/\s+/g,"-");

  /* Aegislash é uma espécie com registros de forma separados na PokéAPI.
     A busca simples deve abrir a Shield Stance como forma inicial. */
  if(query==="aegislash")query="aegislash-shield";

  status.textContent="Buscando...";
  btn.disabled=true;
  btn.textContent="Buscando...";

  const integratedSpecies=findIntegratedCustomSpecies(query);
  if(integratedSpecies){
    try{
      status.textContent=`Carregando ${integratedSpecies.name} do Banco do Sistema...`;
      applyIntegratedCustomSpecies(integratedSpecies);
      status.textContent=`✓ ${integratedSpecies.name} carregado • Fakemon do Sistema • BST ${integratedSpeciesBst(integratedSpecies)}`;
    }catch(error){
      console.error(error);
      status.textContent=error.message||"Não foi possível carregar o Pokémon personalizado.";
      showToast(status.textContent);
    }finally{
      btn.disabled=false;
      btn.textContent="Buscar";
    }
    return;
  }

  try{
    const res=await fetch(`https://pokeapi.co/api/v2/pokemon/${encodeURIComponent(query)}/`);
    if(!res.ok){
      if(res.status===404) throw new Error("Pokémon não encontrado.");
      throw new Error(`Erro da PokéAPI (${res.status}).`);
    }

    const data=await res.json();
    const rework=findPokemonRework(data.name)||findPokemonRework(data.id);
    const apiStats=pokeStatMap(data.stats);
    const resolvedStats=rework?clone(rework.baseStats):apiStats;
    const resolvedTypes=rework
      ? [...(rework.types||[])]
      : (data.types||[]).map(x=>prettyName(x.type?.name||""));

    const shouldPreserve=document.getElementById("preserveInvestedStats").checked;
    const shouldSync=document.getElementById("syncCurrentStats").checked;
    const oldSpecies=current.apiData?.pokemonName||current.name||"";
    const oldLevel=Number(current.level||1);
    const oldBase={...(current.baseStats||{})};
    const oldStats={...(current.stats||{})};
    const wasFullHp=Number(current.currentHp||0) >= Number(current.maxHp||0);
    const oldMaxHp=Number(current.maxHp||oldStats.hp||1);
    const oldCurrentHp=Number(current.currentHp||oldMaxHp);

    const abilities=(data.abilities||[]).sort((a,b)=>Number(a.slot||0)-Number(b.slot||0));
    const mainAbility=abilities.find(x=>!x.is_hidden) || abilities[0];
    const apiAbilityName=mainAbility?.ability?.name || "";
    const apiAbilityDesc=await fetchAbilityDescription(apiAbilityName);

    const apiAbilityMemory=[];
    for(const entry of abilities){
      const apiName=entry?.ability?.name||"";
      if(!apiName) continue;
      const desc=apiName===apiAbilityName ? apiAbilityDesc : await fetchAbilityDescription(apiName);
      const systemAbility=findCustomAbility(apiName);
      apiAbilityMemory.push({
        id:uid(),
        apiName,
        name:systemAbility?systemAbility.name:officialAbilityEnglishName(apiName),
        description:desc,
        hidden:!!entry.is_hidden,
        custom:false,
        source:systemAbility?"Compêndio Principal":"PokéAPI • PT-BR",
        section:systemAbility?.section||"",
        primary:!!systemAbility
      });
    }

    if(rework){
      const reworkDescription=pokemonReworkAbilityDescription(rework);
      apiAbilityMemory.unshift({
        id:uid(),
        name:rework.abilityName,
        description:reworkDescription,
        hidden:false,
        custom:false,
        source:"Sistema",
        rework:true
      });
    }

    current.name=rework?.name
      ||(String(data.species?.name||"").toLowerCase()==="aegislash"
        ?"Aegislash"
        :prettyName(data.name));
    current.dex=String(data.id);
    current.type1=resolvedTypes[0]||"";
    current.type2=resolvedTypes[1]||"";
    current.imageUrl=bestPokemonImage(data);
    current.baseStats={...resolvedStats};

    if(shouldPreserve){
      const preserved={};
      STAT_KEYS.forEach(([stat])=>{
        const previousBase=Number(oldBase[stat]||0);
        const previousCurrent=Number(oldStats[stat]||previousBase);
        const invested=Math.max(0,previousCurrent-previousBase);
        preserved[stat]=Number(resolvedStats[stat]||0)+invested;
      });
      current.stats=preserved;

      const newMaxHp=Math.max(1,Number(preserved.hp||resolvedStats.hp||1));
      const hpIncrease=newMaxHp-oldMaxHp;
      current.maxHp=newMaxHp;

      if(wasFullHp){
        current.currentHp=newMaxHp;
      }else{
        current.currentHp=Math.max(0,Math.min(newMaxHp,oldCurrentHp+Math.max(0,hpIncrease)));
      }
    }else if(shouldSync){
      current.stats={...resolvedStats};
      current.maxHp=Number(resolvedStats.hp||1);
      current.currentHp=Number(resolvedStats.hp||1);
    }

    if(rework){
      current.abilityName=rework.abilityName;
      current.abilityText=pokemonReworkAbilityDescription(rework);
      current.systemReworkVersion="2.0";
      if(rework.evolutionProfile) current.evolutionProfile=clone(rework.evolutionProfile);
    }else if(apiAbilityName){
      current.abilityName=officialAbilityEnglishName(apiAbilityName);
      if(apiAbilityDesc) current.abilityText=apiAbilityDesc;
    }

    const preservedInvestments=STAT_KEYS.reduce((acc,[stat])=>{
      acc[stat]=Math.max(0,Number(oldStats[stat]||0)-Number(oldBase[stat]||0));
      return acc;
    },{});

    current.apiData={
      source:"PokeAPI",
      pokemonId:Number(data.id),
      pokemonName:data.name,
      speciesName:data.species?.name||data.name,
      speciesUrl:data.species?.url||"",
      moveNames:(data.moves||[]).map(x=>prettyName(x.move?.name||"")).filter(Boolean),
      abilities:abilities.map(x=>({
        name:officialAbilityEnglishName(x.ability?.name||""),
        apiName:x.ability?.name||"",
        hidden:!!x.is_hidden
      })),
      systemRework:rework?{
        version:"2.0",
        name:rework.name,
        abilityName:rework.abilityName
      }:null,
      lastEvolutionTransfer:shouldPreserve?{
        fromBase:oldBase,
        toBase:{...resolvedStats},
        preservedInvestments
      }:null
    };

    if(String(data.species?.name||"").toLowerCase()==="aegislash"){
      current.aegislashStance=String(data.name||"").toLowerCase().includes("blade")?"blade":"shield";
      current.abilityName="Stance Change";
      current.abilityText="Alterna entre Shield Stance e Blade Stance. Ao alterar a instância, os valores de Attack e Defense são invertidos entre si.";
    }

    ensurePage2Data(current);
    apiAbilityMemory.forEach(newAbility=>{
      const existing=current.abilityMemory.find(a=>
        (newAbility.apiName && a.apiName===newAbility.apiName) ||
        a.name.toLowerCase()===newAbility.name.toLowerCase()
      );
      if(existing){
        if(newAbility.source==="Compêndio Principal" && newAbility.description){
          existing.description=newAbility.description;
          existing.source="Compêndio Principal";
          existing.section=newAbility.section||"";
          existing.primary=true;
          existing.rework=!!newAbility.rework;
        }else if(!existing.description && newAbility.description){
          existing.description=newAbility.description;
        }
        existing.hidden=newAbility.hidden;
      }else{
        current.abilityMemory.push(newAbility);
      }
    });

    status.textContent=`${current.name} carregado • importando movepool por nível...`;
    const learnsetResult=await importOfficialLevelUpMoves(data,oldSpecies,oldLevel);

    renderAll();
    saveState();

    const learnsetText=learnsetResult.total
      ? ` • ${learnsetResult.total} moves por nível (${prettyName(learnsetResult.versionGroup)})`
      : "";

    if(rework){
      status.textContent=`✓ ${current.name} carregado • Rework V2.0 aplicado${learnsetText}`;
      showToast(`${current.name}: Rework V2.0 + movepool por nível carregados.`);
    }else if(shouldPreserve){
      status.textContent=`✓ ${current.name} carregado • investimentos preservados${learnsetText}`;
      showToast(`${current.name} carregado com investimentos e movepool por nível.`);
    }else{
      status.textContent=`✓ ${current.name} carregado (#${data.id})${learnsetText}`;
      showToast(`${current.name} carregado com movepool por nível.`);
    }
  }catch(err){
    console.error(err);
    status.textContent=err.message || "Não foi possível consultar a PokéAPI.";
    showToast(status.textContent);
  }finally{
    btn.disabled=false;
    btn.textContent="Buscar";
  }
}

function formatEvolutionDetails(details){
  const d=(details||[])[0]||{}, parts=[];
  if(d.min_level) parts.push(`Lv. ${d.min_level}`);
  if(d.min_happiness) parts.push(`Felicidade ${d.min_happiness}+`);
  if(d.item?.name) parts.push(`Usa ${prettyName(d.item.name)}`);
  if(d.held_item?.name) parts.push(`Segurando ${prettyName(d.held_item.name)}`);
  if(d.known_move?.name) parts.push(`Conhecendo ${prettyName(d.known_move.name)}`);
  if(d.location?.name) parts.push(`Local: ${prettyName(d.location.name)}`);
  if(d.time_of_day) parts.push(`Período: ${prettyName(d.time_of_day)}`);
  if(d.trigger?.name==="trade") parts.push("Troca");
  if(d.needs_overworld_rain) parts.push("Durante chuva");
  if(d.turn_upside_down) parts.push("Condição especial");
  return parts.join(" • ")||"Condição especial / não especificada";
}
function findEvolutionNode(node,speciesName){
  if(!node)return null;
  if(normalizeSpeciesKey(node.species?.name)===normalizeSpeciesKey(speciesName)) return node;
  for(const child of (node.evolves_to||[])){
    const found=findEvolutionNode(child,speciesName);
    if(found)return found;
  }
  return null;
}
async function fetchOfficialEvolutionOptions(){
  const ref=current.apiData?.speciesName||current.apiData?.pokemonName||current.dex||current.name;
  const res=await fetch(`https://pokeapi.co/api/v2/pokemon-species/${encodeURIComponent(normalizeApiSlug(ref))}/`);
  if(!res.ok) throw new Error("Não foi possível localizar a espécie oficial.");
  const species=await res.json();
  if(!species.evolution_chain?.url)return [];
  const chainRes=await fetch(species.evolution_chain.url);
  if(!chainRes.ok) throw new Error("Não foi possível carregar a cadeia evolutiva.");
  const chain=await chainRes.json();
  const node=findEvolutionNode(chain.chain,species.name);
  if(!node)return [];
  return (node.evolves_to||[]).map(child=>({
    source:"official",name:prettyName(child.species?.name||""),
    apiName:child.species?.name||"",detail:formatEvolutionDetails(child.evolution_details)
  }));
}

function getIntegratedEvolutionOptions(){
  const species=findIntegratedCustomSpecies(
    current.apiData?.integratedSpeciesId||current.name
  );
  if(!species)return [];

  return (species.evolution?.evolvesTo||[])
    .map(next=>{
      const target=findIntegratedCustomSpecies(next.id||next.name);
      if(!target)return null;
      const level=next.level==null?null:Number(next.level);
      return {
        source:"integrated",
        name:target.name,
        species:target,
        level,
        detail:species.evolution?.method||
          (level?`Lv. ${level}`:"Evolução registrada no Banco do Sistema")
      };
    })
    .filter(Boolean);
}

function getLocalEvolutionOptions(){
  const template=findLocalSpecies(current.name);
  if(!template?.nextEvolution?.name)return [];
  const target=findLocalSpecies(template.nextEvolution.name);
  if(!target)return [];
  return [{
    source:"local",name:target.name,template:target,
    level:template.nextEvolution.level==null?null:Number(template.nextEvolution.level),
    detail:template.nextEvolution.level?`Lv. ${template.nextEvolution.level}`:"Evolução registrada no Banco Local"
  }];
}
async function openEvolutionModal(){
  const modal=document.getElementById("evolutionModal");
  const box=document.getElementById("evolutionOptions");
  const subtitle=document.getElementById("evolutionModalSubtitle");
  modal.classList.add("open");
  subtitle.textContent=`Forma atual: ${current.name}`;
  box.innerHTML='<div class="empty-state">Buscando opções de evolução...</div>';
  try{
    let options=[];
    if(current.apiData?.source==="IntegratedCustomSpecies")options=getIntegratedEvolutionOptions();
    if(!options.length && current.apiData?.source==="PokeAPI")options=await fetchOfficialEvolutionOptions();
    if(!options.length)options=getLocalEvolutionOptions();
    if(!options.length){
      box.innerHTML='<div class="empty-state">Nenhuma próxima evolução disponível para esta forma.</div>';
      return;
    }
    box.innerHTML="";
    options.forEach(opt=>{
      const row=document.createElement("div");row.className="evolution-option";
      row.innerHTML=`
        <div>
          <div class="evolution-option-name">${esc(current.name)} → ${esc(opt.name)}</div>
          <div class="evolution-option-detail">${esc(opt.detail||"")}</div>
        </div>
        <button class="btn primary">Evoluir</button>`;
      const evolveButton=row.querySelector("button");
      const levelLocked=opt.level!=null && Number(current.level||1)<Number(opt.level);
      if(levelLocked){
        evolveButton.disabled=true;
        evolveButton.textContent=`Requer Lv. ${opt.level}`;
      }

      evolveButton.onclick=async()=>{
        if(levelLocked)return;

        if(opt.source==="official"){
          document.getElementById("preserveInvestedStats").checked=true;
          document.getElementById("syncCurrentStats").checked=false;
          modal.classList.remove("open");
          await searchPokemonFromApi(opt.apiName);
        }else if(opt.source==="integrated"){
          modal.classList.remove("open");
          applyIntegratedCustomSpecies(opt.species,{
            preserveInvested:true,
            syncCurrent:false,
            fromEvolution:true
          });
          showToast(`${current.name} evoluiu através do Banco do Sistema.`);
        }else{
          applyLocalEvolution(opt.template);
          modal.classList.remove("open");
        }
      };
      box.appendChild(row);
    });
  }catch(err){
    console.error(err);
    box.innerHTML=`<div class="empty-state">${esc(err.message||"Falha ao buscar evolução.")}</div>`;
  }
}
function applyLocalEvolution(template){
  clearTemporaryGimmicksForSpeciesChange();
  const oldBase={...(current.baseStats||{})}, oldStats={...(current.stats||{})};
  const oldMax=Number(current.maxHp||oldStats.hp||1), oldHp=Number(current.currentHp||oldMax);
  const wasFull=oldHp>=oldMax, newBase={...(template.baseStats||{})}, preserved={};
  STAT_KEYS.forEach(([stat])=>{
    const invested=Math.max(0,Number(oldStats[stat]||0)-Number(oldBase[stat]||0));
    preserved[stat]=Number(newBase[stat]||0)+invested;
  });
  current.name=template.name;current.dex=template.dex||current.dex||"";
  current.type1=template.type1||"";current.type2=template.type2||"";
  current.imageUrl=template.imageUrl||current.imageUrl||"";
  current.baseStats={...newBase};current.stats=preserved;
  current.abilityName=template.abilityName||current.abilityName||"";
  current.abilityText=template.abilityText||current.abilityText||"";
  current.evolutionProfile=clone(template.evolutionProfile||current.evolutionProfile||EVOLUTION_PROFILES.medium);
  current.nextEvolution=template.nextEvolution?clone(template.nextEvolution):null;
  current.apiData={source:"Manual",custom:true,fromLocalBank:true};
  const newMax=Math.max(1,Number(preserved.hp||newBase.hp||1));
  current.maxHp=newMax;
  current.currentHp=wasFull?newMax:Math.max(0,Math.min(newMax,oldHp+Math.max(0,newMax-oldMax)));
  renderAll();saveState();
  showToast(`${current.name} evoluiu usando o Banco Local. Pontos investidos preservados.`);
}
function applySystemPokemonReworkToRecord(p){
  if(!p)return false;
  const rework=findPokemonRework(p.dex)||findPokemonRework(p.apiData?.pokemonName)||findPokemonRework(p.name);
  if(!rework)return false;

  const officialLike=
    String(p.dex||"")===String(rework.dex) ||
    p.apiData?.source==="PokeAPI";

  if(!officialLike || p.systemReworkVersion==="2.0") return false;

  const oldBase={...(p.baseStats||{})};
  const oldStats={...(p.stats||{})};
  const oldMax=Math.max(1,Number(p.maxHp||oldStats.hp||oldBase.hp||1));
  const oldHp=Math.max(0,Number(p.currentHp||oldMax));
  const wasFull=oldHp>=oldMax;

  const newStats={};
  STAT_KEYS.forEach(([stat])=>{
    const invested=Math.max(0,Number(oldStats[stat]||oldBase[stat]||0)-Number(oldBase[stat]||0));
    newStats[stat]=Number(rework.baseStats[stat]||0)+invested;
  });

  p.name=rework.name;
  p.type1=rework.types?.[0]||"";
  p.type2=rework.types?.[1]||"";
  p.baseStats=clone(rework.baseStats);
  p.stats=newStats;
  p.abilityName=rework.abilityName;
  p.abilityText=pokemonReworkAbilityDescription(rework);
  p.systemReworkVersion="2.0";
  if(rework.evolutionProfile) p.evolutionProfile=clone(rework.evolutionProfile);

  const newMax=Math.max(1,Number(newStats.hp||rework.baseStats.hp||1));
  p.maxHp=newMax;
  p.currentHp=wasFull?newMax:Math.max(0,Math.min(newMax,oldHp+Math.max(0,newMax-oldMax)));

  p.apiData=p.apiData||{};
  p.apiData.systemRework={version:"2.0",name:rework.name,abilityName:rework.abilityName};

  if(!Array.isArray(p.abilityMemory))p.abilityMemory=[];
  const existing=p.abilityMemory.find(a=>String(a.name||"").toLowerCase()===rework.abilityName.toLowerCase());
  if(existing){
    existing.description=p.abilityText;
    existing.source="Sistema";
    existing.rework=true;
  }else{
    p.abilityMemory.unshift({
      id:uid(),
      name:rework.abilityName,
      description:p.abilityText,
      hidden:false,
      custom:false,
      source:"Sistema",
      rework:true
    });
  }
  return true;
}

function migrateSavedPokemonReworks(){
  let changed=false;
  // V7 — textos no sistema de QD: abilities e itens copiados nas fichas
  const QD=window.hhQdText;
  const itemBySlug=typeof POKEAPI_ITEM_BY_SLUG!=="undefined"?POKEAPI_ITEM_BY_SLUG:null;
  const qd=t=>{if(!QD||typeof t!=="string")return t;const n=QD.convert(t);if(n!==t)changed=true;return n;};
  (state.pokemon||[]).forEach(p=>{
    if(applySystemPokemonReworkToRecord(p))changed=true;
    if(QD){
      if(p.abilityText)p.abilityText=qd(p.abilityText);
      (p.abilityMemory||[]).forEach(a=>{if(a&&a.description)a.description=qd(a.description);});
      (p.itemMemory||[]).forEach(it=>{
        if(!it)return;
        const off=it.apiName&&itemBySlug?.get(it.apiName);
        if(off&&!it.custom&&off.description&&it.description!==off.description){it.description=off.description;changed=true;}
        else if(it.description)it.description=qd(it.description);
      });
    }
    /* Fakemon do sistema que ganharam arte depois: preenche só se a ficha está sem imagem */
    if(!p.imageUrl&&p.apiData?.integratedSpeciesId){
      const sp=findIntegratedCustomSpecies(p.apiData.integratedSpeciesId);
      if(sp?.image?.dataUrl){p.imageUrl=resolveAssetUrl(sp.image.dataUrl);changed=true;}
    }
  });
  if(changed){
    saveState();
  }
}

const MEGA_OPTIONS_CACHE=new Map();

function ensureGimmicks(p=current){
  return ensurePage2Data(p).gimmicks;
}

function formatMegaDisplayName(apiName,speciesName=""){
  const raw=String(apiName||"");
  const species=String(speciesName||current.apiData?.speciesName||"").toLowerCase();
  const marker=species?`${species}-mega`:"-mega";
  let suffix="";
  if(species && raw.startsWith(marker)){
    suffix=raw.slice(marker.length).replace(/^-+/,"");
  }else{
    const parts=raw.split("-mega");
    suffix=(parts[1]||"").replace(/^-+/,"");
  }
  const base=prettyName(species||raw.split("-mega")[0]||current.name);
  return `Mega ${base}${suffix?` ${prettyName(suffix)}`:""}`;
}

function isTeraStabMove(move){
  ensureGimmicks();
  return !!(
    current.gimmicks.tera.active &&
    normalizeTypeName(move?.type) &&
    normalizeTypeName(move?.type)===normalizeTypeName(current.gimmicks.tera.type)
  );
}

function canUseZMoveWithMove(move){
  ensureGimmicks();
  const z=current.gimmicks.zMove;
  return !!(
    z.prepared &&
    !z.used &&
    move?.category!=="Status" &&
    normalizeTypeName(move?.type)===normalizeTypeName(z.type)
  );
}

function renderGimmickUI(){
  ensureGimmicks();

  const tera=current.gimmicks.tera;
  const z=current.gimmicks.zMove;
  const mega=current.gimmicks.mega;

  const teraBtn=document.getElementById("teraGimmickBtn");
  const zBtn=document.getElementById("zGimmickBtn");
  const megaBtn=document.getElementById("megaGimmickBtn");
  const overlay=document.getElementById("gimmickStatusOverlay");

  if(teraBtn)teraBtn.classList.toggle("active",!!tera.active);
  if(zBtn){
    zBtn.classList.toggle("active",!!z.prepared && !z.used);
    zBtn.classList.toggle("used",!!z.used);
  }
  if(megaBtn)megaBtn.classList.toggle("active",!!mega.active);

  if(overlay){
    const chips=[];
    if(tera.active)chips.push(`<span class="gimmick-status-chip">✦ Tera ${esc(tera.type)} • STAB +2d6</span>`);
    if(z.prepared)chips.push(`<span class="gimmick-status-chip">Z ${esc(z.type)} • ${z.used?"Usado":"Pronto"}</span>`);
    if(mega.active){
      const customId=String(mega.formName||"").startsWith("custom:")?String(mega.formName).slice(7):"";
      const customForm=customId?(mega.customForms||[]).find(x=>x.id===customId):null;
      const megaLabel=customForm?.name||formatMegaDisplayName(mega.formName,current.apiData?.speciesName);
      chips.push(`<span class="gimmick-status-chip">${esc(megaLabel)}</span>`);
    }
    overlay.innerHTML=chips.join("");
  }

  renderGimmickModalState();
}

function fillGimmickTypeSelects(){
  ["teraTypeSelect","zMoveTypeSelect"].forEach(id=>{
    const select=document.getElementById(id);
    if(!select)return;
    const previous=select.value;
    select.innerHTML=POKEMON_TYPES.map(type=>`<option value="${type}">${type}</option>`).join("");
    if(previous && POKEMON_TYPES.includes(previous))select.value=previous;
  });
}

function fillGimmickTypeSelects(){
  ["teraTypeSelect","zMoveTypeSelect","customMegaType1"].forEach(id=>{
    const select=document.getElementById(id);
    if(!select)return;
    const previous=select.value;
    select.innerHTML=POKEMON_TYPES.map(type=>`<option value="${type}">${type}</option>`).join("");
    if(previous && POKEMON_TYPES.includes(previous))select.value=previous;
  });

  const customType2=document.getElementById("customMegaType2");
  if(customType2){
    const previous=customType2.value;
    customType2.innerHTML=[
      '<option value="">Nenhum</option>',
      ...POKEMON_TYPES.map(type=>`<option value="${type}">${type}</option>`)
    ].join("");
    if(previous!==undefined)customType2.value=previous;
  }
}

function renderGimmickModalState(){
  ensureGimmicks();
  fillGimmickTypeSelects();

  const tera=current.gimmicks.tera;
  const z=current.gimmicks.zMove;
  const mega=current.gimmicks.mega;

  const teraSelect=document.getElementById("teraTypeSelect");
  const zSelect=document.getElementById("zMoveTypeSelect");
  if(teraSelect)teraSelect.value=tera.type||normalizeTypeName(current.type1)||"Normal";
  if(zSelect)zSelect.value=z.type||"Normal";

  const teraStatus=document.getElementById("teraGimmickStatus");
  const zStatus=document.getElementById("zGimmickStatus");
  const megaStatus=document.getElementById("megaGimmickStatus");
  const deactivateTeraBtn=document.getElementById("deactivateTeraBtn");
  const revertMegaBtn=document.getElementById("revertMegaBtn");
  const useZBtn=document.getElementById("usePreparedZMoveBtn");

  if(teraStatus){
    teraStatus.textContent=tera.active
      ? `Ativa: ${tera.type}. O Pokémon está como monotipo ${tera.type}; golpes ${tera.type} recebem STAB +2d6.`
      : `Inativa. Tipagem atual: ${current.type1}${current.type2?` / ${current.type2}`:""}.`;
  }
  if(deactivateTeraBtn)deactivateTeraBtn.disabled=!tera.active;

  if(zStatus){
    zStatus.textContent=!z.prepared
      ? "Nenhuma Z-Stone preparada."
      : `Z-Stone ${z.type} preparada • ${z.used?"Z-Move já utilizado nesta batalha.":"Z-Move disponível para um golpe ofensivo do mesmo tipo."}`;
  }
  if(useZBtn)useZBtn.disabled=!z.prepared || z.used;

  if(megaStatus){
    if(mega.active){
      const customId=String(mega.formName||"").startsWith("custom:")?String(mega.formName).slice(7):"";
      const customForm=customId?(mega.customForms||[]).find(x=>x.id===customId):null;
      const megaLabel=customForm?.name||formatMegaDisplayName(mega.formName,current.apiData?.speciesName);
      megaStatus.textContent=`${megaLabel} está ativa. A forma anterior está salva e pode ser restaurada.`;
    }else{
      megaStatus.textContent="Mega Evolução inativa. Escolha uma Mega oficial ou personalizada.";
    }
  }
  if(revertMegaBtn)revertMegaBtn.disabled=!mega.active;

  renderCustomMegaOptions();
}

