function activateTera(){
  ensureGimmicks();
  if(current.gimmicks.mega.active){
    showToast("Reverta a Mega Evolução antes de Terastalizar.");
    return;
  }

  const selected=normalizeTypeName(document.getElementById("teraTypeSelect").value);
  if(!selected){
    showToast("Selecione um Tera Type.");
    return;
  }

  const tera=current.gimmicks.tera;
  if(!tera.active){
    tera.snapshot={type1:current.type1||"",type2:current.type2||""};
  }

  tera.active=true;
  tera.type=selected;
  current.type1=selected;
  current.type2="";

  renderAll();
  saveState();
  showToast(`${current.name} Terastalizou para ${selected}. STAB do tipo: +2d6.`);
}

function deactivateTera({silent=false}={}){
  ensureGimmicks();
  const tera=current.gimmicks.tera;
  if(!tera.active)return;

  if(tera.snapshot){
    current.type1=tera.snapshot.type1||"";
    current.type2=tera.snapshot.type2||"";
  }

  tera.active=false;
  tera.type="";
  tera.snapshot=null;

  if(!silent){
    renderAll();
    saveState();
    showToast(`${current.name} voltou à tipagem normal.`);
  }
}

function prepareZMove(){
  ensureGimmicks();
  const selected=normalizeTypeName(document.getElementById("zMoveTypeSelect").value);
  if(!selected){
    showToast("Selecione o elemento da Z-Stone.");
    return;
  }

  current.gimmicks.zMove.prepared=true;
  current.gimmicks.zMove.type=selected;
  current.gimmicks.zMove.used=false;
  renderAll();
  saveState();
  showToast(`Z-Stone ${selected} preparada.`);
}

function consumeZMove(moveName=""){
  ensureGimmicks();
  const z=current.gimmicks.zMove;
  if(!z.prepared){
    showToast("Prepare uma Z-Stone primeiro.");
    return;
  }
  if(z.used){
    showToast("O Z-Move já foi utilizado nesta batalha.");
    return;
  }

  z.used=true;
  renderAll();
  saveState();
  showToast(moveName
    ? `Z-Move ${z.type} utilizado através de ${moveName}.`
    : `Z-Move ${z.type} marcado como utilizado.`);
}

function resetZMove(){
  ensureGimmicks();
  current.gimmicks.zMove.used=false;
  renderAll();
  saveState();
  showToast("Uso do Z-Move resetado.");
}

