const POKEAPI_ITEM_SEARCH=new Map();
function normalizeItemSearch(value){return String(value||"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").trim().toLowerCase().replace(/[’']/g,"").replace(/[^a-z0-9]+/g,"-").replace(/^-+|-+$/g,"")}
POKEAPI_ITEM_CATALOG.forEach(item=>{POKEAPI_ITEM_SEARCH.set(normalizeItemSearch(item.apiName),item);POKEAPI_ITEM_SEARCH.set(normalizeItemSearch(item.name),item)});
const ITEM_CURABLE_CONDITIONS=["Paralisado","Dormindo","Envenenado","Queimado","Confuso","Congelado"];
function officialItemByQuery(query){return POKEAPI_ITEM_SEARCH.get(normalizeItemSearch(query))||null}
function ensureItemMemoryData(p){
 if(!Array.isArray(p.itemMemory))p.itemMemory=[];
 p.itemMemory=p.itemMemory.filter(Boolean).map(item=>({id:item.id||uid(),name:String(item.name||"Item"),apiName:String(item.apiName||""),description:String(item.description||""),category:String(item.category||""),categoryPt:String(item.categoryPt||""),cost:Number(item.cost||0),flingPower:item.flingPower==null?null:Number(item.flingPower),automation:item.automation&&typeof item.automation==="object"?item.automation:null,custom:item.custom!==false,pokeApi:!!item.pokeApi,source:String(item.source||"")}));return p
}
function officialItemRecordFromCatalog(item){return {id:uid(),name:item.name,apiName:item.apiName,description:item.description||"Sem descrição mecânica registrada.",category:item.category||"",categoryPt:item.categoryPt||"Item",cost:Number(item.cost||0),flingPower:item.flingPower==null?null:Number(item.flingPower),automation:item.automation?clone(item.automation):null,custom:false,pokeApi:true,source:"PokéAPI • Adaptado H&H"}}
function pokemonHeldItemRecord(p){ensureItemMemoryData(p);const held=normalizeItemSearch(p.heldItem||"");return held?p.itemMemory.find(item=>normalizeItemSearch(item.name)===held||normalizeItemSearch(item.apiName)===held)||null:null}
function syncHeldItemFields(p=current){if(p!==current)return;const a=document.getElementById("heldItem"),b=document.getElementById("heldItemSelect");if(a)a.value=p.heldItem||"";if(b)b.value=p.heldItem||""}
function itemAutomationLabel(record){return record?.automation?.label||""}
function itemAutomationMode(record){const t=record?.automation?.trigger;if(!t)return "Manual";return t==="endRound"?"Automático • Fim da rodada":t==="hp"?"Automático • HP":t==="condition"?"Automático • Condição":t==="stage"?"Automático • Estágios":"Automático"}
function registerOfficialItem(query,{equip=false}={}){const item=officialItemByQuery(query);if(!item){showToast("Item não encontrado no catálogo PokéAPI.");return null}ensureItemMemoryData(current);let record=current.itemMemory.find(row=>row.apiName===item.apiName);if(!record){record=officialItemRecordFromCatalog(item);current.itemMemory.push(record)}else Object.assign(record,officialItemRecordFromCatalog(item),{id:record.id});if(equip){current.heldItem=record.name;syncHeldItemFields()}renderItemMemory();renderCombatPage();renderPageOverview();debouncedSave();return record}
function consumeHeldItem(p,record,reason=""){if(!p?.heldItem)return "";const name=record?.name||p.heldItem;p.heldItem="";if(p===current)syncHeldItemFields(p);return `${name} foi consumido${reason?` • ${reason}`:""}.`}
function itemFractionAmount(maxHp,num,den){return Math.max(1,Math.floor(Math.max(1,Number(maxHp||1))*Number(num||0)/Math.max(1,Number(den||1))))}
function applyItemHpDelta(p,delta){const max=Math.max(1,Number(p.maxHp||1)),before=Math.max(0,Math.min(max,Number(p.currentHp||0))),after=Math.max(0,Math.min(max,before+Number(delta||0)));p.currentHp=after;return after-before}
function applyItemStage(p,stat,amount,source){ensureCombatStageData(p);const currentStage=combatStageTotal(p,stat),requested=Math.trunc(Number(amount||0));let applied=requested;if(requested>0)applied=Math.min(requested,6-currentStage);if(requested<0)applied=Math.max(requested,-6-currentStage);if(!applied)return 0;p.stageEffects.push({id:uid(),stat,amount:applied,grantedAmount:requested,source,roundsRemaining:combatStageDurationForActivation(requested),createdRound:Math.max(1,Math.trunc(Number(state.combatRound||1)))});return applied}
function processHeldItemHpTrigger(p){const record=pokemonHeldItemRecord(p),rule=record?.automation;if(!rule||rule.trigger!=="hp")return [];const max=Math.max(1,Number(p.maxHp||1)),hp=Math.max(0,Number(p.currentHp||0));if(hp<=0)return [];const threshold=max*Number(rule.thresholdNum||0)/Math.max(1,Number(rule.thresholdDen||1));if(hp>threshold)return [];const msg=[];if(rule.kind==="healThresholdFlat"){const healed=applyItemHpDelta(p,Number(rule.amount||0));if(healed>0)msg.push(`${record.name} recuperou ${healed} HP.`)}if(rule.kind==="healThresholdFraction"){const amount=itemFractionAmount(max,rule.num,rule.den),healed=applyItemHpDelta(p,amount);if(healed>0)msg.push(`${record.name} recuperou ${healed} HP (${rule.num}/${rule.den} do HP Máximo).`)}if(rule.kind==="stageThreshold"){const applied=applyItemStage(p,rule.stat,rule.amount,record.name);if(applied)msg.push(`${record.name} aplicou ${combatStageSigned(applied)} em ${combatStageDefinition(rule.stat).label}.`)}if(rule.kind==="randomStageThreshold"){const stats=["atk","def","spa","spd","spe"],stat=stats[Math.floor(Math.random()*stats.length)],applied=applyItemStage(p,stat,rule.amount,record.name);if(applied)msg.push(`${record.name} aplicou ${combatStageSigned(applied)} em ${combatStageDefinition(stat).label}.`)}if(msg.length&&rule.consume)msg.push(consumeHeldItem(p,record));return msg.filter(Boolean)}
function processHeldItemConditionTrigger(p){const record=pokemonHeldItemRecord(p),rule=record?.automation;if(!rule||rule.trigger!=="condition")return [];if(!Array.isArray(p.conditions))p.conditions=[];const msg=[];if(rule.kind==="cureCondition"&&p.conditions.includes(rule.condition)){p.conditions=p.conditions.filter(c=>c!==rule.condition);msg.push(`${record.name} removeu ${rule.condition}.`)}if(rule.kind==="cureAnyCondition"){const before=p.conditions.length;p.conditions=p.conditions.filter(c=>!ITEM_CURABLE_CONDITIONS.includes(c));const removed=before-p.conditions.length;if(removed)msg.push(`${record.name} removeu ${removed} condição${removed===1?"":"ões"}.`)}if(msg.length&&rule.consume)msg.push(consumeHeldItem(p,record));return msg.filter(Boolean)}
function processHeldItemStageTrigger(p){const record=pokemonHeldItemRecord(p),rule=record?.automation;if(!rule||rule.trigger!=="stage"||rule.kind!=="clearNegativeStages")return [];ensureCombatStageData(p);const negatives=p.stageEffects.filter(e=>Number(e.amount||0)<0);if(!negatives.length)return [];p.stageEffects=p.stageEffects.filter(e=>Number(e.amount||0)>=0);return [`${record.name} removeu ${negatives.length} redução${negatives.length===1?"":"ões"} de estágio.`,consumeHeldItem(p,record)].filter(Boolean)}
function processHeldItemEndRound(p){const record=pokemonHeldItemRecord(p),rule=record?.automation;if(!rule||rule.trigger!=="endRound")return [];const msg=[],max=Math.max(1,Number(p.maxHp||1));if(rule.kind==="healFraction"){const healed=applyItemHpDelta(p,itemFractionAmount(max,rule.num,rule.den));if(healed>0)msg.push(`${record.name} recuperou ${healed} HP.`)}if(rule.kind==="damageFraction"){const lost=-applyItemHpDelta(p,-itemFractionAmount(max,rule.num,rule.den));if(lost>0)msg.push(`${record.name} causou ${lost} de dano ao usuário.`)}if(rule.kind==="blackSludge"){const poison=[p.type1,p.type2].some(type=>String(type||"").toLowerCase()==="poison");if(poison){const healed=applyItemHpDelta(p,itemFractionAmount(max,1,16));if(healed>0)msg.push(`Black Sludge recuperou ${healed} HP.`)}else{const lost=-applyItemHpDelta(p,-itemFractionAmount(max,1,8));if(lost>0)msg.push(`Black Sludge causou ${lost} de dano.`)}}if(rule.kind==="condition"){if(!Array.isArray(p.conditions))p.conditions=[];const blocked=rule.condition==="Queimado"?(p.conditions.includes("Queimado")||p.conditions.includes("Deep Burn")):p.conditions.includes(rule.condition);if(!blocked){p.conditions.push(rule.condition);msg.push(`${record.name} aplicou ${rule.condition}.`)}}return msg}
function processHeldItemImmediate(p){return [...processHeldItemConditionTrigger(p),...processHeldItemStageTrigger(p),...processHeldItemHpTrigger(p)]}
function refreshAfterItemAutomation(messages=[],{toast=true}={}){if(!messages.length)return;syncHeldItemFields(current);updateHp();renderConditions();renderItemMemory();renderCombatPage();renderPageOverview();renderDrawer();debouncedSave();if(toast)showToast(messages.join(" • "))}
function populatePokeApiItemCatalog(){const list=document.getElementById("pokeApiItemSuggestions"),count=document.getElementById("pokeApiItemCount");if(count)count.textContent=String(POKEAPI_ITEM_CATALOG.length);if(list)list.innerHTML=POKEAPI_ITEM_CATALOG.map(item=>`<option value="${escAttr(item.name)}" label="${escAttr(item.categoryPt)}"></option>`).join("")}
function lookupAndAddOfficialItem({equip=false}={}){const source=equip?document.getElementById("heldItem"):document.getElementById("officialItemLookup"),status=equip?document.getElementById("heldItemOfficialStatus"):document.getElementById("officialItemLookupStatus"),query=source?.value.trim()||"",item=officialItemByQuery(query);if(!item){if(status)status.textContent="Item não encontrado no catálogo PokéAPI.";showToast("Item oficial não encontrado.");return}const record=registerOfficialItem(item.name,{equip});if(status)status.textContent=`✓ ${record.name} • ${record.categoryPt} • ${itemAutomationMode(record)}`;if(!equip)source.value="";if(equip){const msg=processHeldItemImmediate(current);if(msg.length)refreshAfterItemAutomation(msg)}else showToast(`${record.name} adicionado à Memória de Itens.`)}


const COMBAT_BAG_ITEMS=[
  {key:"pokeBall",label:"Poké Ball",icon:"🔴"},
  {key:"greatBall",label:"Great Ball",icon:"🔵"},
  {key:"ultraBall",label:"Ultra Ball",icon:"🟡"},
  {key:"potion",label:"Potion",icon:"🧪"},
  {key:"superPotion",label:"Super Potion",icon:"💧"},
  {key:"hyperPotion",label:"Hyper Potion",icon:"⚗"},
  {key:"fullHeal",label:"Full Heal",icon:"✨"},
  {key:"revive",label:"Revive",icon:"◆"}
];


const COMBAT_STAGE_STATS=[
  {key:"atk",label:"Attack",short:"ATK",kind:"combat"},
  {key:"def",label:"Defense",short:"DEF",kind:"combat"},
  {key:"spa",label:"Sp.Atk",short:"SP.ATK",kind:"combat"},
  {key:"spd",label:"Sp.Def",short:"SP.DEF",kind:"combat"},
  {key:"spe",label:"Speed",short:"SPEED",kind:"combat"},
  {key:"accuracy",label:"Accuracy",short:"ACC",kind:"accuracy"},
  {key:"evasion",label:"Evasion",short:"EVA",kind:"accuracy"}
];

function clampCombatStage(value){
  return Math.max(-6,Math.min(6,Math.trunc(Number(value||0))));
}

function combatStageDefinition(key){
  return COMBAT_STAGE_STATS.find(stat=>stat.key===key)||COMBAT_STAGE_STATS[0];
}

function ensureCombatStageData(p){
  if(!Array.isArray(p.stageEffects))p.stageEffects=[];

  p.stageEffects=p.stageEffects
    .filter(effect=>effect&&combatStageDefinition(effect.stat))
    .map(effect=>({
      id:effect.id||uid(),
      stat:combatStageDefinition(effect.stat).key,
      amount:Math.trunc(Number(effect.amount||0)),
      grantedAmount:Math.trunc(Number(effect.grantedAmount??effect.amount??0)),
      source:String(effect.source||"Efeito manual"),
      roundsRemaining:effect.roundsRemaining==null
        ?null
        :Math.max(0,Math.trunc(Number(effect.roundsRemaining||0))),
      createdRound:Math.max(1,Math.trunc(Number(effect.createdRound||state.combatRound||1)))
    }))
    .filter(effect=>effect.amount!==0 && (effect.roundsRemaining==null || effect.roundsRemaining>0));

  if(p.stageTargetEvasion==null)p.stageTargetEvasion=0;
  p.stageTargetEvasion=clampCombatStage(p.stageTargetEvasion);

  return p;
}

function combatStageRawTotal(p,stat){
  ensureCombatStageData(p);
  return (p.stageEffects||[])
    .filter(effect=>effect.stat===stat)
    .reduce((sum,effect)=>sum+Number(effect.amount||0),0);
}

function combatStageTotal(p,stat){
  return clampCombatStage(combatStageRawTotal(p,stat));
}

function combatStageMultiplier(stat,stageValue){
  const stage=clampCombatStage(stageValue);
  const accuracyScale=stat==="accuracy"||stat==="evasion";

  if(stage>=0){
    return accuracyScale
      ?(3+stage)/3
      :(2+stage)/2;
  }

  const absolute=Math.abs(stage);
  return accuracyScale
    ?3/(3+absolute)
    :2/(2+absolute);
}

function combatStageMultiplierLabel(stat,stageValue){
  const multiplier=combatStageMultiplier(stat,stageValue);
  const rounded=Math.round(multiplier*100)/100;
  return `×${String(rounded).replace(".",",")}`;
}

function combatEffectiveStat(p,stat){
  ensureCombatStageData(p);

  if(stat==="hp")return Math.max(0,Math.floor(Number(p.stats?.hp||0)));

  const stage=combatStageTotal(p,stat);
  const base=(stat==="accuracy"||stat==="evasion")
    ?100
    :Math.max(0,Number(p.stats?.[stat]||0));

  return Math.floor(base*combatStageMultiplier(stat,stage));
}

function combatStageSigned(value){
  const number=Math.trunc(Number(value||0));
  return number>0?`+${number}`:String(number);
}

function combatStageDurationForActivation(requestedAmount){
  const amount=Math.trunc(Number(requestedAmount||0));
  if(amount<0)return 3;
  if(amount===1)return null;
  if(amount>=2)return 2;
  return null;
}

function combatStageDurationText(requestedAmount){
  const amount=Math.trunc(Number(requestedAmount||0));

  if(amount<0){
    return `${combatStageSigned(amount)} estágio${Math.abs(amount)===1?"":"s"} • 3 rodadas`;
  }

  if(amount===1){
    return "+1 estágio • permanente até ser removido";
  }

  return `${combatStageSigned(amount)} estágios • 2 rodadas`;
}

function combatStageConversionText(stat,effective){
  if(stat==="atk"||stat==="spa"){
    const conversion=statDice(effective);
    return `+${conversion.dice}d6${conversion.fixed?` +${conversion.fixed} fixo`:""} em dano`;
  }

  if(stat==="def"||stat==="spd"){
    const conversion=statDice(effective);
    return `-${conversion.dice}d6${conversion.fixed?` -${conversion.fixed} fixo`:""} recebido`;
  }

  if(stat==="spe"){
    return "Usado para ordem e efeitos de Speed";
  }

  if(stat==="accuracy"){
    return "Aplicado à Accuracy base do Move";
  }

  if(stat==="evasion"){
    return "Reduz a Accuracy do atacante";
  }

  return "—";
}

function effectiveMoveAccuracy(move){
  if(move?.alwaysHits){
    return {
      base:null,
      final:null,
      changed:false,
      label:move.accuracyLabel||"Nunca erra",
      detail:"Este Move nunca erra."
    };
  }

  const base=Math.max(0,Number(move?.accuracy||0));
  if(base<=0){
    return {
      base:null,
      final:null,
      changed:false,
      label:move?.accuracyLabel||"—",
      detail:"Este Move não utiliza uma rolagem normal de Accuracy."
    };
  }

  ensureCombatStageData(current);

  const accuracyStage=combatStageTotal(current,"accuracy");
  const targetEvasion=clampCombatStage(current.stageTargetEvasion||0);
  const netStage=clampCombatStage(accuracyStage-targetEvasion);
  const multiplier=combatStageMultiplier("accuracy",netStage);
  const finalAccuracy=Math.min(90,Math.max(1,Math.floor(base*multiplier)));
  const changed=accuracyStage!==0||targetEvasion!==0;

  return {
    base,
    final:finalAccuracy,
    changed,
    accuracyStage,
    targetEvasion,
    netStage,
    multiplier,
    label:changed?`${base}% → ${finalAccuracy}%`:`${base}%`,
    detail:`Accuracy ${combatStageSigned(accuracyStage)} • Evasion do alvo ${combatStageSigned(targetEvasion)} • Estágio líquido ${combatStageSigned(netStage)} • ${combatStageMultiplierLabel("accuracy",netStage)}`
  };
}

function renderCombatStageTracker(){
  const summary=document.getElementById("combatStageSummary");
  if(!summary)return;

  ensureCombatStageData(current);

  const round=Math.max(1,Math.trunc(Number(state.combatRound||1)));
  const effects=current.stageEffects||[];

  const roundLabel=document.getElementById("combatStageRound");
  const countLabel=document.getElementById("combatStageEffectCount");
  const targetEvasion=document.getElementById("combatTargetEvasion");

  if(roundLabel)roundLabel.textContent=String(round);
  if(countLabel)countLabel.textContent=String(effects.length);
  if(targetEvasion)targetEvasion.value=String(clampCombatStage(current.stageTargetEvasion||0));

  summary.innerHTML=COMBAT_STAGE_STATS.map(stat=>{
    const stage=combatStageTotal(current,stat.key);
    const base=(stat.kind==="accuracy")
      ?100
      :Math.max(0,Math.floor(Number(current.stats?.[stat.key]||0)));
    const effective=combatEffectiveStat(current,stat.key);
    const stageClass=stage>0?"positive":stage<0?"negative":"";
    const changed=stage!==0;
    const baseLabel=stat.kind==="accuracy"
      ?`REF ${base}`
      :`BASE ${base}`;
    const effectiveLabel=stat.kind==="accuracy"
      ?`${effective}%`
      :String(effective);
    const title=[
      `${stat.label}: ${base} → ${effective}`,
      `Estágio ${combatStageSigned(stage)}`,
      combatStageMultiplierLabel(stat.key,stage),
      combatStageConversionText(stat.key,effective)
    ].join(" • ");

    return `
      <div class="pokemon-stage-slot${changed?" changed":""}" data-stat="${escAttr(stat.key)}" title="${escAttr(title)}">
        <span class="pokemon-stage-slot-label">${esc(stat.short)}</span>
        <b class="pokemon-stage-slot-stage ${stageClass}">${esc(combatStageSigned(stage))}</b>
        <strong class="pokemon-stage-slot-effective">${esc(effectiveLabel)}</strong>
        <small class="pokemon-stage-slot-base">${esc(baseLabel)} • ${esc(combatStageMultiplierLabel(stat.key,stage))}</small>
      </div>
    `;
  }).join("");

  const list=document.getElementById("combatStageEffects");
  if(!list)return;

  list.innerHTML=effects.length
    ?""
    :'<div class="pokemon-stage-effect-empty">Nenhum efeito de estágio ativo.</div>';

  effects
    .slice()
    .sort((a,b)=>{
      const temporaryA=a.roundsRemaining==null?1:0;
      const temporaryB=b.roundsRemaining==null?1:0;
      return temporaryA-temporaryB || Number(a.createdRound||0)-Number(b.createdRound||0);
    })
    .forEach(effect=>{
      const stat=combatStageDefinition(effect.stat);
      const positive=effect.amount>0;
      const duration=effect.roundsRemaining==null
        ?"PERMANENTE"
        :`${effect.roundsRemaining}R`;

      const adjusted=Number(effect.grantedAmount||0)!==Number(effect.amount||0)
        ?`Solicitado ${combatStageSigned(effect.grantedAmount)}; limite aplicou ${combatStageSigned(effect.amount)}.`
        :"";

      const title=[
        effect.source||"Efeito manual",
        `${stat.label} ${combatStageSigned(effect.amount)}`,
        effect.roundsRemaining==null?"Permanente":`${effect.roundsRemaining} rodadas restantes`,
        `Aplicado na rodada ${Number(effect.createdRound||1)}`,
        adjusted
      ].filter(Boolean).join(" • ");

      const chip=document.createElement("div");
      chip.className=`pokemon-stage-effect-chip ${positive?"positive":"negative"}`;
      chip.title=title;
      chip.innerHTML=`
        <span class="pokemon-stage-effect-amount">${esc(combatStageSigned(effect.amount))}</span>
        <span class="pokemon-stage-effect-text">
          <b>${esc(stat.short)} • ${esc(duration)}</b>
          <small>${esc(effect.source||"Efeito manual")}</small>
        </span>
        <button class="pokemon-stage-effect-remove" type="button" aria-label="Remover efeito">✕</button>
      `;

      chip.querySelector(".pokemon-stage-effect-remove").addEventListener("click",()=>{
        current.stageEffects=current.stageEffects.filter(row=>row.id!==effect.id);
        refreshCombatStageCalculations();
        showToast(`${stat.label} ${combatStageSigned(effect.amount)} removido.`);
      });

      list.appendChild(chip);
    });
}

function updateCombatStageDurationPreview(){
  const amount=Number(document.getElementById("combatStageAmount")?.value||1);
  const preview=document.getElementById("combatStageDurationPreview");
  if(preview)preview.textContent=combatStageDurationText(amount);
}

function refreshCombatStageCalculations(){
  ensureCombatStageData(current);
  updateDerived();
  renderMoves();
  renderCombatPage();
  renderPageOverview();
  debouncedSave();
}

function applyCombatStageEffect(){
  ensureCombatStageData(current);

  const stat=document.getElementById("combatStageStat")?.value||"atk";
  const requestedAmount=Math.trunc(Number(document.getElementById("combatStageAmount")?.value||0));
  const source=document.getElementById("combatStageSource")?.value.trim()||"Efeito manual";

  if(!requestedAmount){
    showToast("Escolha uma quantidade diferente de 0.");
    return;
  }

  const currentStage=combatStageTotal(current,stat);
  let appliedAmount=requestedAmount;

  if(requestedAmount>0){
    appliedAmount=Math.min(requestedAmount,6-currentStage);
  }else{
    appliedAmount=Math.max(requestedAmount,-6-currentStage);
  }

  if(appliedAmount===0){
    showToast(`${combatStageDefinition(stat).label} já está no limite de ${currentStage>0?"+6":"-6"} estágios.`);
    return;
  }

  const duration=combatStageDurationForActivation(requestedAmount);

  current.stageEffects.push({
    id:uid(),
    stat,
    amount:appliedAmount,
    grantedAmount:requestedAmount,
    source,
    roundsRemaining:duration,
    createdRound:Math.max(1,Math.trunc(Number(state.combatRound||1)))
  });

  const itemMessages=requestedAmount<0?processHeldItemStageTrigger(current):[];

  const sourceInput=document.getElementById("combatStageSource");
  if(sourceInput)sourceInput.value="";

  const tools=document.getElementById("combatStageTools");
  const toggle=document.getElementById("combatStageToolsToggle");
  if(tools)tools.setAttribute("hidden","");
  if(toggle){
    toggle.setAttribute("aria-expanded","false");
    toggle.title="Aplicar novo estágio";
  }

  refreshCombatStageCalculations();

  const statName=combatStageDefinition(stat).label;
  const durationText=duration==null?"permanente":`${duration} rodadas`;
  showToast(itemMessages.length?`${statName} ${combatStageSigned(appliedAmount)} aplicado • ${itemMessages.join(" • ")}`:`${statName} ${combatStageSigned(appliedAmount)} aplicado • ${durationText}.`);
}

function recomposeCombatNegativeStages(){
  ensureCombatStageData(current);

  const removed=current.stageEffects.filter(effect=>Number(effect.amount||0)<0).length;
  if(!removed){
    showToast("Este Pokémon não possui estágios negativos.");
    return;
  }

  current.stageEffects=current.stageEffects.filter(effect=>Number(effect.amount||0)>=0);
  refreshCombatStageCalculations();
  showToast(`${current.name||"Pokémon"} gastou 1 ação e removeu todos os estágios negativos.`);
}

function endGlobalCombatRound(){
  state.combatRound=Math.max(1,Math.trunc(Number(state.combatRound||1)));

  let expiredEffects=0;
  let affectedPokemon=0;

  (state.pokemon||[]).forEach(pokemon=>{
    ensureCombatStageData(pokemon);

    let changed=false;
    pokemon.stageEffects.forEach(effect=>{
      if(effect.roundsRemaining==null)return;
      effect.roundsRemaining=Math.max(0,Number(effect.roundsRemaining||0)-1);
      changed=true;
    });

    const before=pokemon.stageEffects.length;
    pokemon.stageEffects=pokemon.stageEffects.filter(effect=>effect.roundsRemaining==null||effect.roundsRemaining>0);
    expiredEffects+=before-pokemon.stageEffects.length;

    if(changed)affectedPokemon+=1;
  });

  const heldItemMessages=processHeldItemEndRound(current);
  state.combatRound+=1;
  current=getCurrent();
  renderAll();
  saveState();
  const itemText=heldItemMessages.length?` • Item: ${heldItemMessages.join(" • ")}`:"";
  showToast(`Rodada ${state.combatRound-1} encerrada • ${expiredEffects} efeito${expiredEffects===1?" expirou":"s expiraram"} • ${affectedPokemon} Pokémon processado${affectedPokemon===1?"":"s"}${itemText}.`);
}




/* V5.0 — Aegislash • Stance Change */
function isAegislashPokemon(p=current){
  if(!p)return false;

  const dex=Number(p.dex||p.apiData?.pokemonId||0);
  const species=String(p.apiData?.speciesName||"").toLowerCase();
  const apiName=String(p.apiData?.pokemonName||"").toLowerCase();
  const name=String(p.name||"").toLowerCase();

  return dex===681
    ||species==="aegislash"
    ||apiName.startsWith("aegislash")
    ||name==="aegislash"
    ||name.startsWith("aegislash ");
}

function aegislashStanceLabel(value){
  return value==="blade"?"Blade Stance":"Shield Stance";
}

function renderAegislashStance(){
  const panel=document.getElementById("aegislashStancePanel");
  if(!panel)return;

  const active=isAegislashPokemon(current);
  panel.hidden=!active;
  panel.classList.toggle("blade",active&&current.aegislashStance==="blade");

  if(!active)return;

  ensurePage2Data(current);

  const stance=current.aegislashStance==="blade"?"blade":"shield";
  const next=stance==="shield"?"Blade Stance":"Shield Stance";

  const title=document.getElementById("aegislashStanceTitle");
  const hint=document.getElementById("aegislashStanceHint");
  const atk=document.getElementById("aegislashStanceAtk");
  const def=document.getElementById("aegislashStanceDef");
  const nextLabel=document.getElementById("aegislashStanceNext");

  if(title)title.textContent=aegislashStanceLabel(stance);
  if(hint){
    hint.textContent=stance==="shield"
      ?"Forma defensiva atual. Ao alterar, Attack e Defense serão invertidos."
      :"Forma ofensiva atual. Ao alterar, Attack e Defense serão invertidos.";
  }
  if(atk)atk.textContent=String(Number(current.stats?.atk||0));
  if(def)def.textContent=String(Number(current.stats?.def||0));
  if(nextLabel)nextLabel.textContent=`Ir para ${next}`;
}

function toggleAegislashStance(){
  if(!isAegislashPokemon(current))return;

  ensurePage2Data(current);

  if(!current.stats||typeof current.stats!=="object")current.stats={};
  if(!current.baseStats||typeof current.baseStats!=="object")current.baseStats={};

  /* O efeito pedido é literal: Attack vira Defense e Defense vira Attack.
     Trocamos Base + Status atual para manter investimentos coerentes ao alternar. */
  const currentAtk=Number(current.stats.atk||0);
  const currentDef=Number(current.stats.def||0);
  current.stats.atk=currentDef;
  current.stats.def=currentAtk;

  const baseAtk=Number(current.baseStats.atk||0);
  const baseDef=Number(current.baseStats.def||0);
  current.baseStats.atk=baseDef;
  current.baseStats.def=baseAtk;

  current.aegislashStance=current.aegislashStance==="blade"?"shield":"blade";

  current.abilityName="Stance Change";
  current.abilityText="Alterna entre Shield Stance e Blade Stance. Ao alterar a instância, os valores de Attack e Defense são invertidos entre si.";

  renderStats();
  renderBaseStatsSummary();
  renderCombatPage();
  renderPageOverview();
  drawRadar();
  debouncedSave();

  showToast(`Aegislash mudou para ${aegislashStanceLabel(current.aegislashStance)}.`);
}


const COMBAT_ARENAS={
  standard:{label:"Padrão"},
  desert:{label:"Deserto"},
  water:{label:"Água"},
  night:{label:"Noite"},
  rain:{label:"Padrão na Chuva"},
  forest:{label:"Floresta Densa"},
  sky:{label:"Céu"},
  cave:{label:"Caverna"},
  volcanic:{label:"Vulcânico"},
  temple:{label:"Templo"},
  city:{label:"Cidade"},
  mountain:{label:"Montanha"},
  ocean:{label:"Oceano"}
};

function normalizeCombatArena(value){
  const key=String(value||"standard").toLowerCase();
  return COMBAT_ARENAS[key]?key:"standard";
}

function applyCombatArena(){
  const screen=document.querySelector(".combat-screen");
  const select=document.getElementById("combatArenaSelect");
  if(!screen)return;

  current.combatArena=normalizeCombatArena(current.combatArena);
  screen.dataset.arena=current.combatArena;

  if(select)select.value=current.combatArena;
}

function renderCombatPage(){
  if(window.hhDefer?.("page2",renderCombatPage))return;
  const name=document.getElementById("combatPokemonName");
  if(!name)return;

  ensurePage2Data(current);
  applyCombatArena();

  name.textContent=current.name||"Pokémon";
  document.getElementById("combatLevel").textContent=`Lv. ${Number(current.level||1)}`;
  document.getElementById("combatHpText").textContent=`${Math.max(0,Number(current.currentHp||0))} / ${Math.max(1,Number(current.maxHp||1))}`;

  const typeBox=document.getElementById("combatTypeBadges");
  const types=[normalizeTypeName(current.type1),normalizeTypeName(current.type2)].filter(Boolean);
  typeBox.innerHTML=types.length?types.map(type=>typeIconHtml(type,true)).join(""):'<span class="tag">Sem Tipo</span>';

  const img=document.getElementById("combatPortraitImg");
  const empty=document.getElementById("combatPortraitEmpty");
  const combatSrc=displayPokemonImage(current);
  if(combatSrc){
    if(img.getAttribute("src")!==combatSrc)img.src=combatSrc;
    img.hidden=false;
    empty.hidden=true;
  }else{
    img.hidden=true;
    empty.hidden=false;
  }

  document.getElementById("combatAbilityName").textContent=current.abilityName||"Sem Ability";
  document.getElementById("combatAbilityText").textContent=current.abilityText||"Nenhum efeito registrado.";

  renderAegislashStance();

  const heldName=current.heldItem||"";
  const heldRecord=(current.itemMemory||[]).find(item=>
    String(item.name||"").toLowerCase()===heldName.toLowerCase()
  );
  document.getElementById("combatHeldItemName").textContent=heldName||"Nenhum item";
  const heldDescription=heldRecord?.description||"Sem descrição registrada. Edite o item em Miscelâneas.";
  const heldAutomation=itemAutomationLabel(heldRecord);
  document.getElementById("combatHeldItemText").textContent=heldName
    ? `${heldDescription}${heldAutomation?`\n\n⚙ ${itemAutomationMode(heldRecord)} — ${heldAutomation}`:""}`
    : "Este Pokémon não está segurando um item.";

  renderCombatStatusAndItemUi();

  applyCombatItemUi();
  applyCombatExtraPanelsUi();
  renderCombatParty();
  renderCombatBag();
  renderCombatStageTracker();
  updateCombatHp();
}

function updateCombatHp(){
  const fill=document.getElementById("combatHpFill");
  const text=document.getElementById("combatHpText");
  if(!fill||!text)return;

  const currentHp=Math.max(0,Number(current.currentHp||0));
  const maximum=Math.max(1,Number(current.maxHp||1));
  const percentage=Math.max(0,Math.min(100,currentHp/maximum*100));

  fill.style.width=`${percentage}%`;
  fill.classList.toggle("hp-warning",percentage<=50&&percentage>=25);
  fill.classList.toggle("hp-danger",percentage<25);
  text.textContent=`${currentHp} / ${maximum}`;

  const controlValue=document.getElementById("combatHpControlValue");
  const controlPercent=document.getElementById("combatHpControlPercent");
  const controlFill=document.getElementById("combatControlHpFill");

  if(controlValue)controlValue.textContent=`${currentHp} / ${maximum}`;
  if(controlPercent){
    controlPercent.textContent=`${Math.round(percentage)}%`;
    controlPercent.style.color=percentage<25?"#ef565d":percentage<=50?"#e1b72c":"#62c778";
  }
  if(controlFill){
    controlFill.style.width=`${percentage}%`;
    controlFill.classList.toggle("hp-warning",percentage<=50&&percentage>=25);
    controlFill.classList.toggle("hp-danger",percentage<25);
  }
}


function readCombatHpAmount(){
  const input=document.getElementById("combatHpAmount");
  const value=Math.max(1,Math.floor(Number(input?.value||1)));
  if(input)input.value=value;
  return value;
}

function setCombatHpAmount(value){
  const input=document.getElementById("combatHpAmount");
  if(input)input.value=Math.max(1,Math.floor(Number(value||1)));
}

function flashCombatHpAction(kind){
  const screen=document.querySelector(".combat-screen");
  if(!screen)return;

  screen.classList.remove("hp-flash-damage","hp-flash-heal");
  void screen.offsetWidth;
  screen.classList.add(kind==="damage"?"hp-flash-damage":"hp-flash-heal");

  window.setTimeout(()=>{
    screen.classList.remove("hp-flash-damage","hp-flash-heal");
  },380);
}

function applyCombatHpChange(kind,forcedAmount=null){
  const maximum=Math.max(1,Number(current.maxHp||1));
  const before=Math.max(0,Math.min(maximum,Number(current.currentHp||0)));
  const amount=forcedAmount==null?readCombatHpAmount():Math.max(0,Number(forcedAmount||0));

  let after=before;
  if(kind==="damage")after=Math.max(0,before-amount);
  if(kind==="heal")after=Math.min(maximum,before+amount);
  if(kind==="full")after=maximum;

  current.currentHp=after;
  const itemMessages=kind==="damage"?processHeldItemHpTrigger(current):[];
  const generalInput=document.getElementById("currentHp");
  if(generalInput)generalInput.value=after;

  updateHp();
  renderCombatPage();
  renderDrawer();
  renderPageOverview();
  debouncedSave();

  const applied=Math.abs(after-before);
  const feedback=document.getElementById("combatHpFeedback");

  if(feedback){
    if(kind==="damage"){
      feedback.textContent=applied
        ? `${current.name||"Pokémon"} recebeu ${applied} de dano. HP: ${after}/${maximum}.`
        : `${current.name||"Pokémon"} já está com 0 HP.`;
    }else{
      feedback.textContent=applied
        ? `${current.name||"Pokémon"} recuperou ${applied} HP. HP: ${after}/${maximum}.`
        : `${current.name||"Pokémon"} já está com o HP máximo.`;
    }
  }

  flashCombatHpAction(kind==="damage"?"damage":"heal");
  if(itemMessages.length)refreshAfterItemAutomation(itemMessages);
}

function renderCombatParty(){
  const box=document.getElementById("combatPartyList");
  if(!box)return;

  const party=state.pokemon.filter(p=>p.storageGroup==="team").slice(0,6);
  box.innerHTML="";

  for(let index=0;index<6;index++){
    const pokemon=party[index];
    if(!pokemon){
      const empty=document.createElement("div");
      empty.className="combat-party-slot empty";
      empty.innerHTML='<span class="party-ball"></span><span class="combat-party-name">Espaço vazio</span><span class="combat-party-level">—</span>';
      box.appendChild(empty);
      continue;
    }

    const button=document.createElement("button");
    button.type="button";
    button.className=`combat-party-slot${pokemon.id===current.id?" active":""}`;
    button.innerHTML=`
      <span class="party-ball"></span>
      <span class="combat-party-name">${esc(pokemon.name||"Pokémon")}</span>
      <span class="combat-party-level">Lv. ${Number(pokemon.level||1)}</span>
    `;
    button.addEventListener("click",()=>{
      if(pokemon.id===current.id)return;
      state.currentId=pokemon.id;
      current=getCurrent();
      renderAll();
      debouncedSave();
    });
    box.appendChild(button);
  }
}

function renderCombatBag(){
  const box=document.getElementById("combatBagList");
  if(!box)return;

  box.innerHTML="";
  COMBAT_BAG_ITEMS.forEach(item=>{
    const value=Math.max(0,Number(state.combatBag[item.key]||0));
    const row=document.createElement("div");
    row.className="combat-bag-row";
    row.innerHTML=`
      <div class="combat-bag-label">
        <span class="combat-bag-emoji">${item.icon}</span>
        <span>${esc(item.label)}</span>
      </div>
      <div class="combat-bag-controls">
        <button type="button" class="bag-minus" aria-label="Remover ${escAttr(item.label)}">−</button>
        <input type="number" min="0" step="1" value="${value}" aria-label="Quantidade de ${escAttr(item.label)}">
        <button type="button" class="bag-plus" aria-label="Adicionar ${escAttr(item.label)}">+</button>
      </div>
    `;

    const input=row.querySelector("input");
    const commit=amount=>{
      state.combatBag[item.key]=Math.max(0,Number(amount||0));
      input.value=state.combatBag[item.key];
      updateDrawerPocketSummary();
      renderDrawerBag();
      debouncedSave();
    };

    row.querySelector(".bag-minus").addEventListener("click",()=>commit(valueFromInput(input)-1));
    row.querySelector(".bag-plus").addEventListener("click",()=>commit(valueFromInput(input)+1));
    input.addEventListener("input",()=>commit(valueFromInput(input)));
    box.appendChild(row);
  });
}

function valueFromInput(input){
  return Math.max(0,Number(input.value||0));
}



