function renderPageOverview(){
  if(!current)return;
  ensurePage2Data(current);
  ensureProgression(current);

  const setText=(id,value)=>{
    const element=document.getElementById(id);
    if(element)element.textContent=value;
  };

  const activeMoves=(current.moves||[]).filter(move=>move.active&&!isMoveLevelLocked(move)).slice(0,5).length;

  setText("generalOverviewLevel",`Lv. ${Number(current.level||1)}`);
  setText("generalOverviewHp",`${Math.max(0,Number(current.currentHp||0))} / ${Math.max(1,Number(current.maxHp||1))}`);
  setText("generalOverviewNature",current.natureName||"Não definida");
  setText("generalOverviewMoves",`${activeMoves} / 5`);

  setText("miscOverviewPpg",`${Math.max(0,Number(current.currentPpg||0))} / 15`);
  setText("miscOverviewTraining",String((current.trainingMoves||[]).length));
  setText("miscOverviewItems",String((current.itemMemory||[]).length));
  setText("miscOverviewAbilities",String((current.abilityMemory||[]).length));
}

