function setVal(id,v){
  document.getElementById(id).value=v??"";
  if(id==="abilityText"&&typeof fitGeneralAbilityText==="function")requestAnimationFrame(fitGeneralAbilityText);
}
function bindValue(id,key,transform=v=>v){
  document.getElementById(id).addEventListener("input",e=>{
    current[key]=transform(e.target.value);
    if(key==="name"){
      
      renderDrawer();
    }
    if(key==="dex") document.getElementById("dexLabel").textContent="#"+String(current.dex||"—").padStart(4,"0");
    if(["currentHp","maxHp"].includes(key)) updateHp();
    if(["name","level","currentHp","maxHp","type1","type2","heldItem","imageUrl","abilityName","abilityText"].includes(key)){
      renderCombatPage();
      renderPageOverview();
    }
    if(["type1","type2"].includes(key)){
      renderCurrentTypeBadges();
      renderTypeMatchups();
    }
    debouncedSave();
  });
}

function renderNatureProgression(){
  ensureProgression(current);

  const natureSelect=document.getElementById("pokemonNature");
  const positiveDisplay=document.getElementById("naturePositiveDisplay");
  const negativeDisplay=document.getElementById("natureNegativeDisplay");
  const description=document.getElementById("natureDescription");

  natureSelect.innerHTML=[
    '<option value="">Sem Nature definida</option>',
    ...POKEMON_NATURES.map(n=>`<option value="${escAttr(n.name)}">${esc(natureOptionLabel(n))}</option>`)
  ].join("");

  natureSelect.value=current.natureName||"";

  const selectedNature=findPokemonNature(current.natureName);
  const isNeutral=!!selectedNature && !selectedNature.plus && !selectedNature.minus;

  positiveDisplay.textContent=selectedNature?.plus?natureStatLabel(selectedNature.plus):"Nenhum";
  negativeDisplay.textContent=selectedNature?.minus?natureStatLabel(selectedNature.minus):"Nenhum";

  if(!selectedNature){
    description.textContent="Nenhuma Nature definida. A progressão não aplicará bônus nem penalidade de Nature.";
  }else if(isNeutral){
    description.textContent=`${selectedNature.name} é uma Nature neutra: não favorece nem prejudica nenhum atributo.`;
  }else{
    description.textContent=`${selectedNature.name}: ${natureStatLabel(selectedNature.plus)} recebe +1 adicional quando houver investimento; ${natureStatLabel(selectedNature.minus)} perde 1 ponto do ganho, com mínimo de 0.`;
  }

  document.getElementById("autoProgression").checked=!!current.progression.auto;
  document.getElementById("trackingLevel").textContent=`Lv. ${current.progression.lastAppliedLevel ?? current.level}`;

  const grid=document.getElementById("presetGrid");
  grid.innerHTML="";
  const nextLevel=Math.min(100,Number(current.level||1)+1);
  const nextBlock=blockKeyForLevel(nextLevel);
  const lockedNames=[];

  STAT_KEYS.forEach(([k,label])=>{
    const cap=progressionCapacityForNextLevel(k);
    let value=Math.min(Number(current.progression.preset[k]||0),cap.maxThisLevel);
    current.progression.preset[k]=value;

    const box=document.createElement("div");
    box.className="preset-stat"+(cap.maxThisLevel<=0?" locked":"");
    box.innerHTML=`
      <label>${label}</label>
      <input type="number" min="0" max="${cap.maxThisLevel}" value="${value}" ${cap.maxThisLevel<=0?"disabled":""}>
      <span class="preset-limit">${cap.used}/20 no bloco ${esc(nextBlock)}${cap.maxThisLevel<=0?" • BLOQUEADO":` • máx. +${cap.maxThisLevel}`}</span>
    `;
    if(cap.maxThisLevel<=0) lockedNames.push(label);

    const input=box.querySelector("input");
    input.addEventListener("input",e=>{
      const liveCap=progressionCapacityForNextLevel(k);
      let v=Math.max(0,Math.min(liveCap.maxThisLevel,Number(e.target.value||0)));
      e.target.value=v;
      current.progression.preset[k]=v;
      validatePreset(true);
      debouncedSave();
    });
    grid.appendChild(box);
  });

  const notice=document.getElementById("progressLimitNotice");
  if(lockedNames.length){
    notice.innerHTML=`<b>Bloco ${nextBlock}:</b> ${lockedNames.join(", ")} já atingiu +20 e está bloqueado. O atributo será liberado automaticamente quando o próximo nível entrar em uma nova dezena.`;
  }else{
    notice.innerHTML=`<b>Bloco do próximo nível: ${nextBlock}.</b> Cada atributo pode receber no máximo +20 pontos neste bloco. Ao atingir o limite, ele será bloqueado até a próxima dezena.`;
  }

  validatePreset(false);
  renderPriorityControls();
  updateLevelBatchPreview();
}

function renderBaseStatsSummary(){
  const b=current.baseStats||{};
  const total=STAT_KEYS.reduce((sum,[k])=>sum+Number(b[k]||0),0);
  document.getElementById("baseStatsSummary").innerHTML=
    `HP <b>${Number(b.hp||0)}</b> • ATK <b>${Number(b.atk||0)}</b> • DEF <b>${Number(b.def||0)}</b> • `+
    `SP.ATK <b>${Number(b.spa||0)}</b> • SP.DEF <b>${Number(b.spd||0)}</b> • SPEED <b>${Number(b.spe||0)}</b>`+
    `<br><span style="color:var(--muted)">BST Total: ${total}</span>`;
}

