function updatePpgDisplay(){
  const value=Math.max(0,Math.min(15,Number(current.currentPpg||0)));
  current.currentPpg=value;
  const label=document.getElementById("ppgValueLabel");
  const fill=document.getElementById("ppgFill");
  const input=document.getElementById("currentPpg");
  if(label) label.textContent=value;
  if(fill) fill.style.width=`${(value/15)*100}%`;
  if(input && Number(input.value)!==value) input.value=value;
}

function addTrainingMove(){
  const name=document.getElementById("trainingMoveName").value.trim();
  if(!name){showToast("Digite o nome do move em treinamento.");return}

  const elementType=document.getElementById("trainingElementType").value.trim()||"Normal";
  const category=document.getElementById("trainingCategory").value;
  const power=Math.max(0,Number(document.getElementById("trainingPower").value||0));
  const accuracy=Math.max(0,Math.min(90,Number(document.getElementById("trainingAccuracy").value||90)));
  const effectChance=Math.max(0,Math.min(100,Number(document.getElementById("trainingEffectChance").value||0)));
  const description=document.getElementById("trainingDescription").value.trim();
  const type=document.getElementById("trainingMoveType").value;
  const required=type==="natural"?5:10;

  const meta=moveLookupMeta.training||{};
  current.trainingMoves.push({
    id:uid(),
    name,
    elementType,
    category,
    power,
    powerLabel:meta.powerLabel||"",
    accuracy,
    accuracyLabel:meta.accuracyLabel||"",
    alwaysHits:!!meta.alwaysHits,
    effectChance,
    description,
    source:meta.source||"",
    tags:[...(meta.tags||[])],
    learnableBy:[...(meta.learnableBy||[])],
    learnRule:meta.learnRule||"",
    trainingType:type,
    successes:0,
    required,
    active:false
  });
  moveLookupMeta.training=null;

  document.getElementById("trainingMoveName").value="";
  document.getElementById("trainingElementType").value="";
  document.getElementById("trainingCategory").value="Physical";
  document.getElementById("trainingPower").value=0;
  document.getElementById("trainingAccuracy").value=90;
  document.getElementById("trainingEffectChance").value=0;
  document.getElementById("trainingDescription").value="";

  renderTrainingMoves();
  debouncedSave();
}

function renderTrainingMoves(){
  const list=document.getElementById("trainingMovesList");
  if(!list)return;
  const moves=current.trainingMoves||[];
  list.innerHTML=moves.length?"":'<div class="empty-state">Nenhum move em treinamento.</div>';

  moves.forEach(t=>{
    const done=Number(t.successes||0)>=Number(t.required||5);
    const pct=Math.min(100,(Number(t.successes||0)/Number(t.required||5))*100);
    const card=document.createElement("div");
    card.className="training-card"+(t.active?" active-training":"");
    card.innerHTML=`
      <div class="training-top">
        <div>
          <div class="move-name">${esc(t.name)}</div>
          <div class="move-meta">
            <span class="tag">${esc(t.elementType||"Normal")}</span>
            <span class="tag">${esc(t.category||"Physical")}</span>
            <span class="tag">Power ${esc(String(t.powerLabel||Number(t.power||0)))}</span>
            <span class="tag">Acc. ${esc(String(t.accuracyLabel||`${Number(t.accuracy||0)}%`))}</span>
            ${t.source==="Sistema"?'<span class="tag">Exclusivo</span>':""}
            ${Number(t.effectChance||0)>0?`<span class="tag effect-chance-tag combat-detail-tag">Efeito ${Number(t.effectChance||0)}%</span>`:""}
            <span class="tag">${t.trainingType==="natural"?"Natural":"Ilegal / Ovo / TM Raro"}</span>
            <span class="tag">${Number(t.successes||0)}/${Number(t.required||5)} sucessos</span>
            ${t.active?'<span class="tag">Treino ativo</span>':""}
            ${done?'<span class="tag">Concluído</span>':""}
          </div>
          ${t.description?`<div class="move-description">${esc(translateMoveEffectPt(t.description))}</div>`:""}
        </div>
        <button class="btn small danger remove-training">✕</button>
      </div>
      <div class="training-progress"><div class="training-progress-fill" style="width:${pct}%"></div></div>
      <div class="training-actions">
        <button class="btn small set-active">${t.active?"Desmarcar ativo":"Marcar treino ativo"}</button>
        <button class="btn small success-plus" ${done?"disabled":""}>+1 Sucesso</button>
        <button class="btn small crit-plus" ${done?"disabled":""}>Crítico +2</button>
        ${done?'<button class="btn primary small learn-move">Adicionar à Memória de Moves</button>':""}
      </div>
    `;
    card.querySelector(".set-active").onclick=()=>{
      if(!t.active){
        current.trainingMoves.forEach(x=>x.active=false);
        t.active=true;
      }else{
        t.active=false;
      }
      renderTrainingMoves();debouncedSave();
    };
    card.querySelector(".success-plus").onclick=()=>{
      t.successes=Math.min(t.required,Number(t.successes||0)+1);
      renderTrainingMoves();debouncedSave();
    };
    card.querySelector(".crit-plus").onclick=()=>{
      t.successes=Math.min(t.required,Number(t.successes||0)+2);
      renderTrainingMoves();debouncedSave();
    };
    card.querySelector(".remove-training").onclick=()=>{
      current.trainingMoves=current.trainingMoves.filter(x=>x.id!==t.id);
      renderTrainingMoves();debouncedSave();
    };
    const learn=card.querySelector(".learn-move");
    if(learn) learn.onclick=()=>{
      const exists=current.moves.some(m=>m.name.toLowerCase()===t.name.toLowerCase());
      if(!exists){
        current.moves.push({
          id:uid(),
          name:t.name,
          type:t.elementType||"Normal",
          category:t.category||"Physical",
          power:Number(t.power||0),
          powerLabel:t.powerLabel||"",
          accuracy:Number(t.accuracy||90),
          accuracyLabel:t.accuracyLabel||"",
          alwaysHits:!!t.alwaysHits,
          effectChance:Math.max(0,Math.min(100,Number(t.effectChance||0))),
          description:t.description||"",
          source:t.source||"",
          tags:[...(t.tags||[])],
          learnableBy:[...(t.learnableBy||[])],
          learnRule:t.learnRule||"",
          active:false
        });
      }
      current.trainingMoves=current.trainingMoves.filter(x=>x.id!==t.id);
      renderTrainingMoves();
      renderMoves();
      showToast(`${t.name} adicionado à Memória de Moves.`);
      saveState();
    };
    list.appendChild(card);
  });
}

function addCustomItem(){
  const name=document.getElementById("customItemName").value.trim();
  const description=document.getElementById("customItemDescription").value.trim();
  if(!name){showToast("Digite o nome do item.");return}
  if(!current.itemMemory.some(i=>i.name.toLowerCase()===name.toLowerCase())){
    current.itemMemory.push({id:uid(),name,description,custom:true});
  }
  document.getElementById("customItemName").value="";
  document.getElementById("customItemDescription").value="";
  renderItemMemory();debouncedSave();
}

function renderItemMemory(){
  ensureItemMemoryData(current);
  const select=document.getElementById("heldItemSelect");
  const list=document.getElementById("itemMemoryList");
  if(!select||!list)return;
  const names=[];
  if(current.heldItem)names.push(current.heldItem);
  current.itemMemory.forEach(item=>{if(item.name&&!names.includes(item.name))names.push(item.name)});
  select.innerHTML='<option value="">Nenhum item</option>'+names.map(name=>`<option value="${escAttr(name)}">${esc(name)}</option>`).join("");
  select.value=current.heldItem||"";
  list.innerHTML=current.itemMemory.length?"":'<div class="empty-state">Nenhum item salvo. Busque qualquer item oficial no catálogo PokéAPI ou crie um item original.</div>';
  current.itemMemory.forEach(item=>{
    const card=document.createElement("div");
    card.className="item-memory-card pokeapi-item-card"+(item.pokeApi?" official":" custom");
    const automation=itemAutomationLabel(item);
    const meta=[item.categoryPt||"",item.pokeApi?"PokéAPI":"Original",item.cost?`₽ ${Number(item.cost).toLocaleString("pt-BR")}`:"",item.flingPower!=null?`Fling ${item.flingPower}`:""].filter(Boolean);
    card.innerHTML=`
      <div class="memory-card-top"><div class="pokeapi-item-main">
        <div class="pokeapi-item-title-row">${itemPixelIconHtml(item,"pokeapi-item-orb")}<div><div class="move-name">${esc(item.name)}</div><div class="pokeapi-item-meta">${meta.map(v=>`<span>${esc(v)}</span>`).join("")}</div></div></div>
        ${current.heldItem===item.name?'<div class="equipped-badge">Item equipado</div>':""}
        ${automation?`<div class="item-automation-badge"><b>⚙ ${esc(itemAutomationMode(item))}</b><span>${esc(automation)}</span></div>`:'<div class="item-automation-badge manual"><b>MANUAL</b><span>O efeito depende de um evento que a ficha não consegue detectar automaticamente.</span></div>'}
        <div class="item-description">${esc(item.description||"Sem descrição.")}</div>
      </div><button class="btn small danger remove-item" type="button">✕</button></div>
      <div class="memory-card-actions"><button class="btn small equip-item" type="button">${current.heldItem===item.name?"Desequipar":"Equipar"}</button></div>`;
    card.querySelector(".equip-item").onclick=()=>{current.heldItem=current.heldItem===item.name?"":item.name;syncHeldItemFields();const messages=current.heldItem?processHeldItemImmediate(current):[];renderItemMemory();renderCombatPage();renderPageOverview();debouncedSave();if(messages.length)refreshAfterItemAutomation(messages)};
    card.querySelector(".remove-item").onclick=()=>{if(current.heldItem===item.name){current.heldItem="";syncHeldItemFields()}current.itemMemory=current.itemMemory.filter(row=>row.id!==item.id);renderItemMemory();renderCombatPage();debouncedSave()};
    list.appendChild(card);
  });
}

const CUSTOM_DISPLAY_ABILITY_NAMES=new Set([
  "counterstep",
  "slipstream",
  "strata-guard",
  "wyrmscale",
  "emergency-dash"
]);

function abilityIsAuthored(ability){
  const section=String(ability?.section||"").trim();
  const key=normalizeAbilityKey(ability?.name);

  return (
    CUSTOM_DISPLAY_ABILITY_NAMES.has(key)
    ||section==="Economia e Downtime"
    ||section==="Abilities exclusivas de Pokémon reworkados"
    ||section==="Abilities exclusivas de Fakemon"
    ||section.startsWith("Autorais ")
  );
}

function abilityDisplayLabel(ability){
  if(!ability)return "Ability manual";

  if(abilityIsAuthored(ability)){
    return "By N4nd0_0";
  }

  const section=String(ability.section||"").trim();

  if(/^Geração\s+(?:III|IV|V|VI|VII|VIII|IX)$/i.test(section)){
    return `${section} • Atualizadas & Adaptadas`;
  }

  return "Atualizadas & Adaptadas";
}

function renderPrimaryAbilitySource(){
  const badge=document.getElementById("activeAbilitySource");
  if(!badge)return;

  const ability=findCustomAbility(current.abilityName);

  if(ability){
    badge.textContent=abilityDisplayLabel(ability);
    badge.title=abilityIsAuthored(ability)
      ?`Ability criada e adaptada por N4nd0_0 • ${ability.name}`
      :`Ability atualizada e adaptada para o sistema • ${ability.name}`;
    badge.hidden=false;
    return;
  }

  badge.textContent="Ability manual";
  badge.title="Esta Ability foi escrita manualmente na ficha.";
  badge.hidden=false;
}

function applyActiveAbilityFromCompendium({notify=false}={}){
  const input=document.getElementById("abilityName");
  const ability=findCustomAbility(input?.value||current.abilityName);

  if(!ability){
    renderPrimaryAbilitySource();
    return false;
  }

  current.abilityName=ability.name;
  current.abilityText=ability.description||"";
  current.abilitySource="Compêndio Principal";
  current.abilitySection=ability.section||"";

  setVal("abilityName",current.abilityName);
  setVal("abilityText",current.abilityText);
  renderPrimaryAbilitySource();
  renderCombatPage();
  renderPageOverview();
  debouncedSave();

  if(notify){
    showToast(`${ability.name} aplicada • ${abilityDisplayLabel(ability)}.`);
  }

  return true;
}

function renderSystemAbilitySuggestions(){
  const list=document.getElementById("systemAbilitySuggestions");
  if(!list)return;

  const abilities=[...CUSTOM_ABILITY_BANK]
    .sort((a,b)=>a.name.localeCompare(b.name,"pt-BR"));

  list.innerHTML=abilities
    .map(ability=>
      `<option value="${escAttr(ability.name)}" label="${escAttr(abilityDisplayLabel(ability))}"></option>`
    )
    .join("");

  const count=document.getElementById("abilityBankCount");
  if(count)count.textContent=String(abilities.length);
}

function fillAbilityFromSystem(){
  const input=document.getElementById("abilitySystemLookup");
  const status=document.getElementById("abilitySystemLookupStatus");
  const ability=findCustomAbility(input.value);

  if(!ability){
    status.textContent="Ability não encontrada.";
    return;
  }

  setVal("memoryAbilityName",ability.name);
  setVal("memoryAbilityDescription",ability.description||"");
  status.textContent=`✓ ${ability.name} carregada • ${abilityDisplayLabel(ability)}.`;
}

function applySystemAbilityOverrides(){
  const active=findCustomAbility(current.abilityName);

  if(active){
    current.abilityName=active.name;
    current.abilityText=active.description||current.abilityText||"";
    current.abilitySource="Compêndio Principal";
    current.abilitySection=active.section||"";
  }else if(current.abilitySource==="Compêndio Principal"){
    current.abilitySource="";
    current.abilitySection="";
  }

  (current.abilityMemory||[]).forEach(record=>{
    const systemAbility=findCustomAbility(record.name||record.apiName);

    if(systemAbility){
      record.name=systemAbility.name;
      record.description=systemAbility.description||record.description||"";
      record.source="Compêndio Principal";
      record.section=systemAbility.section||"";
      record.primary=true;
    }
  });
}

function addMemoryAbility(){
  const typedName=document.getElementById("memoryAbilityName").value.trim();
  const typedDescription=document.getElementById("memoryAbilityDescription").value.trim();

  if(!typedName){
    showToast("Digite o nome da Ability.");
    return;
  }

  const systemAbility=findCustomAbility(typedName);
  const name=systemAbility?.name||typedName;
  const description=systemAbility?.description||typedDescription;

  if(!current.abilityMemory.some(record=>
    normalizeAbilityKey(record.name)===normalizeAbilityKey(name)
  )){
    current.abilityMemory.push({
      id:uid(),
      name,
      description,
      hidden:false,
      custom:true,
      source:systemAbility?"Compêndio Principal":"Manual",
      section:systemAbility?.section||"",
      primary:!!systemAbility
    });
  }

  document.getElementById("memoryAbilityName").value="";
  document.getElementById("memoryAbilityDescription").value="";
  renderAbilityMemory();
  debouncedSave();
}

function renderAbilityMemory(){
  const list=document.getElementById("abilityMemoryList");
  if(!list)return;

  const abilities=current.abilityMemory||[];
  list.innerHTML=abilities.length
    ?""
    :'<div class="empty-state">Nenhuma outra Ability salva.</div>';

  abilities.forEach(record=>{
    const equipped=current.abilityName
      &&normalizeAbilityKey(current.abilityName)===normalizeAbilityKey(record.name);

    const systemAbility=findCustomAbility(record.name);
    const primary=record.source==="Compêndio Principal"
      ||record.source==="Sistema"
      ||!!systemAbility;

    const displayLabel=systemAbility
      ?abilityDisplayLabel(systemAbility)
      :record.source==="PokéAPI • PT-BR"
        ?"Descrição oficial"
        :"Ability manual";

    const card=document.createElement("div");
    card.className="ability-memory-card";
    card.innerHTML=`
      <div class="memory-card-top">
        <div>
          <div class="move-name">${esc(record.name)}</div>
          ${record.hidden?'<div class="equipped-badge">Hidden Ability</div>':""}
          ${primary?`<div class="equipped-badge">${esc(displayLabel)}</div>`:""}
          ${!primary&&record.source==="PokéAPI • PT-BR"?'<div class="equipped-badge">Descrição oficial</div>':""}
          ${equipped?'<div class="equipped-badge">Ability ativa</div>':""}
          <div class="ability-description">${esc(record.description||"Sem descrição salva.")}</div>
        </div>
        <button class="btn small danger remove-ability">✕</button>
      </div>
      <div class="memory-card-actions">
        <button class="btn small equip-ability">Usar como Ability ativa</button>
      </div>
    `;

    card.querySelector(".equip-ability").onclick=()=>{
      const systemAbility=findCustomAbility(record.name);
      current.abilityName=systemAbility?.name||record.name;
      current.abilityText=systemAbility?.description||record.description||"";
      current.abilitySource=systemAbility?"Compêndio Principal":record.source||"";
      current.abilitySection=systemAbility?.section||record.section||"";
      setVal("abilityName",current.abilityName);
      setVal("abilityText",current.abilityText);
      renderPrimaryAbilitySource();
      renderAbilityMemory();
      renderCombatPage();
      debouncedSave();
    };

    card.querySelector(".remove-ability").onclick=()=>{
      current.abilityMemory=current.abilityMemory.filter(item=>item.id!==record.id);
      renderAbilityMemory();
      debouncedSave();
    };

    list.appendChild(card);
  });
}

function renderPortrait(){
  const img=document.getElementById("portraitImg");
  const empty=document.getElementById("portraitEmpty");
  const src=displayPokemonImage(current);
  img.classList.toggle("is-official-fallback",!current.imageUrl&&!!src);
  if(src){
    if(img.getAttribute("src")!==src)img.src=src;
    img.hidden=false; empty.hidden=true;
    img.onerror=()=>{img.hidden=true;empty.hidden=false;};
  }else{
    img.hidden=true; empty.hidden=false;
  }
}
function renderStats(){
  const box=document.getElementById("statEditor");
  box.innerHTML="";

  STAT_KEYS.forEach(([key,label])=>{
    const row=document.createElement("div");
    row.className="stat-row";
    row.dataset.stat=key;
    row.innerHTML=`<span>${label}</span><input type="number" min="0" value="${Number(current.stats[key]||0)}">`;

    row.querySelector("input").addEventListener("input",e=>{
      current.stats[key]=Number(e.target.value||0);

      if(key==="hp"){
        current.maxHp=Number(e.target.value||0);
        if(Number(current.currentHp)>current.maxHp)current.currentHp=current.maxHp;
        setVal("maxHp",current.maxHp);
        setVal("currentHp",current.currentHp);
        updateHp();
      }

      drawRadar();
      updateDerived();
      renderMoves();
      renderCombatPage();
      debouncedSave();
    });

    box.appendChild(row);
  });

  drawRadar();
  updateDerived();
}

function statDice(v){
  v=Number(v||0);
  if(v<50)return {dice:0,fixed:0};
  if(v<=75)return {dice:1,fixed:0};
  if(v<=100)return {dice:2,fixed:0};
  if(v<=125)return {dice:3,fixed:0};
  if(v<=150)return {dice:4,fixed:0};
  if(v<=175)return {dice:5,fixed:0};
  // Acima de 175, cada 15 pontos completos concede +1/-1 fixo.
  return {dice:6,fixed:Math.floor((v-175)/15)};
}
function updateDerived(){
  const atkValue=combatEffectiveStat(current,"atk");
  const spaValue=combatEffectiveStat(current,"spa");
  const defValue=combatEffectiveStat(current,"def");
  const spdValue=combatEffectiveStat(current,"spd");

  const atk=statDice(atkValue);
  const spa=statDice(spaValue);
  const def=statDice(defValue);
  const spd=statDice(spdValue);

  const atkStage=combatStageTotal(current,"atk");
  const spaStage=combatStageTotal(current,"spa");
  const defStage=combatStageTotal(current,"def");
  const spdStage=combatStageTotal(current,"spd");

  document.getElementById("atkBonus").textContent=
    `ATK +${atk.dice}d6${atk.fixed?` +${atk.fixed}`:""}${atkStage?` • ${atkValue} (${combatStageSigned(atkStage)})`:""}`;

  document.getElementById("spaBonus").textContent=
    `SP.ATK +${spa.dice}d6${spa.fixed?` +${spa.fixed}`:""}${spaStage?` • ${spaValue} (${combatStageSigned(spaStage)})`:""}`;

  document.getElementById("defReduce").textContent=
    `DEF -${def.dice}d6${def.fixed?` -${def.fixed}`:""}${defStage?` • ${defValue} (${combatStageSigned(defStage)})`:""}`;

  document.getElementById("spdReduce").textContent=
    `SP.DEF -${spd.dice}d6${spd.fixed?` -${spd.fixed}`:""}${spdStage?` • ${spdValue} (${combatStageSigned(spdStage)})`:""}`;
}

/* V6 — o radar anima entre os valores antigos e os novos e usa uma escala que acompanha o Pokémon. */
let radarAnimFrom=null,radarAnimShown=null,radarAnimFrame=0;
function radarScaleFor(values){
  const top=Math.max(...values,1);
  return Math.max(100,Math.ceil(top*1.12/25)*25);
}
function drawRadar(){
  radarAccentCache=null;
  const target=STAT_KEYS.map(([k])=>Number(current?.stats?.[k]||0));
  const targetMax=radarScaleFor(target);
  const reduce=window.matchMedia?.("(prefers-reduced-motion: reduce)")?.matches;
  const start=radarAnimShown||target.map(()=>0);
  const startMax=radarAnimFrom?.max||targetMax;
  cancelAnimationFrame(radarAnimFrame);
  const same=radarAnimShown&&radarAnimShown.every((v,i)=>v===target[i])&&startMax===targetMax;
  if(reduce||same||document.hidden){
    radarAnimShown=target.slice();radarAnimFrom={max:targetMax};
    drawRadarFrame(target,targetMax);
    return;
  }
  const t0=performance.now(),duration=radarAnimShown?420:780;
  const ease=t=>1-Math.pow(1-t,3);
  const step=now=>{
    const k=ease(Math.min(1,(now-t0)/duration));
    const vals=target.map((v,i)=>start[i]+(v-start[i])*k);
    const max=startMax+(targetMax-startMax)*k;
    radarAnimShown=vals;radarAnimFrom={max};
    drawRadarFrame(vals,max,target);
    if(k<1)radarAnimFrame=requestAnimationFrame(step);
    else{radarAnimShown=target.slice();radarAnimFrom={max:targetMax};}
  };
  radarAnimFrame=requestAnimationFrame(step);
}
function radarHexA(hex,a){
  const h=String(hex).replace("#","");
  const n=parseInt(h.length===3?h.split("").map(c=>c+c).join(""):h,16);
  return `rgba(${(n>>16)&255},${(n>>8)&255},${n&255},${a})`;
}
let radarHoverIndex=-1;
let radarAccentCache=null;
function drawRadarFrame(animatedValues,animatedMax,labelValues=animatedValues){
  const c=document.getElementById("radar");
  if(!c)return;
  /* Desenha em alta resolução para ficar nítido em telas de celular e Retina. */
  const W=560,H=470,dpr=Math.min(3,Math.max(1,window.devicePixelRatio||1));
  if(c.width!==Math.round(W*dpr)){
    c.width=Math.round(W*dpr);c.height=Math.round(H*dpr);
    c.style.aspectRatio=`${W} / ${H}`;
    c.style.width=`${W}px`;
  }
  const ctx=c.getContext("2d");
  ctx.setTransform(dpr,0,0,dpr,0,0);
  ctx.clearRect(0,0,W,H);
  const cx=W/2,cy=222,R=150;
  /* A cor do tema é lida uma vez por animação: ler o estilo a cada quadro
     forçava o celular a recalcular a página inteira ~60 vezes por segundo. */
  const isDex=document.documentElement.dataset.sheetMode==="pokedex";
  if(!radarAccentCache||radarAccentCache.dex!==isDex){
    const style=getComputedStyle(document.documentElement);
    radarAccentCache={dex:isDex,value:(isDex?style.getPropertyValue("--pokedex-color"):style.getPropertyValue("--accent")).trim()||"#63d0ff"};
  }
  const accent=radarAccentCache.value;
  const labels=["VIDA","ATAQUE","DEFESA","ATQ. ESP.","DEF. ESP.","VELOC."];
  const keys=STAT_KEYS.map(([k])=>k);
  const statColors=["#4fe36f","#ff9538","#4f8dff","#b067ff","#76e7ff","#ffd84a"];
  const values=animatedValues;
  const max=animatedMax;
  const plus=current?.naturePlus,minus=current?.natureMinus;
  const angle=i=>-Math.PI/2+i*Math.PI/3;
  const pt=(i,r)=>[cx+Math.cos(angle(i))*r,cy+Math.sin(angle(i))*r];
  const hexPath=r=>{ctx.beginPath();for(let i=0;i<6;i++){const [x,y]=pt(i,r);i?ctx.lineTo(x,y):ctx.moveTo(x,y)}ctx.closePath()};

  /* Fundo: halo suave na cor do tema. */
  const halo=ctx.createRadialGradient(cx,cy,10,cx,cy,R+110);
  halo.addColorStop(0,radarHexA("#3c78d8",.16));
  halo.addColorStop(.6,radarHexA("#122038",.06));
  halo.addColorStop(1,"rgba(0,0,0,0)");
  ctx.fillStyle=halo;ctx.fillRect(0,0,W,H);

  /* Anéis em faixas alternadas (como uma teia), do externo para o interno. */
  for(let ring=5;ring>=1;ring--){
    hexPath(R*ring/5);
    ctx.fillStyle=ring%2?"rgba(110,170,255,.075)":"rgba(10,18,32,.35)";
    ctx.fill();
    ctx.lineWidth=ring===5?2:1;
    ctx.strokeStyle=ring===5?"rgba(150,200,255,.45)":"rgba(130,180,255,.16)";
    ctx.stroke();
  }

  /* Fatia em destaque quando o mouse passa por cima de um status. */
  if(radarHoverIndex>=0){
    const i=radarHoverIndex;
    const a0=angle(i)-Math.PI/6,a1=angle(i)+Math.PI/6;
    ctx.save();
    hexPath(R);ctx.clip();
    ctx.beginPath();ctx.moveTo(cx,cy);ctx.arc(cx,cy,R*1.2,a0,a1);ctx.closePath();
    ctx.fillStyle=radarHexA(statColors[i],.12);ctx.fill();
    ctx.restore();
  }

  /* Eixos. */
  for(let i=0;i<6;i++){
    const [x,y]=pt(i,R);
    const g=ctx.createLinearGradient(cx,cy,x,y);
    g.addColorStop(0,"rgba(150,200,255,0)");
    g.addColorStop(1,radarHexA(statColors[i],i===radarHoverIndex?.75:.4));
    ctx.beginPath();ctx.moveTo(cx,cy);ctx.lineTo(x,y);
    ctx.strokeStyle=g;ctx.lineWidth=i===radarHoverIndex?2:1.2;ctx.stroke();
  }

  /* Valores de referência no eixo de cima. */
  ctx.font='10px "Silkscreen", monospace';
  ctx.textAlign="left";ctx.textBaseline="middle";
  ctx.fillStyle="rgba(180,205,240,.55)";
  for(let ring=1;ring<=4;ring++){
    const [x,y]=pt(0,R*ring/5);
    ctx.fillText(String(Math.round(max*ring/5)),x+5,y);
  }

  /* Polígono: cada fatia mistura as cores dos dois status vizinhos. */
  const pts=values.map((v,i)=>pt(i,R*Math.max(0,Math.min(v/max,1))));
  for(let i=0;i<6;i++){
    const j=(i+1)%6;
    const [x1,y1]=pts[i],[x2,y2]=pts[j];
    const g=ctx.createLinearGradient(x1,y1,x2,y2);
    g.addColorStop(0,radarHexA(statColors[i],.42));
    g.addColorStop(1,radarHexA(statColors[j],.42));
    ctx.beginPath();ctx.moveTo(cx,cy);ctx.lineTo(x1,y1);ctx.lineTo(x2,y2);ctx.closePath();
    ctx.fillStyle=g;ctx.fill();
  }
  const shine=ctx.createRadialGradient(cx,cy,0,cx,cy,R);
  shine.addColorStop(0,"rgba(8,14,24,.55)");
  shine.addColorStop(1,"rgba(8,14,24,0)");
  ctx.beginPath();pts.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.closePath();
  ctx.fillStyle=shine;ctx.fill();
  ctx.save();
  ctx.shadowColor="rgba(160,230,255,.85)";ctx.shadowBlur=14;
  ctx.lineJoin="round";ctx.lineWidth=2.6;ctx.strokeStyle="rgba(235,248,255,.95)";
  ctx.stroke();
  ctx.restore();

  /* Pontos em cada vértice. */
  pts.forEach(([x,y],i)=>{
    const big=i===radarHoverIndex;
    const r=big?8:6;
    const glow=ctx.createRadialGradient(x,y,0,x,y,r*3.2);
    glow.addColorStop(0,radarHexA(statColors[i],.55));
    glow.addColorStop(1,radarHexA(statColors[i],0));
    ctx.fillStyle=glow;ctx.beginPath();ctx.arc(x,y,r*3.2,0,Math.PI*2);ctx.fill();
    ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);
    ctx.fillStyle=statColors[i];ctx.fill();
    ctx.lineWidth=2.5;ctx.strokeStyle="#0b121a";ctx.stroke();
    ctx.beginPath();ctx.arc(x-r*.3,y-r*.3,r*.35,0,Math.PI*2);
    ctx.fillStyle="rgba(255,255,255,.7)";ctx.fill();
  });

  /* Centro: total de status. */
  const total=Math.round(labelValues.reduce((a,b)=>a+Number(b||0),0));
  ctx.beginPath();ctx.arc(cx,cy,27,0,Math.PI*2);
  ctx.fillStyle="rgba(7,12,20,.92)";ctx.fill();
  ctx.lineWidth=2.5;ctx.strokeStyle=radarHexA(accent.startsWith("#")?accent:"#63d0ff",.9);ctx.stroke();
  ctx.textAlign="center";ctx.textBaseline="middle";
  ctx.fillStyle="rgba(190,214,255,.75)";ctx.font='8px "Press Start 2P", "Silkscreen", monospace';
  ctx.fillText("TOTAL",cx,cy-8);
  ctx.fillStyle="#fff";ctx.font='12px "Press Start 2P", "Silkscreen", monospace';
  ctx.fillText(String(total),cx,cy+7);

  /* Rótulos em etiquetas, com a Nature marcada. */
  const labelR=R+44;
  labels.forEach((lab,i)=>{
    const [lx,ly]=pt(i,labelR);
    const key=keys[i];
    const mark=key===plus?" ▲":key===minus?" ▼":"";
    const value=String(Math.round(labelValues[i]));
    ctx.font='10px "Press Start 2P", "Silkscreen", monospace';
    const lw=ctx.measureText(lab+mark).width;
    ctx.font='14px "Press Start 2P", "Silkscreen", monospace';
    const vw=ctx.measureText(value).width;
    const bw=Math.max(lw,vw)+22,bh=46;
    let bx=lx-bw/2,by=ly-bh/2;
    bx=Math.max(4,Math.min(W-bw-4,bx));
    by=Math.max(4,Math.min(H-bh-4,by));
    const hot=i===radarHoverIndex;
    ctx.beginPath();
    if(ctx.roundRect)ctx.roundRect(bx,by,bw,bh,8);else ctx.rect(bx,by,bw,bh);
    ctx.fillStyle=hot?radarHexA(statColors[i],.22):"rgba(8,14,22,.78)";
    ctx.fill();
    ctx.lineWidth=hot?2:1.4;
    ctx.strokeStyle=radarHexA(statColors[i],hot?.95:.55);
    ctx.stroke();
    ctx.textAlign="center";ctx.textBaseline="middle";
    ctx.font='10px "Press Start 2P", "Silkscreen", monospace';
    ctx.fillStyle=statColors[i];
    ctx.fillText(lab,bx+bw/2-(mark?ctx.measureText(mark).width/2:0),by+15);
    if(mark){
      ctx.fillStyle=key===plus?"#ff8a8a":"#7fb4ff";
      ctx.fillText(mark,bx+bw/2+ctx.measureText(lab).width/2,by+15);
    }
    ctx.font='14px "Press Start 2P", "Silkscreen", monospace';
    ctx.fillStyle="#f4f9ff";
    ctx.fillText(value,bx+bw/2,by+33);
  });

  ctx.textAlign="center";ctx.textBaseline="middle";
  ctx.font='10px "Silkscreen", monospace';
  ctx.fillStyle="rgba(190,214,255,.6)";
  ctx.fillText(`ESCALA ATÉ ${Math.round(max)}  •  ▲ NATURE +  ▼ NATURE −`,cx,H-12);
}

/* Passar o mouse destaca o status; clicar abre o campo dele para editar. */
function initializeRadarInteraction(){
  const c=document.getElementById("radar");
  if(!c||c.dataset.radarBound)return;
  c.dataset.radarBound="1";
  const indexAt=event=>{
    const rect=c.getBoundingClientRect();
    const x=(event.clientX-rect.left)/rect.width*560-280;
    const y=(event.clientY-rect.top)/rect.height*470-222;
    if(Math.hypot(x,y)<30)return -1;
    let a=Math.atan2(y,x)+Math.PI/2;
    if(a<0)a+=Math.PI*2;
    return Math.round(a/(Math.PI/3))%6;
  };
  const setHover=i=>{
    if(i===radarHoverIndex)return;
    radarHoverIndex=i;
    c.style.cursor=i>=0?"pointer":"default";
    document.querySelectorAll("#statEditor .stat-row").forEach(row=>{
      row.classList.toggle("radar-linked",i>=0&&row.dataset.stat===STAT_KEYS[i][0]);
    });
    if(radarAnimShown)drawRadarFrame(radarAnimShown,radarAnimFrom?.max||radarScaleFor(radarAnimShown),STAT_KEYS.map(([k])=>Number(current?.stats?.[k]||0)));
  };
  c.addEventListener("pointermove",event=>setHover(indexAt(event)));
  c.addEventListener("pointerleave",()=>setHover(-1));
  c.addEventListener("click",event=>{
    const i=indexAt(event);
    if(i<0)return;
    const input=document.querySelector(`#statEditor .stat-row[data-stat="${STAT_KEYS[i][0]}"] input`);
    if(input){input.focus();input.select?.();}
  });
  document.getElementById("statEditor")?.addEventListener("pointerover",event=>{
    const row=event.target.closest(".stat-row");
    if(row)setHover(STAT_KEYS.findIndex(([k])=>k===row.dataset.stat));
  });
  document.getElementById("statEditor")?.addEventListener("pointerleave",()=>setHover(-1));
}
function hexToRgba(color,a){
  const tmp=document.createElement("div");tmp.style.color=color;document.body.appendChild(tmp);
  const rgb=getComputedStyle(tmp).color;tmp.remove();
  const nums=rgb.match(/\d+/g)||[200,100,100];
  return `rgba(${nums[0]},${nums[1]},${nums[2]},${a})`;
}
function updateHp(){
  const cur=Math.max(0,Number(current.currentHp||0)), max=Math.max(1,Number(current.maxHp||1));
  const pct=Math.max(0,Math.min(100,cur/max*100));
  const fill=document.getElementById("hpFill");
  const label=document.getElementById("hpPercentLabel");
  fill.style.width=pct+"%";
  fill.classList.toggle("hp-warning",pct<=50 && pct>=25);
  fill.classList.toggle("hp-danger",pct<25);
  if(label)label.textContent=`${Math.round(pct)}%`;
  updateCombatHp();
}
function updateHappiness(){
  current.happiness=Math.max(0,Math.min(255,Math.round(Number(current.happiness||0))));
  const input=document.getElementById("happiness");
  const value=document.getElementById("happinessValue");
  const fill=document.getElementById("happinessFill");
  const bar=fill?.parentElement;

  if(input) input.value=current.happiness;
  if(value) value.textContent=current.happiness;

  const pct=(current.happiness/255)*100;
  if(fill) fill.style.width=`${pct}%`;

  if(bar){
    bar.setAttribute("role","progressbar");
    bar.setAttribute("aria-label","Felicidade");
    bar.setAttribute("aria-valuemin","0");
    bar.setAttribute("aria-valuemax","255");
    bar.setAttribute("aria-valuenow",String(current.happiness));
  }
}
const CONDITION_ICONS={
  "Paralisado":"⚡","Dormindo":"💤","Envenenado":"☠️","Queimado":"🔥",
  "Deep Burn":"🩸","Confuso":"💫","Congelado":"🧊","Exaustão":"💨"
};

function renderConditionsLegacy(){
  if(!Array.isArray(current.conditions)) current.conditions=[];
  const box=document.getElementById("conditions");
  const count=document.getElementById("conditionActiveCount");
  const title=document.getElementById("conditionInfoTitle");
  const text=document.getElementById("conditionInfoText");
  box.innerHTML="";
  count.textContent=current.conditions.length;

  const selected=renderConditions.selectedName;
  if(selected && CONDITIONS[selected]){
    title.textContent=selected;
    text.textContent=CONDITIONS[selected];
  }else{
    title.textContent=current.conditions.length ? "Condições ativas" : "Nenhuma condição ativa";
    text.textContent=current.conditions.length
      ? current.conditions.join(" • ")
      : "Clique em uma condição para ativá-la ou removê-la e consultar seu efeito.";
  }

  Object.entries(CONDITIONS).forEach(([name,desc])=>{
    const active=current.conditions.includes(name);
    const b=document.createElement("button");
    b.type="button";
    b.className="condition"+(active?" active":"");
    b.innerHTML=`
      <span class="condition-icon">${CONDITION_ICONS[name]||"●"}</span>
      <span class="condition-name">${esc(name)}</span>
      <span class="condition-state">${active?"Ativa":"Inativa"}</span>
    `;
    b.addEventListener("click",()=>{
      renderConditions.selectedName=name;
      if(active){current.conditions=current.conditions.filter(x=>x!==name);}else{current.conditions.push(name);}
      const itemMessages=!active?processHeldItemConditionTrigger(current):[];
      renderConditions();renderItemMemory();renderCombatPage();debouncedSave();
      if(itemMessages.length)refreshAfterItemAutomation(itemMessages);
    });
    box.appendChild(b);
  });
}
function powerToDice(power){
  power=Number(power||0);
  if(power<=0)return "—";
  if(power<=20)return "1d6";
  if(power<=40)return "2d6";
  if(power<=60)return "3d6";
  if(power<=80)return "4d6";
  if(power<=100)return "5d6";
  return "6d6";
}

const POKEMON_TYPES=[
  "Normal","Fire","Water","Electric","Grass","Ice","Fighting","Poison","Ground",
  "Flying","Psychic","Bug","Rock","Ghost","Dragon","Dark","Steel","Fairy"
];

function typeBadgeClass(type){
  return String(normalizeTypeName(type)||"").toLowerCase().replace(/[^a-z0-9_-]/g,"");
}

function typeIconHtml(type,compact=false){
  const normalized=normalizeTypeName(type);
  if(!normalized)return '<span class="tag">—</span>';
  const className=typeBadgeClass(normalized);
  return `<span class="type-icon-badge type-${escAttr(className)}${compact?" compact":""}" title="${escAttr(normalized)}">
    <span class="type-icon-label">[${esc(normalized.toUpperCase())}]</span>
  </span>`;
}

function renderCurrentTypeBadges(){
  const box=document.getElementById("currentTypeBadges");
  if(!box)return;
  const types=[normalizeTypeName(current.type1),normalizeTypeName(current.type2)].filter(Boolean);
  box.innerHTML=types.length?types.map(type=>typeIconHtml(type)).join(""):'<span class="matchup-empty">Nenhuma tipagem definida</span>';
}

const TYPE_CHART={
  Normal:{Rock:.5,Ghost:0,Steel:.5},
  Fire:{Fire:.5,Water:.5,Grass:2,Ice:2,Bug:2,Rock:.5,Dragon:.5,Steel:2},
  Water:{Fire:2,Water:.5,Grass:.5,Ground:2,Rock:2,Dragon:.5},
  Electric:{Water:2,Electric:.5,Grass:.5,Ground:0,Flying:2,Dragon:.5},
  Grass:{Fire:.5,Water:2,Grass:.5,Poison:.5,Ground:2,Flying:.5,Bug:.5,Rock:2,Dragon:.5,Steel:.5},
  Ice:{Fire:.5,Water:.5,Grass:2,Ice:.5,Ground:2,Flying:2,Dragon:2,Steel:.5},
  Fighting:{Normal:2,Ice:2,Poison:.5,Flying:.5,Psychic:.5,Bug:.5,Rock:2,Ghost:0,Dark:2,Steel:2,Fairy:.5},
  Poison:{Grass:2,Poison:.5,Ground:.5,Rock:.5,Ghost:.5,Steel:0,Fairy:2},
  Ground:{Fire:2,Electric:2,Grass:.5,Poison:2,Flying:0,Bug:.5,Rock:2,Steel:2},
  Flying:{Electric:.5,Grass:2,Fighting:2,Bug:2,Rock:.5,Steel:.5},
  Psychic:{Fighting:2,Poison:2,Psychic:.5,Dark:0,Steel:.5},
  Bug:{Fire:.5,Grass:2,Fighting:.5,Poison:.5,Flying:.5,Psychic:2,Ghost:.5,Dark:2,Steel:.5,Fairy:.5},
  Rock:{Fire:2,Ice:2,Fighting:.5,Ground:.5,Flying:2,Bug:2,Steel:.5},
  Ghost:{Normal:0,Psychic:2,Ghost:2,Dark:.5},
  Dragon:{Dragon:2,Steel:.5,Fairy:0},
  Dark:{Fighting:.5,Psychic:2,Ghost:2,Dark:.5,Fairy:.5},
  Steel:{Fire:.5,Water:.5,Electric:.5,Ice:2,Rock:2,Steel:.5,Fairy:2},
  Fairy:{Fire:.5,Fighting:2,Poison:.5,Dragon:2,Dark:2,Steel:.5}
};

/* Nomes em português (e sem acento) também valem: "Fada" vira Fairy. */
const TYPE_ALIASES_PT={
  normal:"Normal",fogo:"Fire",agua:"Water",eletrico:"Electric",eletrica:"Electric",grama:"Grass",planta:"Grass",
  gelo:"Ice",lutador:"Fighting",luta:"Fighting",veneno:"Poison",venenoso:"Poison",terra:"Ground",solo:"Ground",
  voador:"Flying",voo:"Flying",psiquico:"Psychic",inseto:"Bug",pedra:"Rock",rocha:"Rock",fantasma:"Ghost",
  dragao:"Dragon",sombrio:"Dark",noturno:"Dark",trevas:"Dark",metal:"Steel",aco:"Steel",fada:"Fairy",fadas:"Fairy"
};
const TYPE_PT_LABEL={Normal:"Normal",Fire:"Fogo",Water:"Água",Electric:"Elétrico",Grass:"Grama",Ice:"Gelo",Fighting:"Lutador",
  Poison:"Veneno",Ground:"Terra",Flying:"Voador",Psychic:"Psíquico",Bug:"Inseto",Rock:"Pedra",Ghost:"Fantasma",Dragon:"Dragão",
  Dark:"Sombrio",Steel:"Aço",Fairy:"Fada"};
function normalizeTypeName(type){
  const raw=String(type||"").trim().toLowerCase();
  if(!raw)return "";
  const found=POKEMON_TYPES.find(t=>t.toLowerCase()===raw);
  if(found)return found;
  const plain=raw.normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-z]/g,"");
  return TYPE_ALIASES_PT[plain]||POKEMON_TYPES.find(t=>t.toLowerCase()===plain)||"";
}

function defensiveMultiplier(attackingType, defendingTypes){
  let mult=1;
  defendingTypes.forEach(defType=>{
    const chart=TYPE_CHART[attackingType]||{};
    const factor=chart[defType]===undefined?1:chart[defType];
    mult*=factor;
  });
  return mult;
}

function fillMatchupTypes(id,types){
  const el=document.getElementById(id);
  if(!el)return;
  el.innerHTML=types.length
    ? types.map(t=>typeIconHtml(t,true)).join("")
    : '<span class="matchup-empty">Nenhum</span>';
}


let lastIncomingDamageCalculation=null;

function parseDamageFormula(formula){
  const raw=String(formula||"")
    .toLowerCase()
    .replace(/\s+/g,"")
    .replace(/−/g,"-");

  if(!raw)throw new Error("Digite uma fórmula de dano.");

  const normalized=raw[0]==="-"?raw:"+"+raw;
  const tokens=normalized.match(/[+-](?:\d*d6|\d+)/g);

  if(!tokens || tokens.join("")!==normalized){
    throw new Error("Use uma fórmula como 4d6 + 4d6 + 10.");
  }

  const terms=tokens.map(token=>{
    const sign=token[0]==="-"?-1:1;
    const body=token.slice(1);

    if(body.endsWith("d6")){
      const countText=body.slice(0,-2);
      const count=(countText===""?1:Number(countText))*sign;
      if(!Number.isFinite(count))throw new Error("Fórmula de dados inválida.");
      return {kind:"dice",value:count,raw:token};
    }

    const value=Number(body)*sign;
    if(!Number.isFinite(value))throw new Error("Valor fixo inválido.");
    return {kind:"fixed",value,raw:token};
  });

  const positiveDice=terms.filter(t=>t.kind==="dice" && t.value>0);
  const firstBaseTerm=positiveDice[0]||null;

  const baseDice=firstBaseTerm?firstBaseTerm.value:0;
  let usedBase=false;
  let bonusDice=0;
  let fixed=0;

  terms.forEach(term=>{
    if(term.kind==="dice"){
      if(term===firstBaseTerm && !usedBase){
        usedBase=true;
      }else{
        bonusDice+=term.value;
      }
    }else{
      fixed+=term.value;
    }
  });

  return {
    original:formula,
    terms,
    baseDice:Math.max(0,baseDice),
    bonusDice,
    fixed
  };
}

function incomingMatchupInfo(mult){
  if(mult===0)return {label:"Imunidade • 0×",className:"immune"};
  if(mult>=4)return {label:"Super Efetivo • 4×",className:"super"};
  if(mult===2)return {label:"Efetivo • 2×",className:"effective"};
  if(mult===.5)return {label:"Resiste • ½×",className:"resist"};
  if(mult<=.25)return {label:"Hyper Resiste • ¼×",className:"hyper"};
  return {label:"Neutro • 1×",className:"neutral"};
}

function rollD6(count){
  const rolls=[];
  for(let i=0;i<count;i++)rolls.push(Math.floor(Math.random()*6)+1);
  return rolls;
}

function calculateIncomingDamage(){
  const formula=document.getElementById("incomingDamageFormula").value;
  const damageType=normalizeTypeName(document.getElementById("incomingDamageType").value);
  const category=document.getElementById("incomingDamageCategory").value;

  if(!damageType)throw new Error("Selecione um tipo de dano válido.");

  const parsed=parseDamageFormula(formula);
  const defendingTypes=[normalizeTypeName(current.type1),normalizeTypeName(current.type2)]
    .filter(Boolean);
  const uniqueDefending=[...new Set(defendingTypes)];
  const multiplier=uniqueDefending.length
    ? defensiveMultiplier(damageType,uniqueDefending)
    : 1;

  const matchup=incomingMatchupInfo(multiplier);

  let baseDice=Math.max(0,parsed.baseDice);
  let bonusDice=Math.max(0,parsed.bonusDice);
  let fixedBonus=parsed.fixed;
  let matchupDiceAdded=0;
  let typeDicePenalty=0;
  let ignoredBonusDice=0;
  let ignoredFixedBonus=0;

  if(multiplier===0){
    return {
      formula:parsed.original,
      damageType,
      category,
      multiplier,
      matchup,
      baseDice,
      originalBonusDice:bonusDice,
      originalFixedBonus:fixedBonus,
      finalDice:0,
      finalFixed:0,
      defenseDice:0,
      defenseFixed:0,
      appliedDefenseDice:0,
      appliedDefenseFixed:0,
      rolls:[],
      diceRollTotal:0,
      subtotal:0,
      damage:0,
      ruleText:"Imunidade de tipo: nenhum dano recebido."
    };
  }

  if(multiplier>=4){
    matchupDiceAdded=2;
  }else if(multiplier===2){
    matchupDiceAdded=1;
  }else if(multiplier===.5){
    const keptBonusDice=Math.floor(bonusDice/2);
    ignoredBonusDice=bonusDice-keptBonusDice;
    bonusDice=keptBonusDice;
    typeDicePenalty=1;
  }else if(multiplier<=.25){
    ignoredBonusDice=bonusDice;
    ignoredFixedBonus=fixedBonus;
    bonusDice=0;
    fixedBonus=0;
    typeDicePenalty=2;
  }

  let diceBeforeDefense=Math.max(0,baseDice+bonusDice+matchupDiceAdded-typeDicePenalty);
  let fixedBeforeDefense=fixedBonus;

  let defenseDice=0;
  let defenseFixed=0;

  if(category==="physical"){
    const reduction=statDice(combatEffectiveStat(current,"def"));
    defenseDice=reduction.dice;
    defenseFixed=reduction.fixed;
  }else if(category==="special"){
    const reduction=statDice(combatEffectiveStat(current,"spd"));
    defenseDice=reduction.dice;
    defenseFixed=reduction.fixed;
  }

  let appliedDefenseDice=defenseDice;
  let appliedDefenseFixed=defenseFixed;

  if(multiplier>=4){
    appliedDefenseDice=0;
    appliedDefenseFixed=0;
  }else if(multiplier===2){
    appliedDefenseDice=Math.floor(defenseDice/2);
    appliedDefenseFixed=Math.floor(defenseFixed/2);
  }

  let finalDice=Math.max(0,diceBeforeDefense-appliedDefenseDice);

  // Regra geral do sistema: dano em dados não cai abaixo de 1d6
  // quando o ataque possuía dados e não foi anulado por imunidade.
  const hadDamageDice=(baseDice+Math.max(0,parsed.bonusDice))>0;
  if(hadDamageDice && finalDice<=0)finalDice=1;

  const rolls=rollD6(finalDice);
  const diceRollTotal=rolls.reduce((sum,v)=>sum+v,0);
  const subtotal=Math.max(0,diceRollTotal+fixedBeforeDefense);
  const damage=Math.max(0,subtotal-appliedDefenseFixed);

  const ruleParts=[];

  if(multiplier>=4){
    ruleParts.push("+2d6 pela fraqueza 4×");
    if(category!=="none")ruleParts.push("redução defensiva ignorada");
  }else if(multiplier===2){
    ruleParts.push("+1d6 pela fraqueza 2×");
    if(category!=="none")ruleParts.push("apenas metade da redução defensiva aplicada");
  }else if(multiplier===.5){
    ruleParts.push(`-1d6 pela resistência ½×`);
    if(ignoredBonusDice>0)ruleParts.push(`${ignoredBonusDice}d6 bônus ignorados`);
  }else if(multiplier<=.25){
    ruleParts.push("-2d6 pela Hyper Resistência ¼×");
    if(ignoredBonusDice>0)ruleParts.push(`${ignoredBonusDice}d6 bônus ignorados`);
    if(ignoredFixedBonus!==0)ruleParts.push(`${ignoredFixedBonus} de dano bônus fixo ignorado`);
    ruleParts.push("somente a base do Power foi considerada");
  }else{
    ruleParts.push("dano neutro");
  }

  if(category==="physical" && appliedDefenseDice){
    ruleParts.push(`DEF aplicou -${appliedDefenseDice}d6`);
  }
  if(category==="special" && appliedDefenseDice){
    ruleParts.push(`SP.DEF aplicou -${appliedDefenseDice}d6`);
  }
  if(appliedDefenseFixed){
    ruleParts.push(`-${appliedDefenseFixed} de redução fixa defensiva`);
  }

  return {
    formula:parsed.original,
    damageType,
    category,
    multiplier,
    matchup,
    baseDice,
    originalBonusDice:Math.max(0,parsed.bonusDice),
    originalFixedBonus:parsed.fixed,
    ignoredBonusDice,
    ignoredFixedBonus,
    matchupDiceAdded,
    typeDicePenalty,
    diceBeforeDefense,
    fixedBeforeDefense,
    defenseDice,
    defenseFixed,
    appliedDefenseDice,
    appliedDefenseFixed,
    finalDice,
    finalFixed:fixedBeforeDefense,
    rolls,
    diceRollTotal,
    subtotal,
    damage,
    ruleText:ruleParts.join(" • ")
  };
}

function renderIncomingDamageCalculation(calc,applied=false,hpBefore=null,hpAfter=null){
  const result=document.getElementById("incomingDamageResult");
  const total=document.getElementById("incomingDamageTotal");
  const matchup=document.getElementById("incomingDamageMatchup");
  const breakdown=document.getElementById("incomingDamageBreakdown");
  const hpChange=document.getElementById("incomingDamageHpChange");

  result.hidden=false;
  total.textContent=calc.damage;
  matchup.textContent=`${calc.damageType} • ${calc.matchup.label}`;

  const categoryLabel=
    calc.category==="physical"?"Físico • DEF":
    calc.category==="special"?"Especial • SP.DEF":
    "Somente Tipagem";

  const diceFormula=calc.finalDice>0
    ? `${calc.finalDice}d6${calc.finalFixed?` + ${calc.finalFixed}`:""}`
    : `${calc.finalFixed||0}`;

  breakdown.innerHTML=`
    <div><b>Entrada:</b> ${esc(calc.formula)} • ${esc(categoryLabel)}</div>
    <div><b>Base interpretada:</b> ${calc.baseDice}d6 • <b>Bônus:</b> ${calc.originalBonusDice}d6${calc.originalFixedBonus?` + ${calc.originalFixedBonus}`:""}</div>
    <div><b>Após Tipagem/Defesa:</b> ${esc(diceFormula)}</div>
    <div><b>Regra aplicada:</b> ${esc(calc.ruleText)}</div>
    ${calc.rolls.length?`
      <div class="damage-rolls">
        ${calc.rolls.map((roll,index)=>`<span class="damage-die" title="d6 ${index+1}">${roll}</span>`).join("")}
      </div>
      <div style="margin-top:6px"><b>Dados:</b> ${calc.diceRollTotal}${calc.finalFixed?` + ${calc.finalFixed}`:""}${calc.appliedDefenseFixed?` - ${calc.appliedDefenseFixed}`:""} = <b>${calc.damage}</b></div>
    `:""}
  `;

  if(applied){
    hpChange.hidden=false;
    hpChange.innerHTML=`🩸 <b>${esc(current.name)}</b> recebeu <b>${calc.damage}</b> de dano. Vida Atual: <b>${hpBefore}</b> → <b>${hpAfter}</b>.`;
  }else{
    hpChange.hidden=true;
    hpChange.textContent="";
  }
}

function calculateIncomingDamagePreview(){
  try{
    lastIncomingDamageCalculation=calculateIncomingDamage();
    renderIncomingDamageCalculation(lastIncomingDamageCalculation,false);
  }catch(err){
    showToast(err.message||"Não foi possível calcular o dano.");
  }
}

function applyIncomingDamage(){
  try{
    // Sempre rola novamente ao clicar em Receber Dano.
    const calc=calculateIncomingDamage();
    lastIncomingDamageCalculation=calc;

    const hpBefore=Math.max(0,Number(current.currentHp||0));
    const hpAfter=Math.max(0,hpBefore-Number(calc.damage||0));

    current.currentHp=hpAfter;
    setVal("currentHp",hpAfter);
    updateHp();
    renderIncomingDamageCalculation(calc,true,hpBefore,hpAfter);
    debouncedSave();

    if(calc.damage<=0){
      showToast(`${current.name} não recebeu dano.`);
    }else{
      showToast(`${current.name} recebeu ${calc.damage} de dano.`);
    }
  }catch(err){
    showToast(err.message||"Não foi possível aplicar o dano.");
  }
}

function populateIncomingDamageTypes(){
  const select=document.getElementById("incomingDamageType");
  if(!select)return;
  const previous=select.value||"Normal";
  select.innerHTML=POKEMON_TYPES
    .map(type=>`<option value="${type}" ${type===previous?"selected":""}>${type}</option>`)
    .join("");
}

function renderTypeMatchups(){
  const defending=[normalizeTypeName(current.type1),normalizeTypeName(current.type2)].filter(Boolean);
  const unique=[...new Set(defending)];
  const groups={super:[],effective:[],resist:[],hyper:[],immune:[]};

  if(!unique.length){
    ["superEffectiveTypes","effectiveTypes","resistTypes","hyperResistTypes","immuneTypes"]
      .forEach(id=>fillMatchupTypes(id,[]));
    return;
  }

  POKEMON_TYPES.forEach(atkType=>{
    const mult=defensiveMultiplier(atkType,unique);
    if(mult===0) groups.immune.push(atkType);
    else if(mult>=4) groups.super.push(atkType);
    else if(mult===2) groups.effective.push(atkType);
    else if(mult===.5) groups.resist.push(atkType);
    else if(mult<=.25) groups.hyper.push(atkType);
  });

  fillMatchupTypes("superEffectiveTypes",groups.super);
  fillMatchupTypes("effectiveTypes",groups.effective);
  fillMatchupTypes("resistTypes",groups.resist);
  fillMatchupTypes("hyperResistTypes",groups.hyper);
  fillMatchupTypes("immuneTypes",groups.immune);
}
const MOVE_MEMORY_UI_KEY="pokemon_move_memory_ui_v1";
let moveMemoryUi=(()=>{
  try{
    const saved=JSON.parse(localStorage.getItem(MOVE_MEMORY_UI_KEY)||"{}");
    return {collapsed:!!saved.collapsed,expanded:false};
  }catch(err){
    return {collapsed:false,expanded:false};
  }
})();

function saveMoveMemoryUi(){
  localStorage.setItem(MOVE_MEMORY_UI_KEY,JSON.stringify({collapsed:!!moveMemoryUi.collapsed}));
}

function applyMoveMemoryUi(){
  const panel=document.getElementById("moveMemoryPanel");
  const backdrop=document.getElementById("memoryPanelBackdrop");
  const collapseBtn=document.getElementById("collapseMemoryBtn");
  const expandBtn=document.getElementById("expandMemoryBtn");
  if(!panel)return;

  panel.classList.toggle("collapsed",moveMemoryUi.collapsed && !moveMemoryUi.expanded);
  panel.classList.toggle("expanded",moveMemoryUi.expanded);
  backdrop?.classList.toggle("open",moveMemoryUi.expanded);
  document.body.classList.toggle("memory-panel-expanded",moveMemoryUi.expanded);

  if(collapseBtn){
    collapseBtn.textContent=moveMemoryUi.collapsed?"+":"−";
    collapseBtn.title=moveMemoryUi.collapsed?"Abrir Memória de Moves":"Minimizar Memória de Moves";
    collapseBtn.setAttribute("aria-label",collapseBtn.title);
  }
  if(expandBtn){
    expandBtn.textContent=moveMemoryUi.expanded?"↙":"⤢";
    expandBtn.title=moveMemoryUi.expanded?"Restaurar tamanho":"Ampliar Memória de Moves";
    expandBtn.setAttribute("aria-label",expandBtn.title);
  }
}

function toggleMoveMemoryCollapsed(){
  if(moveMemoryUi.expanded)return;
  moveMemoryUi.collapsed=!moveMemoryUi.collapsed;
  saveMoveMemoryUi();
  applyMoveMemoryUi();
}

function toggleMoveMemoryExpanded(){
  moveMemoryUi.expanded=!moveMemoryUi.expanded;
  if(moveMemoryUi.expanded)moveMemoryUi.collapsed=false;
  applyMoveMemoryUi();
}

function renderMoves(){
  applyMoveMemoryUi();

  let changed=repairPokemonMoves(current);

  current.moves.forEach(m=>{
    if(isMoveLevelLocked(m) && m.active){
      m.active=false;
      changed=true;
    }
  });

  const autoMoves=current.moves.filter(m=>m.autoLearnset);
  const availableAuto=autoMoves.filter(m=>!isMoveLevelLocked(m)).length;
  const futureAuto=autoMoves.filter(m=>isMoveLevelLocked(m)).length;

  const summary=document.getElementById("learnsetSummary");
  const helper=document.getElementById("learnsetHelper");

  if(summary){
    summary.textContent=autoMoves.length
      ?`${availableAuto} disponíveis • ${futureAuto} futuros`
      :"Golpes Aprendidos";
  }

  if(helper){
    const version=current.apiData?.learnsetVersionGroup;
    helper.textContent=autoMoves.length
      ?`Movepool automática por nível${version?` • referência: ${prettyName(version)}`:""}. Moves acima do nível atual permanecem bloqueados até o pré-requisito ser alcançado.`
      :"Pokémon oficiais carregam automaticamente seus Moves aprendidos por nível. Moves futuros ficam na memória, mas bloqueados até alcançar o nível necessário.";
  }

  const activeBox=document.getElementById("activeMoves");
  const memoryBox=document.getElementById("memoryMoves");
  if(!activeBox || !memoryBox)return;

  const search=String(document.getElementById("memorySearch")?.value||"").trim().toLowerCase();

  const active=current.moves.filter(m=>m.active && !isMoveLevelLocked(m)).slice(0,5);
  const activeCount=document.getElementById("activeCount");
  if(activeCount)activeCount.textContent=String(active.length);

  activeBox.innerHTML=active.length
    ?""
    :'<div class="empty-state">Nenhum Move ativo. Equipe golpes pela Memória de Moves.</div>';
  active.forEach(m=>activeBox.appendChild(makeMoveCard(m,true)));

  const filtered=current.moves
    .filter(m=>{
      if(!search)return true;
      return [
        m.name,
        m.type,
        m.category,
        translateMoveEffectPt(m.description||"")
      ].filter(Boolean).join(" ").toLowerCase().includes(search);
    })
    .sort((a,b)=>{
      const lockA=isMoveLevelLocked(a)?1:0;
      const lockB=isMoveLevelLocked(b)?1:0;
      if(lockA!==lockB)return lockA-lockB;

      const levelA=a.autoLearnset?Number(a.learnLevel||0):-1;
      const levelB=b.autoLearnset?Number(b.learnLevel||0):-1;
      if(levelA!==levelB)return levelA-levelB;

      return String(a.name||"").localeCompare(String(b.name||""),"en");
    });

  memoryBox.innerHTML=filtered.length
    ?""
    :'<div class="empty-state">Nenhum Move encontrado.</div>';
  filtered.forEach(m=>memoryBox.appendChild(makeMoveCard(m,false)));

  renderPageOverview();

  if(changed)debouncedSave();
}

const MOVE_TYPE_PALETTE={"Normal":["#8d969d","#4f575d"],"Fire":["#e04436","#861b14"],"Water":["#2e82d5","#174f8c"],"Electric":["#e2b814","#806800"],"Grass":["#48a047","#276228"],"Ice":["#54b7ca","#267484"],"Fighting":["#cf563a","#7c2a1c"],"Poison":["#a655b9","#612d6c"],"Ground":["#ae7442","#674123"],"Flying":["#789ed3","#405f91"],"Psychic":["#de5b88","#8c2e53"],"Bug":["#899e34","#4f5e1b"],"Rock":["#a28a50","#60502b"],"Ghost":["#6663a0","#393662"],"Dragon":["#526db0","#2d4070"],"Dark":["#514b59","#28242c"],"Steel":["#5c8798","#304f5c"],"Fairy":["#dd83b8","#8d456e"]};

function moveTypePalette(type){
  const normalized=normalizeTypeName(type)||"Normal";
  const colors=MOVE_TYPE_PALETTE[normalized]||MOVE_TYPE_PALETTE.Normal;
  return {main:colors[0],dark:colors[1]};
}

function mixHexWithWhite(hex,amount=.14){
  const value=String(hex||"#888888").replace("#","");
  const full=value.length===3?value.split("").map(x=>x+x).join(""):value;
  const number=parseInt(full,16);
  const r=(number>>16)&255;
  const g=(number>>8)&255;
  const b=number&255;
  const mix=channel=>Math.round(channel+(255-channel)*amount);
  return `rgb(${mix(r)},${mix(g)},${mix(b)})`;
}

function applyMoveTypePalette(card,type,activeView){
  const palette=moveTypePalette(type);
  card.style.setProperty("--move-type",palette.main);
  card.style.setProperty("--move-type-dark",palette.dark);
  card.dataset.moveType=normalizeTypeName(type)||"Normal";

  if(activeView){
    card.style.background=`linear-gradient(145deg,${mixHexWithWhite(palette.main)},${palette.main})`;
    card.style.borderColor=palette.dark;
    card.style.boxShadow=`inset 0 2px 0 rgba(255,255,255,.25), inset 0 -3px 0 rgba(0,0,0,.18), 3px 3px 0 ${palette.dark}`;
  }
}

function moveOffensiveBonus(move){
  const category=String(move?.category||"").toLowerCase();

  if(category==="physical"){
    const effective=combatEffectiveStat(current,"atk");
    const stage=combatStageTotal(current,"atk");
    const bonus=statDice(effective);
    return stage
      ?`ATK ${effective} (${combatStageSigned(stage)}) • +${bonus.dice}d6${bonus.fixed?` +${bonus.fixed}`:""}`
      :`ATK +${bonus.dice}d6${bonus.fixed?` +${bonus.fixed}`:""}`;
  }

  if(category==="special"){
    const effective=combatEffectiveStat(current,"spa");
    const stage=combatStageTotal(current,"spa");
    const bonus=statDice(effective);
    return stage
      ?`SP.ATK ${effective} (${combatStageSigned(stage)}) • +${bonus.dice}d6${bonus.fixed?` +${bonus.fixed}`:""}`
      :`SP.ATK +${bonus.dice}d6${bonus.fixed?` +${bonus.fixed}`:""}`;
  }

  return "";
}

function makeMoveCard(m,activeView){
  const locked=isMoveLevelLocked(m);
  const card=document.createElement("div");
  const moveTypeClass=normalizeApiSlug(normalizeTypeName(m.type)||"normal");

  card.className="move-card"+(locked?" locked-move":"")+` move-type-${moveTypeClass}`;
  card.dataset.moveId=String(m.id||"");
  applyMoveTypePalette(card,m.type,activeView);

  const offensiveBonus=moveOffensiveBonus(m);
  const accuracyInfo=effectiveMoveAccuracy(m);
  const dice=powerToDice(m.power);
  const powerText=m.powerLabel||Number(m.power||0);
  const accuracyText=accuracyInfo.label;
  const description=translateMoveEffectPt(m.description||"");

  card.innerHTML=`
    <div class="move-card-top">
      <div>
        <div class="move-name">${esc(m.name)}</div>
        <div class="move-meta">
          ${typeIconHtml(m.type,true)}
          <span class="tag combat-summary-tag">${esc(m.category||"—")}</span>
          <span class="tag combat-summary-tag">Power ${esc(String(powerText))}</span>
          ${m.powerLabel==="—"||dice==="—"?"":`<span class="tag combat-summary-tag">${dice} base</span>`}
          <span class="tag combat-detail-tag${accuracyInfo.changed?" combat-stage-accuracy-adjusted":""}" title="${escAttr(accuracyInfo.detail)}">Acc. ${esc(String(accuracyText))}</span>
          ${offensiveBonus?`<span class="tag damage-stat-bonus combat-summary-tag">${esc(offensiveBonus)}</span>`:""}
          ${m.source==="Sistema"?'<span class="tag combat-detail-tag">Sistema / Rework</span>':""}
          ${m.autoLearnset?`<span class="tag learn-level-tag combat-detail-tag">${esc(moveLearnLevelLabel(m))}</span>`:""}
          ${m.autoLearnset
            ?locked
              ?`<span class="tag future-level-tag combat-detail-tag">🔒 Requer Lv. ${Number(m.learnLevel||0)}</span>`
              :'<span class="tag available-level-tag combat-detail-tag">✓ Disponível</span>'
            :""}
          ${(m.tags||[]).slice(0,3).map(tag=>`<span class="tag combat-detail-tag">${esc(tag)}</span>`).join("")}
          ${Number(m.effectChance||0)>0?`<span class="tag effect-chance-tag">Efeito ${Number(m.effectChance||0)}%</span>`:""}
        </div>
        ${description?`<div class="move-description">${esc(description)}</div>`:""}
      </div>

      <div class="move-actions">
        <button class="btn small edit" type="button">Editar</button>
        ${canUseZMoveWithMove(m)?'<button class="btn small z-move-action" type="button">Z-Move</button>':""}
        <button class="btn small toggle" type="button">${m.active?"Retirar":locked?`🔒 Lv. ${Number(m.learnLevel||0)}`:"Equipar"}</button>
        ${activeView?"":'<button class="btn small danger remove" type="button">✕</button>'}
      </div>
    </div>
  `;

  card.querySelector(".edit").onclick=event=>{
    event.preventDefault();
    event.stopPropagation();
    openMoveEditModal(String(m.id));
  };

  const zAction=card.querySelector(".z-move-action");
  if(zAction){
    zAction.onclick=event=>{
      event.preventDefault();
      event.stopPropagation();
      consumeZMove(m.name);
    };
  }

  card.querySelector(".toggle").onclick=event=>{
    event.preventDefault();
    event.stopPropagation();

    if(!m.active && isMoveLevelLocked(m)){
      showToast(`${m.name} requer Lv. ${Number(m.learnLevel||0)}.`);
      return;
    }

    if(!m.active && current.moves.filter(x=>x.active).length>=5){
      showToast("Limite de 5 Moves ativos.");
      return;
    }

    m.active=!m.active;
    renderMoves();
    debouncedSave();
  };

  const remove=card.querySelector(".remove");
  if(remove){
    remove.onclick=event=>{
      event.preventDefault();
      event.stopPropagation();
      current.moves=current.moves.filter(x=>String(x.id)!==String(m.id));
      renderMoves();
      debouncedSave();
    };
  }

  return card;
}

