/* ==============================================================
   JSON PORTÁTIL — PRESERVA ARTES DOS POKÉMON, TREINADOR E MEGAS.
   Um único .json carrega as imagens locais como data:image/... .
   Para URLs externas, tenta incorporar a arte ao exportar (CORS).
   ============================================================== */
const portablePendingImages={manual:"",mega:""};

function portableReadImageFile(file){
  return new Promise((resolve,reject)=>{
    if(!file || !String(file.type||"").startsWith("image/")){
      reject(new Error("Escolha um arquivo de imagem PNG, JPG, WEBP ou GIF."));
      return;
    }
    const reader=new FileReader();
    reader.onload=()=>resolve(String(reader.result||""));
    reader.onerror=()=>reject(new Error("Não foi possível abrir a imagem local."));
    reader.readAsDataURL(file);
  });
}

function portableImageFields(root){
  const entries=[];
  const seen=new WeakSet();
  const isImageKey=/^(?:imageUrl|shinyImageUrl|imageURI|spriteUrl|portraitUrl|artworkUrl|photo|dataUrl)$/i;
  const walk=(node,path)=>{
    if(!node || typeof node!=="object" || seen.has(node))return;
    seen.add(node);
    for(const [key,value] of Object.entries(node)){
      const childPath=path?`${path}.${key}`:key;
      if(typeof value==="string" && isImageKey.test(key) && value.trim()){
        // dataUrl também pode conter outros dados; seleciona só imagem.
        if(key.toLowerCase()!=="dataurl" || /^(?:data:image\/|https?:\/\/|blob:)/i.test(value)){
          entries.push({owner:node,key,url:value.trim(),path:childPath});
        }
      }else if(value && typeof value==="object"){
        walk(value,childPath);
      }
    }
  };
  walk(root,"");
  return entries;
}

async function portableFetchImage(url){
  if(!/^https?:\/\//i.test(url))throw new Error("Apenas URLs http/https podem ser incorporadas.");
  const controller=new AbortController();
  const timeout=setTimeout(()=>controller.abort(),6500);
  try{
    const response=await fetch(url,{mode:"cors",signal:controller.signal,credentials:"omit"});
    if(!response.ok)throw new Error(`HTTP ${response.status}`);
    const type=(response.headers.get("content-type")||"").toLowerCase();
    const size=Number(response.headers.get("content-length")||0);
    if(size>12*1024*1024)throw new Error("Arte externa maior que 12 MB.");
    if(type && !type.startsWith("image/"))throw new Error("Endereço não retornou uma imagem.");
    const blob=await response.blob();
    if(blob.size>12*1024*1024 || !blob.type.startsWith("image/")){
      throw new Error("Arquivo remoto inválido ou maior que 12 MB.");
    }
    return await portableReadImageFile(new File([blob],"artwork",{type:blob.type}));
  }finally{
    clearTimeout(timeout);
  }
}

async function portableBuildExport(){
  // Exporta CÓPIA. Nunca altera a URL nem as artes da ficha que está aberta.
  const copy=JSON.parse(JSON.stringify(state));
  const entries=portableImageFields(copy);
  const remote=new Map();
  const failures=[];
  for(const entry of entries){
    if(/^https?:\/\//i.test(entry.url)){
      const group=remote.get(entry.url)||[];
      group.push(entry);
      remote.set(entry.url,group);
    }else if(!/^data:image\//i.test(entry.url)){
      failures.push(entry.path);
    }
  }
  const jobs=Array.from(remote.entries());
  let position=0;
  async function worker(){
    while(position<jobs.length){
      const [url,group]=jobs[position++];
      try{
        const dataUrl=await portableFetchImage(url);
        group.forEach(entry=>entry.owner[entry.key]=dataUrl);
      }catch(error){
        console.warn("Imagem externa não incorporada:",url,error);
        failures.push(...group.map(entry=>entry.path));
      }
    }
  }
  await Promise.all(Array.from({length:Math.min(3,jobs.length)},()=>worker()));
  const embedded=portableImageFields(copy).filter(entry=>/^data:image\//i.test(entry.owner[entry.key]));
  return {copy,embedded:embedded.length,unresolved:failures};
}

function portableBindImageUpload(buttonId,inputId,textId,targetKey){
  const button=document.getElementById(buttonId);
  const input=document.getElementById(inputId);
  const text=document.getElementById(textId);
  const target=document.getElementById(targetKey);
  if(!button||!input||!target)throw new Error(`Campo de arte não encontrado: ${targetKey}`);
  button.addEventListener("click",()=>input.click());
  input.addEventListener("change",async event=>{
    const file=event.target.files?.[0];
    if(!file)return;
    try{
      portablePendingImages[textId==="manualPortableImageNote"?"manual":"mega"]=await portableReadImageFile(file);
      target.value="[imagem local incluída no JSON]";
      if(text)text.textContent=`✓ ${file.name} — arte incluída no JSON`;
      showToast("✓ Imagem local pronta para entrar no JSON.");
    }catch(error){
      showToast(error.message||"Não foi possível abrir esta imagem.");
      input.value="";
    }
  });
  target.addEventListener("input",()=>{
    const scope=textId==="manualPortableImageNote"?"manual":"mega";
    portablePendingImages[scope]="";
    if(text)text.textContent="URL externa: a exportação tentará incluir a imagem. Para garantir, envie o arquivo local.";
  });
}
portableBindImageUpload("manualPortableImageBtn","manualPortableImageInput","manualPortableImageNote","manualImageUrl");
portableBindImageUpload("megaPortableImageBtn","megaPortableImageInput","megaPortableImageNote","customMegaImage");

/* Nome do treinador e data local no arquivo exportado; sem alterar o conteúdo do JSON. */
function portableTrainerExportFileName(exportData){
  const typedName=String(exportData?.trainer?.name ?? "").trim();
  const safeName=typedName
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 48)
    .replace(/-+$/g, "") || "treinador";
  const now=new Date();
  const pad=value=>String(value).padStart(2,"0");
  const date=`${now.getFullYear()}-${pad(now.getMonth()+1)}-${pad(now.getDate())}`;
  return `pokemon-v5-${safeName}-${date}.json`;
}

async function exportAll(){
  const button=document.getElementById("exportBtn");
  if(button?.disabled)return;
  if(button){button.disabled=true;button.textContent="Preparando JSON...";}
  try{
    await flushLocalSave();
    const {copy,embedded,unresolved}=await portableBuildExport();
    const blob=new Blob([JSON.stringify(copy,null,2)],{type:"application/json;charset=utf-8"});
    const url=URL.createObjectURL(blob);
    const anchor=document.createElement("a");
    anchor.href=url;
    anchor.download=portableTrainerExportFileName(copy);
    document.body.appendChild(anchor);
    anchor.click();
    anchor.remove();
    // Revogar só depois que o navegador iniciar o download (especialmente Android).
    setTimeout(()=>URL.revokeObjectURL(url),120000);
    if(unresolved.length){
      const details=unresolved.slice(0,8).join("\n• ");
      alert(`JSON exportado com ${embedded} imagem(ns) embutida(s).\n\nATENÇÃO: ${unresolved.length} imagem(ns) externa(s) não puderam ser incorporadas (bloqueio do site/CORS ou URL inválida). Elas ainda estão como links e podem não abrir offline.\n\n• ${details}\n\nPara garantir, use "Imagem local" nessas artes e exporte novamente.`);
    }else{
      showToast(`✓ JSON exportado com ${embedded} imagem(ns) incluída(s).`);
    }
  }catch(error){
    console.error("Erro ao exportar JSON com artes:",error);
    alert("Não foi possível exportar o JSON. Tente novamente e verifique as imagens adicionadas.");
  }finally{
    if(button){button.disabled=false;button.textContent="Exportar JSON";}
  }
}
function importAll(file){
  const reader=new FileReader();
  reader.onload=async()=>{
    try{
      const parsed=JSON.parse(String(reader.result||""));
      if(!validSavedState(parsed))throw new Error("O JSON não contém fichas Pokémon válidas.");
      const prepared=normalizeLocalSavedState(parsed);
      const included=portableImageFields(prepared).filter(e=>/^data:image\//i.test(e.url)).length;
      if(!await flushLocalSave({reason:'Antes de importar JSON'}))throw new Error("Guarde ou recupere o save atual antes de importar. Suas fichas não foram substituídas.");
      applyRestoredLocalState(prepared);
      const saved=await flushLocalSave({reason:'Importação de JSON'});
      showToast(saved?`✓ JSON importado e salvo! ${included} imagem(ns) restaurada(s).`:'JSON importado na tela. O save está pendente; confira a central de save.');
    }catch(error){
      console.error("Erro ao importar ficha:",error);
      alert(error.message||"Arquivo JSON inválido para esta ficha.");
    }finally{document.getElementById('importInput').value='';}
  };
  reader.onerror=()=>alert("Não foi possível ler o arquivo JSON.");
  reader.readAsText(file);
}

function esc(s){return String(s??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#039;"}[m]))}
function escAttr(s){return esc(s)}

bindValue("pokemonName","name");
document.getElementById("level").addEventListener("change",e=>{
  const requestedLevel=Math.max(1,Math.min(100,Number(e.target.value||1)));
  const oldLevel=Number(current.level||1);
  ensureProgression(current);

  if(current.progression.auto && requestedLevel>oldLevel){
    let stopped=false;
    let stopReason="";
    const redistributionNotes=[];

    while(Number(current.level||1)<requestedLevel){
      const nextLevel=Number(current.level||1)+1;

      if(nextLevel<=5){
        advanceOneLevelWithPreset(nextLevel);
        continue;
      }

      const plan=buildPriorityAllocationForLevel(nextLevel);

      if(plan.total!==6){
        stopped=true;
        stopReason=`A progressão automática parou no Lv. ${current.level}: não existe capacidade suficiente para distribuir os 6 pontos no bloco ${plan.key}.`;
        break;
      }

      const primaryPriorities=getPriorityOrder().slice(0,2);
      const redirected=STAT_KEYS
        .filter(([stat])=>Number(plan.allocation[stat]||0)>0 && !primaryPriorities.includes(stat))
        .map(([stat,label])=>`${label} +${plan.allocation[stat]}`);

      if(redirected.length){
        redistributionNotes.push(`Lv. ${nextLevel}: ${redirected.join(", ")}`);
      }

      advanceOneLevelWithPreset(nextLevel,plan.allocation);
    }

    e.target.value=current.level;

    if(stopped){
      setProgressReport(stopReason);
    }else if(redistributionNotes.length){
      setProgressReport(
        `Progressão automática concluída até o Lv. ${current.level}. O sistema redirecionou pontos quando as prioridades ficaram sem espaço: `+
        redistributionNotes.slice(-10).join(" • ")
      );
    }else{
      setProgressReport(`Progressão automática concluída até o Lv. ${current.level} seguindo a ordem de prioridade.`);
    }

    renderAll();
    saveState();
    return;
  }

  current.level=requestedLevel;
  e.target.value=requestedLevel;

  if(Number(current.progression.lastAppliedLevel||0)>requestedLevel){
    current.progression.lastAppliedLevel=requestedLevel;
  }

  if(current.progression.auto && requestedLevel<oldLevel){
    setProgressReport("O nível foi reduzido manualmente, mas os atributos já aplicados não foram removidos. Ajuste os Status Atuais manualmente se necessário.");
  }

  renderNatureProgression();
  renderMoves();
  renderDrawer();
  debouncedSave();
});
