function setProgressReport(message){
  const warn=document.getElementById("progressWarning");
  const panel=document.getElementById("progressReportPanel");
  const toggle=document.getElementById("toggleProgressReportBtn");
  warn.textContent=message||"";
  if(message){
    toggle.hidden=false;
  }else{
    panel.hidden=true;
    toggle.hidden=true;
  }
}
function toggleProgressReport(){
  const panel=document.getElementById("progressReportPanel");
  const btn=document.getElementById("toggleProgressReportBtn");
  panel.hidden=!panel.hidden;
  btn.textContent=panel.hidden ? "Ver relatório da progressão" : "Ocultar relatório da progressão";
}
function addProgressHistoryEntry(nextLevel,result){
  ensureProgression(current);
  current.progression.history.push({
    id:uid(),level:Number(nextLevel),block:result?.key||blockKeyForLevel(nextLevel),
    invested:clone(result?.invested||{}),gains:clone(result?.gains||{}),
    natureName:current.natureName||"",
    naturePlus:current.naturePlus||"",natureMinus:current.natureMinus||"",
    autoPriority:!!current.progression.auto,
    priorityOrder:current.progression.auto?clone(current.progression.priorityOrder):[],
    blocked:clone(result?.blocked||[]),createdAt:new Date().toISOString()
  });
}
function renderProgressHistory(){
  ensureProgression(current);
  const list=document.getElementById("progressHistoryList"),count=document.getElementById("progressHistoryCount");
  if(!list||!count)return;
  const history=[...(current.progression.history||[])].reverse();
  count.textContent=`${history.length} ${history.length===1?"registro":"registros"}`;
  list.innerHTML=history.length?"":'<div class="empty-state">Nenhum nível confirmado no histórico ainda.</div>';
  history.forEach(entry=>{
    const investedLabels=[],gainLabels=[];
    STAT_KEYS.forEach(([stat,label])=>{
      const inv=Number(entry.invested?.[stat]||0),gain=Number(entry.gains?.[stat]||0);
      if(inv>0) investedLabels.push(`${label} +${inv}`);
      if(gain>0) gainLabels.push(`${label} +${gain}`);
    });
    const plusLabel=entry.naturePlus?(STAT_KEYS.find(x=>x[0]===entry.naturePlus)?.[1]||entry.naturePlus):"";
    const minusLabel=entry.natureMinus?(STAT_KEYS.find(x=>x[0]===entry.natureMinus)?.[1]||entry.natureMinus):"";
    const card=document.createElement("div");card.className="progress-history-card";
    card.innerHTML=`
      <div class="progress-history-top"><div>
        <div class="progress-history-level">Lv. ${Number(entry.level||0)}</div>
        <div class="progress-history-meta">Bloco ${esc(entry.block||"—")}${entry.createdAt?` • ${new Date(entry.createdAt).toLocaleDateString("pt-BR")}`:""}</div>
      </div></div>
      <div class="progress-history-gains">${(gainLabels.length?gainLabels:["Sem ganho de atributo"]).map(x=>`<span class="tag">${esc(x)}</span>`).join("")}</div>
      <div class="progress-history-note">
        Investido antes da Nature: ${esc(investedLabels.join(" • ")||"Nenhum")}.
        ${entry.natureName?` Nature: ${esc(entry.natureName)}.`:""} ${plusLabel?` +${esc(plusLabel)}.`:""} ${minusLabel?` -${esc(minusLabel)}.`:""}
        ${entry.autoPriority?`<br>Automático por prioridade: ${esc((entry.priorityOrder||[]).map(statLabel).join(" → "))}.`:""}
      </div>`;
    list.appendChild(card);
  });
}
function advanceOneLevelWithPreset(nextLevel,allocationOverride=null){
  const wasFullHp=Number(current.currentHp||0) >= Number(current.maxHp||0);

  if(nextLevel<=5){
    current.level=nextLevel;
    current.progression.lastAppliedLevel=nextLevel;
    return {applied:false,early:true,gains:{},blocked:[]};
  }

  const beforeHp=Number(current.stats.hp||0);
  const result=applyProgressForLevel(nextLevel,allocationOverride);
  addProgressHistoryEntry(nextLevel,result);
  const afterHp=Number(current.stats.hp||0);
  const hpGain=Math.max(0,afterHp-beforeHp);

  if(hpGain>0){
    current.maxHp=Number(current.maxHp||0)+hpGain;
    if(wasFullHp) current.currentHp=Number(current.currentHp||0)+hpGain;
  }

  current.level=nextLevel;
  current.progression.lastAppliedLevel=nextLevel;
  return result;
}

function confirmNextLevel(){
  ensureProgression(current);

  if(!current.progression.auto && !validatePreset(true)){
    setProgressReport("Antes de confirmar o nível, distribua exatamente 6 pontos válidos no preset. Atributos que atingiram +20 na dezena atual ficam bloqueados.");
    renderNatureProgression();
    return;
  }

  const oldLevel=Number(current.level||1);
  if(oldLevel>=100){
    setProgressReport("Este Pokémon já está no Lv. 100.");
    return;
  }

  const nextLevel=oldLevel+1;
  let autoPlan=null;

  if(current.progression.auto && nextLevel>5){
    autoPlan=buildPriorityAllocationForLevel(nextLevel);

    if(autoPlan.total!==6){
      setProgressReport(`Não foi possível distribuir automaticamente os 6 pontos no bloco ${autoPlan.key}.`);
      renderNatureProgression();
      return;
    }
  }

  const result=advanceOneLevelWithPreset(nextLevel,autoPlan?.allocation||null);
  setVal("level",nextLevel);

  if(result.early){
    setProgressReport(`Lv. ${nextLevel} confirmado. A distribuição de atributos começa no Lv. 6.`);
  }else if(current.progression.auto){
    const investedLabels=[];
    STAT_KEYS.forEach(([stat,label])=>{
      const invested=Number(result.invested?.[stat]||0);
      if(invested>0) investedLabels.push(`${label} +${invested}`);
    });
    setProgressReport(`Lv. ${nextLevel} confirmado automaticamente por prioridade: ${investedLabels.join(" • ")}.`);
  }else{
    const gainLabels=[];
    STAT_KEYS.forEach(([stat,label])=>{
      const gain=Number(result.gains?.[stat]||0);
      if(gain>0) gainLabels.push(`${label} +${gain}`);
    });
    setProgressReport(`Lv. ${nextLevel} confirmado: ${gainLabels.join(" • ") || "sem ganho de atributo"}.`);
  }

  renderAll();
  saveState();
}


function updateLevelBatchPreview(){
  const input=document.getElementById("levelBatchAmount");
  const preview=document.getElementById("levelBatchPreview");
  const button=document.getElementById("confirmMultipleLevelsBtn");
  const badge=document.getElementById("identityLevelBadge");

  if(!input||!preview||!button)return;

  const currentLevel=Math.max(1,Math.min(100,Number(current.level||1)));
  const remaining=Math.max(0,100-currentLevel);

  input.max=String(Math.max(1,remaining));

  let amount=Math.trunc(Number(input.value||1));
  amount=Math.max(1,Math.min(Math.max(1,remaining),amount));
  input.value=String(amount);

  const target=Math.min(100,currentLevel+amount);
  preview.textContent=`Lv. ${currentLevel} → Lv. ${target}`;
  button.textContent=`SUBIR +${amount}`;
  button.disabled=remaining<=0;
  input.disabled=remaining<=0;

  if(badge)badge.textContent=String(currentLevel);
}

function confirmMultipleLevels(){
  ensureProgression(current);

  const input=document.getElementById("levelBatchAmount");
  const startLevel=Math.max(1,Math.min(100,Number(current.level||1)));

  if(startLevel>=100){
    setProgressReport("Este Pokémon já está no Lv. 100.");
    updateLevelBatchPreview();
    return;
  }

  let requested=Math.trunc(Number(input?.value||1));
  requested=Math.max(1,Math.min(100-startLevel,requested));

  let applied=0;
  let stoppedReason="";
  const totalGains={hp:0,atk:0,def:0,spa:0,spd:0,spe:0};

  while(applied<requested && Number(current.level||1)<100){
    const nextLevel=Number(current.level||1)+1;
    let allocation=null;

    if(nextLevel>5){
      if(current.progression.auto){
        const autoPlan=buildPriorityAllocationForLevel(nextLevel);

        if(autoPlan.total!==6){
          stoppedReason=`A distribuição automática não conseguiu aplicar os 6 pontos no Lv. ${nextLevel}, bloco ${autoPlan.key}.`;
          break;
        }

        allocation=autoPlan.allocation;
      }else{
        if(!validatePreset(false)){
          stoppedReason=`A distribuição manual ficou inválida antes do Lv. ${nextLevel}. Redistribua os 6 pontos para continuar.`;
          break;
        }
      }
    }

    const result=advanceOneLevelWithPreset(nextLevel,allocation);

    STAT_KEYS.forEach(([stat])=>{
      totalGains[stat]+=Number(result.gains?.[stat]||0);
    });

    applied+=1;
  }

  setVal("level",current.level);

  if(applied<=0){
    setProgressReport(stoppedReason||"Nenhum nível foi aplicado.");
    renderNatureProgression();
    return;
  }

  const gainLabels=STAT_KEYS
    .filter(([stat])=>Number(totalGains[stat]||0)>0)
    .map(([stat,label])=>`${label} +${totalGains[stat]}`);

  const mode=current.progression.auto
    ?"progressão automática por prioridade"
    :"preset manual";

  let report=`Treinamento rápido concluído: Lv. ${startLevel} → Lv. ${current.level} usando ${mode}.`;

  if(gainLabels.length){
    report+=` Ganhos totais: ${gainLabels.join(" • ")}.`;
  }

  if(stoppedReason){
    report+=` Processo interrompido: ${stoppedReason}`;
  }

  setProgressReport(report);
  renderAll();
  saveState();

  showToast(`${current.name||"Pokémon"} subiu ${applied} nível${applied===1?"":"is"}!`);
}


