/* Desenha o que ficou pendente assim que a página aparece (antes das animações). */
(function(){
  const original=window.setActiveSheetPage;
  if(typeof original!=="function")return;
  window.setActiveSheetPage=function(pageId){
    const result=original.apply(this,arguments);
    window.hhFlushDeferred?.(pageId);
    return result;
  };
})();
